QUESTIONS.push({"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-pharmacology", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~21–~22; transcript 9/22", "quote": "Pharmacology: “the study of the interaction of “Drugs” with biological systems” ... Which, What, & Where? How much? Smallest dose => Desired effect?", "id": "T-pharmacology-1", "stem": "Which term fits this situation? A diagram splits the subject in two: one half is absorption, distribution, metabolism and excretion, the other is the drug meeting its receptor and producing the physiological response.", "options": [{"t": "Pharmacology", "correct": true, "why": "This situation is pharmacology: The whole field: what the drug does and how much reaches it."}, {"t": "Site of action", "correct": false, "why": "Site of action (SOA) would be: Where the receptor is located; with the mechanism, it predicts effect and side effects."}, {"t": "Side effect", "correct": false, "why": "Side effect (ADR) would be: An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known."}, {"t": "Withdrawal syndrome", "correct": false, "why": "Withdrawal syndrome would be: The opposite of what the drug produced, appearing when the drug is stopped."}], "teach": "The whole field: what the drug does and how much reaches it. The pharmacology diagram splits it in two: pharmacokinetics (absorption, distribution, metabolism, excretion) and pharmacodynamics (drug–receptor signaling that gives the physiological response)."},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-pharmacology", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~21–~22; transcript 9/22", "quote": "Pharmacology: “the study of the interaction of “Drugs” with biological systems” ... Which, What, & Where? How much? Smallest dose => Desired effect?", "id": "T-pharmacology-2", "stem": "Pharmacology means:", "options": [{"t": "The whole field: what the drug does and how much reaches it.", "correct": true, "why": "That is pharmacology."}, {"t": "Where the receptor is located; with the mechanism, it predicts effect and side effects.", "correct": false, "why": "That is site of action (soa), not pharmacology."}, {"t": "An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known.", "correct": false, "why": "That is side effect (adr), not pharmacology."}, {"t": "The opposite of what the drug produced, appearing when the drug is stopped.", "correct": false, "why": "That is withdrawal syndrome, not pharmacology."}], "teach": "The whole field: what the drug does and how much reaches it. The pharmacology diagram splits it in two: pharmacokinetics (absorption, distribution, metabolism, excretion) and pharmacodynamics (drug–receptor signaling that gives the physiological response).", "dupOf": "T-pharmacology-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-pharmacology", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~21–~22; transcript 9/22", "quote": "Pharmacology: “the study of the interaction of “Drugs” with biological systems” ... Which, What, & Where? How much? Smallest dose => Desired effect?", "id": "T-pharmacology-3", "stem": "Which term is defined as: The whole field (pharmacokinetics plus pharmacodynamics): the study of the interaction of drugs with biological systems: which drug, what it does and where, and how much (the smallest dose that gives the desired effect). It determines mechanisms of action, dose–response relationships, therapeutic dose, potency, minimal and maximal effect, and safety?", "options": [{"t": "Pharmacology", "correct": true, "why": "This is the definition of Pharmacology."}, {"t": "Site of action", "correct": false, "why": "Site of action (SOA): Where the receptor is located; with the mechanism, it predicts effect and side effects."}, {"t": "Side effect", "correct": false, "why": "Side effect (ADR): An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known."}, {"t": "Withdrawal syndrome", "correct": false, "why": "Withdrawal syndrome: The opposite of what the drug produced, appearing when the drug is stopped."}], "teach": "The pharmacology diagram splits it in two: pharmacokinetics (absorption, distribution, metabolism, excretion) and pharmacodynamics (drug–receptor signaling that gives the physiological response).", "dupOf": "T-pharmacology-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-pharmacodynamics", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~31; Pharmacodynamics-Day-1-2026s.pdf slide ~22; transcript 9/23", "quote": "General rules: 1) Drug must reach the site of action 2) Drug must bind to and interact with a receptor 3) Drug do not create anything, but change the ongoing phys. system", "id": "T-pharmacodynamics-1", "stem": "Which term fits this situation? Metoprolol reaches the heart, binds the β1 receptor and blocks it, and the heart rate falls; nothing new is created, an ongoing process is changed.", "options": [{"t": "Pharmacodynamics", "correct": true, "why": "This situation is pharmacodynamics (pd): How the drug interacts with the biological system: affinity and efficacy only."}, {"t": "Withdrawal syndrome", "correct": false, "why": "Withdrawal syndrome would be: The opposite of what the drug produced, appearing when the drug is stopped."}, {"t": "Pharmacokinetics", "correct": false, "why": "Pharmacokinetics (PK) would be: Absorption, distribution, metabolism, excretion: how much drug gets to the site of action."}, {"t": "Pharmacology", "correct": false, "why": "Pharmacology would be: The whole field: what the drug does and how much reaches it."}], "teach": "How the drug interacts with the biological system: affinity and efficacy only. Spoken definition: “the study of how drugs interact with the biological system.” Its two basic concepts are affinity and efficacy."},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-pharmacodynamics", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~31; Pharmacodynamics-Day-1-2026s.pdf slide ~22; transcript 9/23", "quote": "General rules: 1) Drug must reach the site of action 2) Drug must bind to and interact with a receptor 3) Drug do not create anything, but change the ongoing phys. system", "id": "T-pharmacodynamics-2", "stem": "Pharmacodynamics means:", "options": [{"t": "How the drug interacts with the biological system: affinity and efficacy only.", "correct": true, "why": "That is pharmacodynamics (pd)."}, {"t": "Absorption, distribution, metabolism, excretion: how much drug gets to the site of action.", "correct": false, "why": "That is pharmacokinetics (pk), not pharmacodynamics (pd)."}, {"t": "The whole field: what the drug does and how much reaches it.", "correct": false, "why": "That is pharmacology, not pharmacodynamics (pd)."}, {"t": "Continued exposure to the same concentration gives a diminished effect; the clinical manifestation.", "correct": false, "why": "That is tolerance, not pharmacodynamics (pd)."}], "teach": "How the drug interacts with the biological system: affinity and efficacy only. Spoken definition: “the study of how drugs interact with the biological system.” Its two basic concepts are affinity and efficacy.", "dupOf": "T-pharmacodynamics-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-pharmacodynamics", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~31; Pharmacodynamics-Day-1-2026s.pdf slide ~22; transcript 9/23", "quote": "General rules: 1) Drug must reach the site of action 2) Drug must bind to and interact with a receptor 3) Drug do not create anything, but change the ongoing phys. system", "id": "T-pharmacodynamics-3", "stem": "Which term is defined as: The study of the biochemical and physiological effects of drugs and their mechanisms of action. General rules: the drug must reach the site of action, must bind to and interact with a receptor, and does not create anything but changes the ongoing physiological system?", "options": [{"t": "Pharmacodynamics", "correct": true, "why": "This is the definition of Pharmacodynamics (PD)."}, {"t": "Withdrawal syndrome", "correct": false, "why": "Withdrawal syndrome: The opposite of what the drug produced, appearing when the drug is stopped."}, {"t": "Pharmacokinetics", "correct": false, "why": "Pharmacokinetics (PK): Absorption, distribution, metabolism, excretion: how much drug gets to the site of action."}, {"t": "Pharmacology", "correct": false, "why": "Pharmacology: The whole field: what the drug does and how much reaches it."}], "teach": "Spoken definition: “the study of how drugs interact with the biological system.” Its two basic concepts are affinity and efficacy.", "dupOf": "T-pharmacodynamics-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-pharmacokinetics", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~22–~23, ~27; transcript 9/22", "quote": "So pharmokinetics is going to be affecting how much of the drug gets to the site of action. Because that’s how it’s going to produce its effects.", "id": "T-pharmacokinetics-1", "stem": "Which term fits this situation? A drug is swallowed, absorbed in the gut, broken down by the liver on first pass, and only a fraction reaches the receptor; given intravenously, 100% is available.", "options": [{"t": "Pharmacokinetics", "correct": true, "why": "This situation is pharmacokinetics (pk): Absorption, distribution, metabolism, excretion: how much drug gets to the site of action."}, {"t": "Mechanism of action", "correct": false, "why": "Mechanism of action (MOA) would be: Which receptor the drug binds and what it does there: activates, inhibits, binds."}, {"t": "Pharmacodynamics", "correct": false, "why": "Pharmacodynamics (PD) would be: How the drug interacts with the biological system: affinity and efficacy only."}, {"t": "Receptor", "correct": false, "why": "Receptor would be: The regulatory protein that senses hormones, neurotransmitters and drugs; it is active or inactive."}], "teach": "Absorption, distribution, metabolism, excretion: how much drug gets to the site of action. On the efficacy poll, “the ability of a drug to be absorbed at the level of the GI” is pharmacokinetics, not efficacy."},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-pharmacokinetics", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~22–~23, ~27; transcript 9/22", "quote": "So pharmokinetics is going to be affecting how much of the drug gets to the site of action. Because that’s how it’s going to produce its effects.", "id": "T-pharmacokinetics-2", "stem": "Pharmacokinetics means:", "options": [{"t": "Absorption, distribution, metabolism, excretion: how much drug gets to the site of action.", "correct": true, "why": "That is pharmacokinetics (pk)."}, {"t": "The regulatory protein that senses hormones, neurotransmitters and drugs; it is active or inactive.", "correct": false, "why": "That is receptor, not pharmacokinetics (pk)."}, {"t": "How the drug interacts with the biological system: affinity and efficacy only.", "correct": false, "why": "That is pharmacodynamics (pd), not pharmacokinetics (pk)."}, {"t": "How few receptor types a drug binds; fewer types, fewer side effects.", "correct": false, "why": "That is selectivity, not pharmacokinetics (pk)."}], "teach": "Absorption, distribution, metabolism, excretion: how much drug gets to the site of action. On the efficacy poll, “the ability of a drug to be absorbed at the level of the GI” is pharmacokinetics, not efficacy.", "dupOf": "T-pharmacokinetics-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-pharmacokinetics", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~22–~23, ~27; transcript 9/22", "quote": "So pharmokinetics is going to be affecting how much of the drug gets to the site of action. Because that’s how it’s going to produce its effects.", "id": "T-pharmacokinetics-3", "stem": "Which term is defined as: The absorption, distribution, metabolism and excretion (ADME) side of the pharmacology diagram: how much of the drug gets to the site of action. It sets the apparent potency of a drug (age, absorption, distribution, elimination, drug–drug interactions)?", "options": [{"t": "Pharmacokinetics", "correct": true, "why": "This is the definition of Pharmacokinetics (PK)."}, {"t": "Mechanism of action", "correct": false, "why": "Mechanism of action (MOA): Which receptor the drug binds and what it does there: activates, inhibits, binds."}, {"t": "Pharmacodynamics", "correct": false, "why": "Pharmacodynamics (PD): How the drug interacts with the biological system: affinity and efficacy only."}, {"t": "Receptor", "correct": false, "why": "Receptor: The regulatory protein that senses hormones, neurotransmitters and drugs; it is active or inactive."}], "teach": "On the efficacy poll, “the ability of a drug to be absorbed at the level of the GI” is pharmacokinetics, not efficacy.", "dupOf": "T-pharmacokinetics-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-drug", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~29–~31; transcript 9/22", "quote": "drugs don’t create anything new, they just change whatever is happening in the body. Either they are going to enhance the signal or perhaps suppress the signal", "id": "T-drug-1", "stem": "Which term fits this situation? Metoprolol does not create a new heartbeat; it slows the rate the heart was already producing. Vitamin A in a carrot helps night blindness and in a polar bear liver poisons: only the amount differs.", "options": [{"t": "Drug", "correct": true, "why": "This situation is drug: A chemical that changes an ongoing function; enhances or suppresses, creates nothing new."}, {"t": "Ligand", "correct": false, "why": "Ligand would be: Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food."}, {"t": "Natural dietary supplement", "correct": false, "why": "Natural dietary supplement (NDS) would be: Regulated as food, not as a drug; the label cannot claim to cure."}, {"t": "Side effect", "correct": false, "why": "Side effect (ADR) would be: An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known."}], "teach": "A chemical that changes an ongoing function; enhances or suppresses, creates nothing new. Walter Straub: there is only a quantitative difference between a drug and a poison (vitamin A in carrots vs polar bear liver)."},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-drug", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~29–~31; transcript 9/22", "quote": "drugs don’t create anything new, they just change whatever is happening in the body. Either they are going to enhance the signal or perhaps suppress the signal", "id": "T-drug-2", "stem": "Drug means:", "options": [{"t": "A chemical that changes an ongoing function; enhances or suppresses, creates nothing new.", "correct": true, "why": "That is drug."}, {"t": "Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food.", "correct": false, "why": "That is ligand, not drug."}, {"t": "Regulated as food, not as a drug; the label cannot claim to cure.", "correct": false, "why": "That is natural dietary supplement (nds), not drug."}, {"t": "An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known.", "correct": false, "why": "That is side effect (adr), not drug."}], "teach": "A chemical that changes an ongoing function; enhances or suppresses, creates nothing new. Walter Straub: there is only a quantitative difference between a drug and a poison (vitamin A in carrots vs polar bear liver).", "dupOf": "T-drug-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-drug", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~29–~31; transcript 9/22", "quote": "drugs don’t create anything new, they just change whatever is happening in the body. Either they are going to enhance the signal or perhaps suppress the signal", "id": "T-drug-3", "stem": "Which term is defined as: A chemical that changes an ongoing function; enhances or suppresses, creates nothing new?", "options": [{"t": "Drug", "correct": true, "why": "This is the definition of Drug."}, {"t": "Ligand", "correct": false, "why": "Ligand: Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food."}, {"t": "Natural dietary supplement", "correct": false, "why": "Natural dietary supplement (NDS): Regulated as food, not as a drug; the label cannot claim to cure."}, {"t": "Side effect", "correct": false, "why": "Side effect (ADR): An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known."}], "teach": "Walter Straub: there is only a quantitative difference between a drug and a poison (vitamin A in carrots vs polar bear liver).", "dupOf": "T-drug-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-receptor", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~11, ~34–~36; transcript 9/22", "quote": "Receptors are regulatory proteins involved in the transfer of chemical information carried by various endogenous/exogenous mediators", "id": "T-receptor-1", "stem": "Which term fits this situation? A protein in the heart cell membrane recognizes norepinephrine by its shape and size, changes its conformation, and the cell answers with a faster beat. The same protein also binds metoprolol.", "options": [{"t": "Receptor", "correct": true, "why": "This situation is receptor: The regulatory protein that senses hormones, neurotransmitters and drugs; it is active or inactive."}, {"t": "Transducer", "correct": false, "why": "Transducer would be: Translates the activated receptor’s change to the effector; the G protein."}, {"t": "Ligand", "correct": false, "why": "Ligand would be: Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food."}, {"t": "Effector", "correct": false, "why": "Effector (signal amplifier) would be: The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C."}], "teach": "The regulatory protein that senses hormones, neurotransmitters and drugs; it is active or inactive. His picture: the gatekeeper that senses hormones, neurotransmitters and drugs; the message the receptor creates is the physiological response. Receptors come in two flavors, active or inactive."},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-receptor", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~11, ~34–~36; transcript 9/22", "quote": "Receptors are regulatory proteins involved in the transfer of chemical information carried by various endogenous/exogenous mediators", "id": "T-receptor-2", "stem": "Receptor means:", "options": [{"t": "The regulatory protein that senses hormones, neurotransmitters and drugs; it is active or inactive.", "correct": true, "why": "That is receptor."}, {"t": "More receptors made after chronic antagonist; a compensatory mechanism, agonist becomes more potent.", "correct": false, "why": "That is up-regulation, not receptor."}, {"t": "Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food.", "correct": false, "why": "That is ligand, not receptor."}, {"t": "The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C.", "correct": false, "why": "That is effector (signal amplifier), not receptor."}], "teach": "The regulatory protein that senses hormones, neurotransmitters and drugs; it is active or inactive. His picture: the gatekeeper that senses hormones, neurotransmitters and drugs; the message the receptor creates is the physiological response. Receptors come in two flavors, active or inactive.", "dupOf": "T-receptor-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-receptor", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~11, ~34–~36; transcript 9/22", "quote": "Receptors are regulatory proteins involved in the transfer of chemical information carried by various endogenous/exogenous mediators", "id": "T-receptor-3", "stem": "Which term is defined as: The regulatory protein that senses hormones, neurotransmitters and drugs; it is active or inactive?", "options": [{"t": "Receptor", "correct": true, "why": "This is the definition of Receptor."}, {"t": "Transducer", "correct": false, "why": "Transducer: Translates the activated receptor’s change to the effector; the G protein."}, {"t": "Ligand", "correct": false, "why": "Ligand: Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food."}, {"t": "Effector", "correct": false, "why": "Effector (signal amplifier): The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C."}], "teach": "His picture: the gatekeeper that senses hormones, neurotransmitters and drugs; the message the receptor creates is the physiological response. Receptors come in two flavors, active or inactive.", "dupOf": "T-receptor-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-ligand", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~26, ~30; transcript 9/23; transcript 9/24", "quote": "Cells have receptors that recognize specific chemicals ... Endogenous as well as exogenous", "id": "T-ligand-1", "stem": "Which term fits this situation? Acetylcholine made by the body and nicotine from a cigarette both bind the nicotinic receptor; acetylcholine also binds the muscarinic receptor.", "options": [{"t": "Ligand", "correct": true, "why": "This situation is ligand: Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food."}, {"t": "Mechanism of action", "correct": false, "why": "Mechanism of action (MOA) would be: Which receptor the drug binds and what it does there: activates, inhibits, binds."}, {"t": "Tolerance", "correct": false, "why": "Tolerance would be: Continued exposure to the same concentration gives a diminished effect; the clinical manifestation."}, {"t": "Synergism", "correct": false, "why": "Synergism would be: Two drugs with the same effect; the result is greater than their sum."}], "teach": "Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food. Multiple chemicals may bind the same receptor, and one chemical may bind multiple receptors (acetylcholine at nicotinic and muscarinic). Ligand-gated channels are named for it."},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-ligand", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~26, ~30; transcript 9/23; transcript 9/24", "quote": "Cells have receptors that recognize specific chemicals ... Endogenous as well as exogenous", "id": "T-ligand-2", "stem": "Ligand means:", "options": [{"t": "Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food.", "correct": true, "why": "That is ligand."}, {"t": "Continued exposure to the same concentration gives a diminished effect; the clinical manifestation.", "correct": false, "why": "That is tolerance, not ligand."}, {"t": "Which receptor the drug binds and what it does there: activates, inhibits, binds.", "correct": false, "why": "That is mechanism of action (moa), not ligand."}, {"t": "Two drugs with the same effect; the result is greater than their sum.", "correct": false, "why": "That is synergism, not ligand."}], "teach": "Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food. Multiple chemicals may bind the same receptor, and one chemical may bind multiple receptors (acetylcholine at nicotinic and muscarinic). Ligand-gated channels are named for it.", "dupOf": "T-ligand-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-ligand", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~26, ~30; transcript 9/23; transcript 9/24", "quote": "Cells have receptors that recognize specific chemicals ... Endogenous as well as exogenous", "id": "T-ligand-3", "stem": "Which term is defined as: Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food?", "options": [{"t": "Ligand", "correct": true, "why": "This is the definition of Ligand."}, {"t": "Mechanism of action", "correct": false, "why": "Mechanism of action (MOA): Which receptor the drug binds and what it does there: activates, inhibits, binds."}, {"t": "Tolerance", "correct": false, "why": "Tolerance: Continued exposure to the same concentration gives a diminished effect; the clinical manifestation."}, {"t": "Synergism", "correct": false, "why": "Synergism: Two drugs with the same effect; the result is greater than their sum."}], "teach": "Multiple chemicals may bind the same receptor, and one chemical may bind multiple receptors (acetylcholine at nicotinic and muscarinic). Ligand-gated channels are named for it.", "dupOf": "T-ligand-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-moa", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~7–~9, ~12, ~33; transcript 9/22", "quote": "So which receptor is binding to you, what is it doing to that receptor when it’s bound, is it activating, inhibiting, just binding, where is the receptor located", "id": "T-moa-1", "stem": "Which term fits this situation? For metoprolol the first thing written down is reversible β1 receptor antagonist: which receptor it binds and that it blocks it, before anything about where those receptors are.", "options": [{"t": "Mechanism of action", "correct": true, "why": "This situation is mechanism of action (moa): Which receptor the drug binds and what it does there: activates, inhibits, binds."}, {"t": "Natural dietary supplement", "correct": false, "why": "Natural dietary supplement (NDS) would be: Regulated as food, not as a drug; the label cannot claim to cure."}, {"t": "Site of action", "correct": false, "why": "Site of action (SOA) would be: Where the receptor is located; with the mechanism, it predicts effect and side effects."}, {"t": "Side effect", "correct": false, "why": "Side effect (ADR) would be: An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known."}], "teach": "Which receptor the drug binds and what it does there: activates, inhibits, binds. MOA is must-know; site of action (SOA) is should-know; effect, ADR and DDI are predicted from the two. Use, dose, route and brand names are not tested."},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-moa", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~7–~9, ~12, ~33; transcript 9/22", "quote": "So which receptor is binding to you, what is it doing to that receptor when it’s bound, is it activating, inhibiting, just binding, where is the receptor located", "id": "T-moa-2", "stem": "Mechanism of action means:", "options": [{"t": "Which receptor the drug binds and what it does there: activates, inhibits, binds.", "correct": true, "why": "That is mechanism of action (moa)."}, {"t": "Where the receptor is located; with the mechanism, it predicts effect and side effects.", "correct": false, "why": "That is site of action (soa), not mechanism of action (moa)."}, {"t": "An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known.", "correct": false, "why": "That is side effect (adr), not mechanism of action (moa)."}, {"t": "How the drug interacts with the biological system: affinity and efficacy only.", "correct": false, "why": "That is pharmacodynamics (pd), not mechanism of action (moa)."}], "teach": "Which receptor the drug binds and what it does there: activates, inhibits, binds. MOA is must-know; site of action (SOA) is should-know; effect, ADR and DDI are predicted from the two. Use, dose, route and brand names are not tested.", "dupOf": "T-moa-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-moa", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~7–~9, ~12, ~33; transcript 9/22", "quote": "So which receptor is binding to you, what is it doing to that receptor when it’s bound, is it activating, inhibiting, just binding, where is the receptor located", "id": "T-moa-3", "stem": "Which term is defined as: What the drug does at its receptor: which receptor it binds and whether it activates, inhibits or just binds (e.g., metoprolol: reversible β1 receptor antagonist). The must-know for every drug on Exam 1?", "options": [{"t": "Mechanism of action", "correct": true, "why": "This is the definition of Mechanism of action (MOA)."}, {"t": "Natural dietary supplement", "correct": false, "why": "Natural dietary supplement (NDS): Regulated as food, not as a drug; the label cannot claim to cure."}, {"t": "Site of action", "correct": false, "why": "Site of action (SOA): Where the receptor is located; with the mechanism, it predicts effect and side effects."}, {"t": "Side effect", "correct": false, "why": "Side effect (ADR): An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known."}], "teach": "MOA is must-know; site of action (SOA) is should-know; effect, ADR and DDI are predicted from the two. Use, dose, route and brand names are not tested.", "dupOf": "T-moa-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-soa", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~7, ~9, ~33; transcript 9/22", "quote": "The things that you should know are going to be the sites of actions. Because if you know where the receptor is located and you know what it does to the receptor, now you can predict the effect, the side effect, the drug-drug interaction, contraindication, use.", "id": "T-soa-1", "stem": "Which term fits this situation? Metoprolol blocks β1 receptors, and those receptors are in the heart, the kidneys and the brain; from the location alone you expect bradycardia and fatigue without memorizing them.", "options": [{"t": "Site of action", "correct": true, "why": "This situation is site of action (soa): Where the receptor is located; with the mechanism, it predicts effect and side effects."}, {"t": "Withdrawal syndrome", "correct": false, "why": "Withdrawal syndrome would be: The opposite of what the drug produced, appearing when the drug is stopped."}, {"t": "Pharmacology", "correct": false, "why": "Pharmacology would be: The whole field: what the drug does and how much reaches it."}, {"t": "Tolerance", "correct": false, "why": "Tolerance would be: Continued exposure to the same concentration gives a diminished effect; the clinical manifestation."}], "teach": "Where the receptor is located; with the mechanism, it predicts effect and side effects. Classifying a drug by chemical structure (benzothiadiazine ring) predicts little; MOA plus SOA (Na+/Cl− symporter antagonist at the distal tubule) predicts diuresis and hyponatremia."},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-soa", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~7, ~9, ~33; transcript 9/22", "quote": "The things that you should know are going to be the sites of actions. Because if you know where the receptor is located and you know what it does to the receptor, now you can predict the effect, the side effect, the drug-drug interaction, contraindication, use.", "id": "T-soa-2", "stem": "Site of action means:", "options": [{"t": "Where the receptor is located; with the mechanism, it predicts effect and side effects.", "correct": true, "why": "That is site of action (soa)."}, {"t": "Continued exposure to the same concentration gives a diminished effect; the clinical manifestation.", "correct": false, "why": "That is tolerance, not site of action (soa)."}, {"t": "The whole field: what the drug does and how much reaches it.", "correct": false, "why": "That is pharmacology, not site of action (soa)."}, {"t": "The opposite of what the drug produced, appearing when the drug is stopped.", "correct": false, "why": "That is withdrawal syndrome, not site of action (soa)."}], "teach": "Where the receptor is located; with the mechanism, it predicts effect and side effects. Classifying a drug by chemical structure (benzothiadiazine ring) predicts little; MOA plus SOA (Na+/Cl− symporter antagonist at the distal tubule) predicts diuresis and hyponatremia.", "dupOf": "T-soa-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-soa", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~7, ~9, ~33; transcript 9/22", "quote": "The things that you should know are going to be the sites of actions. Because if you know where the receptor is located and you know what it does to the receptor, now you can predict the effect, the side effect, the drug-drug interaction, contraindication, use.", "id": "T-soa-3", "stem": "Which term is defined as: Where the receptor is located; with the mechanism, it predicts effect and side effects?", "options": [{"t": "Site of action", "correct": true, "why": "This is the definition of Site of action (SOA)."}, {"t": "Withdrawal syndrome", "correct": false, "why": "Withdrawal syndrome: The opposite of what the drug produced, appearing when the drug is stopped."}, {"t": "Pharmacology", "correct": false, "why": "Pharmacology: The whole field: what the drug does and how much reaches it."}, {"t": "Tolerance", "correct": false, "why": "Tolerance: Continued exposure to the same concentration gives a diminished effect; the clinical manifestation."}], "teach": "Classifying a drug by chemical structure (benzothiadiazine ring) predicts little; MOA plus SOA (Na+/Cl− symporter antagonist at the distal tubule) predicts diuresis and hyponatremia.", "dupOf": "T-soa-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-nds", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~15–~16, ~18, ~20; transcript 9/22", "quote": "Dietary supplements regulated as food ... Not Drugs (Less FDA oversight) ... until they cause harm", "id": "T-nds-1", "stem": "Which term fits this situation? A bottle of fish oil sits on the shelf as food, not tested like a prescription, and stays there until it causes harm; the label may not say it treats or cures anything.", "options": [{"t": "Natural dietary supplement", "correct": true, "why": "This situation is natural dietary supplement (nds): Regulated as food, not as a drug; the label cannot claim to cure."}, {"t": "Down-regulation / desensitization", "correct": false, "why": "Down-regulation / desensitization would be: Fewer receptors after too much agonist; analogous to an irreversible antagonist."}, {"t": "Ligand", "correct": false, "why": "Ligand would be: Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food."}, {"t": "Site of action", "correct": false, "why": "Site of action (SOA) would be: Where the receptor is located; with the mechanism, it predicts effect and side effects."}], "teach": "Regulated as food, not as a drug; the label cannot claim to cure. Every option on his NDS poll was incorrect: labels cannot claim cure, the FDA does not test them like prescription drugs, centuries of use does not prove safety and effectiveness, and herbals interact with prescription/OTC drugs."},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-nds", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~15–~16, ~18, ~20; transcript 9/22", "quote": "Dietary supplements regulated as food ... Not Drugs (Less FDA oversight) ... until they cause harm", "id": "T-nds-2", "stem": "Natural dietary supplement means:", "options": [{"t": "Regulated as food, not as a drug; the label cannot claim to cure.", "correct": true, "why": "That is natural dietary supplement (nds)."}, {"t": "Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food.", "correct": false, "why": "That is ligand, not natural dietary supplement (nds)."}, {"t": "Where the receptor is located; with the mechanism, it predicts effect and side effects.", "correct": false, "why": "That is site of action (soa), not natural dietary supplement (nds)."}, {"t": "An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known.", "correct": false, "why": "That is side effect (adr), not natural dietary supplement (nds)."}], "teach": "Regulated as food, not as a drug; the label cannot claim to cure. Every option on his NDS poll was incorrect: labels cannot claim cure, the FDA does not test them like prescription drugs, centuries of use does not prove safety and effectiveness, and herbals interact with prescription/OTC drugs.", "dupOf": "T-nds-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-nds", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~15–~16, ~18, ~20; transcript 9/22", "quote": "Dietary supplements regulated as food ... Not Drugs (Less FDA oversight) ... until they cause harm", "id": "T-nds-3", "stem": "Which term is defined as: Regulated as food, not as a drug; the label cannot claim to cure?", "options": [{"t": "Natural dietary supplement", "correct": true, "why": "This is the definition of Natural dietary supplement (NDS)."}, {"t": "Down-regulation / desensitization", "correct": false, "why": "Down-regulation / desensitization: Fewer receptors after too much agonist; analogous to an irreversible antagonist."}, {"t": "Ligand", "correct": false, "why": "Ligand: Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food."}, {"t": "Site of action", "correct": false, "why": "Site of action (SOA): Where the receptor is located; with the mechanism, it predicts effect and side effects."}], "teach": "Every option on his NDS poll was incorrect: labels cannot claim cure, the FDA does not test them like prescription drugs, centuries of use does not prove safety and effectiveness, and herbals interact with prescription/OTC drugs.", "dupOf": "T-nds-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-selectivity", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~21, ~29; transcript 9/22; transcript 9/24", "quote": "the larger the dose gets, the less selective a drug becomes ... Metoprolol is a beta 1 selective up to about 200 mg. Once you go above 200, you start to affect the beta 2s, so you start to lose selectivity", "id": "T-selectivity-1", "stem": "Which term fits this situation? Loratadine binds only the H1 receptor; diphenhydramine binds H1, H2 and muscarinic receptors and produces many more effects. Metoprolol binds only β1 up to about 200 mg, then β2 as well.", "options": [{"t": "Selectivity", "correct": true, "why": "This situation is selectivity: How few receptor types a drug binds; fewer types, fewer side effects."}, {"t": "Natural dietary supplement", "correct": false, "why": "Natural dietary supplement (NDS) would be: Regulated as food, not as a drug; the label cannot claim to cure."}, {"t": "Affinity", "correct": false, "why": "Affinity would be: How likely a drug binds and stays bound; depends on the bonds formed."}, {"t": "Potency", "correct": false, "why": "Potency (pharmacological) would be: How much drug is needed; a combination of affinity, efficacy and the tissue."}], "teach": "How few receptor types a drug binds; fewer types, fewer side effects. The larger the dose gets, the less selective a drug becomes (metoprolol is β1-selective up to about 200 mg, then affects β2). Selectivity is about which receptors are bound; affinity is how tightly."},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-selectivity", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~21, ~29; transcript 9/22; transcript 9/24", "quote": "the larger the dose gets, the less selective a drug becomes ... Metoprolol is a beta 1 selective up to about 200 mg. Once you go above 200, you start to affect the beta 2s, so you start to lose selectivity", "id": "T-selectivity-2", "stem": "Selectivity means:", "options": [{"t": "How few receptor types a drug binds; fewer types, fewer side effects.", "correct": true, "why": "That is selectivity."}, {"t": "How much drug is needed; a combination of affinity, efficacy and the tissue.", "correct": false, "why": "That is potency (pharmacological), not selectivity."}, {"t": "How likely a drug binds and stays bound; depends on the bonds formed.", "correct": false, "why": "That is affinity, not selectivity."}, {"t": "Regulated as food, not as a drug; the label cannot claim to cure.", "correct": false, "why": "That is natural dietary supplement (nds), not selectivity."}], "teach": "How few receptor types a drug binds; fewer types, fewer side effects. The larger the dose gets, the less selective a drug becomes (metoprolol is β1-selective up to about 200 mg, then affects β2). Selectivity is about which receptors are bound; affinity is how tightly.", "dupOf": "T-selectivity-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-selectivity", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~21, ~29; transcript 9/22; transcript 9/24", "quote": "the larger the dose gets, the less selective a drug becomes ... Metoprolol is a beta 1 selective up to about 200 mg. Once you go above 200, you start to affect the beta 2s, so you start to lose selectivity", "id": "T-selectivity-3", "stem": "Which term is defined as: How narrowly a drug binds one receptor type rather than others: loratadine is a selective H1 inverse agonist; diphenhydramine binds H1, H2 and muscarinic receptors and is very non-selective. The less selective a drug is, the more effects and side effects it produces?", "options": [{"t": "Selectivity", "correct": true, "why": "This is the definition of Selectivity."}, {"t": "Natural dietary supplement", "correct": false, "why": "Natural dietary supplement (NDS): Regulated as food, not as a drug; the label cannot claim to cure."}, {"t": "Affinity", "correct": false, "why": "Affinity: How likely a drug binds and stays bound; depends on the bonds formed."}, {"t": "Potency", "correct": false, "why": "Potency (pharmacological): How much drug is needed; a combination of affinity, efficacy and the tissue."}], "teach": "The larger the dose gets, the less selective a drug becomes (metoprolol is β1-selective up to about 200 mg, then affects β2). Selectivity is about which receptors are bound; affinity is how tightly.", "dupOf": "T-selectivity-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-affinity", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~31, ~55; Pharmacodynamics-Day-1-2026s.pdf slides ~21, ~37; transcript 9/22; transcript 9/23", "quote": "Remember, affinity is how likely a drug is to bind and stay bound to a receptor, and the binding of a drug to the receptor is going to be depending on what type of bonds they form covalent bonds, hydrogen bonds, ion bonds.", "id": "T-affinity-1", "stem": "Which term fits this situation? Phenoxybenzamine forms a covalent bond with the α1 receptor and stays bound; prazosin forms weaker bonds and comes off. On a binding curve, the drug furthest left binds 50% of receptors at the smallest dose.", "options": [{"t": "Affinity", "correct": true, "why": "This situation is affinity: How likely a drug binds and stays bound; depends on the bonds formed."}, {"t": "Orthosteric site", "correct": false, "why": "Orthosteric site would be: The receptor’s own pocket where the endogenous agonist binds; one or the other."}, {"t": "Efficacy", "correct": false, "why": "Efficacy (intrinsic efficacy) would be: The ability to change the receptor state; positive activates, negative shuts down."}, {"t": "Potency", "correct": false, "why": "Potency (pharmacological) would be: How much drug is needed; a combination of affinity, efficacy and the tissue."}], "teach": "How likely a drug binds and stays bound; depends on the bonds formed. Affinity is read on the x-axis (further left = higher affinity); efficacy on the y-axis. Poll trap: “the ability of a drug to bind and stay bound to a receptor” is affinity, not efficacy.", "fg": "binding-kd"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-affinity", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~31, ~55; Pharmacodynamics-Day-1-2026s.pdf slides ~21, ~37; transcript 9/22; transcript 9/23", "quote": "Remember, affinity is how likely a drug is to bind and stay bound to a receptor, and the binding of a drug to the receptor is going to be depending on what type of bonds they form covalent bonds, hydrogen bonds, ion bonds.", "id": "T-affinity-2", "stem": "Affinity means:", "options": [{"t": "How likely a drug binds and stays bound; depends on the bonds formed.", "correct": true, "why": "That is affinity."}, {"t": "The ability to change the receptor state; positive activates, negative shuts down.", "correct": false, "why": "That is efficacy (intrinsic efficacy), not affinity."}, {"t": "How much drug is needed; a combination of affinity, efficacy and the tissue.", "correct": false, "why": "That is potency (pharmacological), not affinity."}, {"t": "The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect.", "correct": false, "why": "That is kd (dissociation constant), not affinity."}], "teach": "How likely a drug binds and stays bound; depends on the bonds formed. Affinity is read on the x-axis (further left = higher affinity); efficacy on the y-axis. Poll trap: “the ability of a drug to bind and stay bound to a receptor” is affinity, not efficacy.", "fg": "binding-kd", "dupOf": "T-affinity-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-affinity", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~31, ~55; Pharmacodynamics-Day-1-2026s.pdf slides ~21, ~37; transcript 9/22; transcript 9/23", "quote": "Remember, affinity is how likely a drug is to bind and stay bound to a receptor, and the binding of a drug to the receptor is going to be depending on what type of bonds they form covalent bonds, hydrogen bonds, ion bonds.", "id": "T-affinity-3", "stem": "Which term is defined as: How likely a drug binds and stays bound; depends on the bonds formed?", "options": [{"t": "Affinity", "correct": true, "why": "This is the definition of Affinity."}, {"t": "Orthosteric site", "correct": false, "why": "Orthosteric site: The receptor’s own pocket where the endogenous agonist binds; one or the other."}, {"t": "Efficacy", "correct": false, "why": "Efficacy (intrinsic efficacy): The ability to change the receptor state; positive activates, negative shuts down."}, {"t": "Potency", "correct": false, "why": "Potency (pharmacological): How much drug is needed; a combination of affinity, efficacy and the tissue."}], "teach": "Affinity is read on the x-axis (further left = higher affinity); efficacy on the y-axis. Poll trap: “the ability of a drug to bind and stay bound to a receptor” is affinity, not efficacy.", "fg": "binding-kd", "dupOf": "T-affinity-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-efficacy", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~31; Pharmacodynamics-Day_3_2026s.pdf slides ~19, ~26; Pharmacodynamics-Day-1-2026s.pdf slide ~38; transcript 9/22; transcript 9/23", "quote": "Efficacy is the ability of that drug to change the receptor behavior. It’s activity, its state from active to inactive or inactive to active, right?", "id": "T-efficacy-1", "stem": "Which term fits this situation? Norepinephrine binds β1 and flips it from inactive to active, loratadine binds H1 and flips it from active to inactive, and metoprolol binds β1 without changing its state.", "options": [{"t": "Efficacy", "correct": true, "why": "This situation is efficacy (intrinsic efficacy): The ability to change the receptor state; positive activates, negative shuts down."}, {"t": "Intrinsic activity", "correct": false, "why": "Intrinsic activity would be: A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue."}, {"t": "Affinity", "correct": false, "why": "Affinity would be: How likely a drug binds and stays bound; depends on the bonds formed."}, {"t": "Potency", "correct": false, "why": "Potency (pharmacological) would be: How much drug is needed; a combination of affinity, efficacy and the tissue."}], "teach": "The ability to change the receptor state; positive activates, negative shuts down. Read on the y-axis as the height of the curve (Emax). Efficacy cannot be calculated directly; it is a relative measurement between ligands.", "fg": "efficacy"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-efficacy", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~31; Pharmacodynamics-Day_3_2026s.pdf slides ~19, ~26; Pharmacodynamics-Day-1-2026s.pdf slide ~38; transcript 9/22; transcript 9/23", "quote": "Efficacy is the ability of that drug to change the receptor behavior. It’s activity, its state from active to inactive or inactive to active, right?", "id": "T-efficacy-2", "stem": "Efficacy means:", "options": [{"t": "The ability to change the receptor state; positive activates, negative shuts down.", "correct": true, "why": "That is efficacy (intrinsic efficacy)."}, {"t": "The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect.", "correct": false, "why": "That is kd (dissociation constant), not efficacy (intrinsic efficacy)."}, {"t": "How likely a drug binds and stays bound; depends on the bonds formed.", "correct": false, "why": "That is affinity, not efficacy (intrinsic efficacy)."}, {"t": "A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue.", "correct": false, "why": "That is intrinsic activity, not efficacy (intrinsic efficacy)."}], "teach": "The ability to change the receptor state; positive activates, negative shuts down. Read on the y-axis as the height of the curve (Emax). Efficacy cannot be calculated directly; it is a relative measurement between ligands.", "fg": "efficacy", "dupOf": "T-efficacy-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-efficacy", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~31; Pharmacodynamics-Day_3_2026s.pdf slides ~19, ~26; Pharmacodynamics-Day-1-2026s.pdf slide ~38; transcript 9/22; transcript 9/23", "quote": "Efficacy is the ability of that drug to change the receptor behavior. It’s activity, its state from active to inactive or inactive to active, right?", "id": "T-efficacy-3", "stem": "Which term is defined as: The ability to change the receptor state; positive activates, negative shuts down?", "options": [{"t": "Efficacy", "correct": true, "why": "This is the definition of Efficacy (intrinsic efficacy)."}, {"t": "Intrinsic activity", "correct": false, "why": "Intrinsic activity: A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue."}, {"t": "Affinity", "correct": false, "why": "Affinity: How likely a drug binds and stays bound; depends on the bonds formed."}, {"t": "Potency", "correct": false, "why": "Potency (pharmacological): How much drug is needed; a combination of affinity, efficacy and the tissue."}], "teach": "Read on the y-axis as the height of the curve (Emax). Efficacy cannot be calculated directly; it is a relative measurement between ligands.", "fg": "efficacy", "dupOf": "T-efficacy-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-intrinsic-activity", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~24–~26; Pharmacodynamics-Day-1-2026s.pdf slide ~28; transcript 9/22; transcript 9/24", "quote": "What he did not count was for the tissue, how many receptors are present in that system. So this is an incomplete theory that we can’t really use much", "id": "T-intrinsic-activity-1", "stem": "Which term fits this situation? Ariëns assigned each drug a single value, norepinephrine 1, albuterol somewhere between 0 and 1, metoprolol 0, without counting how many receptors the tissue has, so the theory is incomplete.", "options": [{"t": "Intrinsic activity", "correct": true, "why": "This situation is intrinsic activity: A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue."}, {"t": "Allosteric site / modulator", "correct": false, "why": "Allosteric site / modulator would be: A second place on the receptor; changes another drug’s affinity or efficacy; both bound."}, {"t": "Law of mass action", "correct": false, "why": "Law of mass action would be: More drug or more receptors present, greater the chance of binding."}, {"t": "Orthosteric site", "correct": false, "why": "Orthosteric site would be: The receptor’s own pocket where the endogenous agonist binds; one or the other."}], "teach": "A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue. It does not account for the tissue (how many receptors are present), so it is incomplete; efficacy is the more comprehensive term. The names and the formula are not tested."},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-intrinsic-activity", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~24–~26; Pharmacodynamics-Day-1-2026s.pdf slide ~28; transcript 9/22; transcript 9/24", "quote": "What he did not count was for the tissue, how many receptors are present in that system. So this is an incomplete theory that we can’t really use much", "id": "T-intrinsic-activity-2", "stem": "Intrinsic activity means:", "options": [{"t": "A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue.", "correct": true, "why": "That is intrinsic activity."}, {"t": "The receptor’s own pocket where the endogenous agonist binds; one or the other.", "correct": false, "why": "That is orthosteric site, not intrinsic activity."}, {"t": "More drug or more receptors present, greater the chance of binding.", "correct": false, "why": "That is law of mass action, not intrinsic activity."}, {"t": "A second place on the receptor; changes another drug’s affinity or efficacy; both bound.", "correct": false, "why": "That is allosteric site / modulator, not intrinsic activity."}], "teach": "A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue. It does not account for the tissue (how many receptors are present), so it is incomplete; efficacy is the more comprehensive term. The names and the formula are not tested.", "dupOf": "T-intrinsic-activity-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-intrinsic-activity", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~24–~26; Pharmacodynamics-Day-1-2026s.pdf slide ~28; transcript 9/22; transcript 9/24", "quote": "What he did not count was for the tissue, how many receptors are present in that system. So this is an incomplete theory that we can’t really use much", "id": "T-intrinsic-activity-3", "stem": "Which term is defined as: A number for the ability of a drug to produce a response: full agonist = 1, partial agonist between 0 and 1, antagonist = 0. It does not count the tissue (how many receptors are present), so efficacy is the term used instead?", "options": [{"t": "Intrinsic activity", "correct": true, "why": "This is the definition of Intrinsic activity."}, {"t": "Allosteric site / modulator", "correct": false, "why": "Allosteric site / modulator: A second place on the receptor; changes another drug’s affinity or efficacy; both bound."}, {"t": "Law of mass action", "correct": false, "why": "Law of mass action: More drug or more receptors present, greater the chance of binding."}, {"t": "Orthosteric site", "correct": false, "why": "Orthosteric site: The receptor’s own pocket where the endogenous agonist binds; one or the other."}], "teach": "It does not account for the tissue (how many receptors are present), so it is incomplete; efficacy is the more comprehensive term. The names and the formula are not tested.", "dupOf": "T-intrinsic-activity-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-kd", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~45–~50; Pharmacodynamics-Day_3_2026s.pdf slide ~31; transcript 9/24", "quote": "So the take-home message is that the smaller the coefficient of dissociation is, the more drugs receptors are going to find together, and thus the greater the affinity is going to be.", "id": "T-kd-1", "stem": "Which term fits this situation? For the β1 receptor drug A has a value of 30 micromolar and drug B 100 nanomolar; after converting the units the smaller number means drug B binds half of the receptors at a lower concentration (at M1 both are 250 nanomolar: equal affinity). Convert milli, micro and nano before comparing.", "options": [{"t": "Kd", "correct": true, "why": "This situation is kd (dissociation constant): The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect."}, {"t": "EC50 / ED50", "correct": false, "why": "EC50 / ED50 would be: Concentration (or dose) producing 50% of the maximal response; smaller means more potent."}, {"t": "Efficacy", "correct": false, "why": "Efficacy (intrinsic efficacy) would be: The ability to change the receptor state; positive activates, negative shuts down."}, {"t": "Intrinsic activity", "correct": false, "why": "Intrinsic activity would be: A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue."}], "teach": "The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect. Read on the x-axis of a binding curve; it says nothing about effect. Convert units before comparing (milli 10^-3, micro 10^-6, nano 10^-9): “the units ... about 10% of you are gonna miss it.”", "fg": "binding-kd"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-kd", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~45–~50; Pharmacodynamics-Day_3_2026s.pdf slide ~31; transcript 9/24", "quote": "So the take-home message is that the smaller the coefficient of dissociation is, the more drugs receptors are going to find together, and thus the greater the affinity is going to be.", "id": "T-kd-2", "stem": "Kd means:", "options": [{"t": "The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect.", "correct": true, "why": "That is kd (dissociation constant)."}, {"t": "Shared pair of electrons; unbreakable at body temperature; aspirin, omeprazole, phenoxybenzamine form it.", "correct": false, "why": "That is covalent (irreversible) bond, not kd (dissociation constant)."}, {"t": "Concentration (or dose) producing 50% of the maximal response; smaller means more potent.", "correct": false, "why": "That is ec50 / ed50, not kd (dissociation constant)."}, {"t": "The ability to change the receptor state; positive activates, negative shuts down.", "correct": false, "why": "That is efficacy (intrinsic efficacy), not kd (dissociation constant)."}], "teach": "The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect. Read on the x-axis of a binding curve; it says nothing about effect. Convert units before comparing (milli 10^-3, micro 10^-6, nano 10^-9): “the units ... about 10% of you are gonna miss it.”", "fg": "binding-kd", "dupOf": "T-kd-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-kd", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~45–~50; Pharmacodynamics-Day_3_2026s.pdf slide ~31; transcript 9/24", "quote": "So the take-home message is that the smaller the coefficient of dissociation is, the more drugs receptors are going to find together, and thus the greater the affinity is going to be.", "id": "T-kd-3", "stem": "Which term is defined as: The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect?", "options": [{"t": "Kd", "correct": true, "why": "This is the definition of Kd (dissociation constant)."}, {"t": "EC50 / ED50", "correct": false, "why": "EC50 / ED50: Concentration (or dose) producing 50% of the maximal response; smaller means more potent."}, {"t": "Efficacy", "correct": false, "why": "Efficacy (intrinsic efficacy): The ability to change the receptor state; positive activates, negative shuts down."}, {"t": "Intrinsic activity", "correct": false, "why": "Intrinsic activity: A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue."}], "teach": "Read on the x-axis of a binding curve; it says nothing about effect. Convert units before comparing (milli 10^-3, micro 10^-6, nano 10^-9): “the units ... about 10% of you are gonna miss it.”", "fg": "binding-kd", "dupOf": "T-kd-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-binding-curve", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~50; Pharmacodynamics-Day_3_2026s.pdf slide ~3; transcript 9/24", "quote": "And the further the left you are, the smaller the dose is going to be required, and thus the more affinity a drug is gonna have for the receptor.", "id": "T-binding-curve-1", "stem": "Which term fits this situation? Three drugs plotted as percent of receptors occupied, 0 up to 100, against log concentration; drug C reaches 50% occupied at the lowest dose, so it has the highest affinity. No effect is shown.", "options": [{"t": "Binding curve", "correct": true, "why": "This situation is binding curve (bmax): Percent of receptors bound versus log concentration; shows occupancy only, not effect."}, {"t": "Dose–response curve", "correct": false, "why": "Dose–response curve (DRC / CRC) would be: Log dose on the x-axis, percent of maximal effect on the y-axis; sigmoid."}, {"t": "Kd", "correct": false, "why": "Kd (dissociation constant) would be: The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect."}, {"t": "Intrinsic activity", "correct": false, "why": "Intrinsic activity would be: A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue."}], "teach": "Percent of receptors bound versus log concentration; shows occupancy only, not effect. A binding curve shows binding only; a dose–response curve shows effect (Emax, EC50). Drug C “requires less dose to bind 50% of the receptors” so it has the highest affinity.", "fg": "binding-kd"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-binding-curve", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~50; Pharmacodynamics-Day_3_2026s.pdf slide ~3; transcript 9/24", "quote": "And the further the left you are, the smaller the dose is going to be required, and thus the more affinity a drug is gonna have for the receptor.", "id": "T-binding-curve-2", "stem": "Binding curve means:", "options": [{"t": "Percent of receptors bound versus log concentration; shows occupancy only, not effect.", "correct": true, "why": "That is binding curve (bmax)."}, {"t": "The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect.", "correct": false, "why": "That is kd (dissociation constant), not binding curve (bmax)."}, {"t": "Log dose on the x-axis, percent of maximal effect on the y-axis; sigmoid.", "correct": false, "why": "That is dose–response curve (drc / crc), not binding curve (bmax)."}, {"t": "A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue.", "correct": false, "why": "That is intrinsic activity, not binding curve (bmax)."}], "teach": "Percent of receptors bound versus log concentration; shows occupancy only, not effect. A binding curve shows binding only; a dose–response curve shows effect (Emax, EC50). Drug C “requires less dose to bind 50% of the receptors” so it has the highest affinity.", "fg": "binding-kd", "dupOf": "T-binding-curve-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-binding-curve", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~50; Pharmacodynamics-Day_3_2026s.pdf slide ~3; transcript 9/24", "quote": "And the further the left you are, the smaller the dose is going to be required, and thus the more affinity a drug is gonna have for the receptor.", "id": "T-binding-curve-3", "stem": "Which term is defined as: Percent of receptors bound versus log concentration; shows occupancy only, not effect?", "options": [{"t": "Binding curve", "correct": true, "why": "This is the definition of Binding curve (Bmax)."}, {"t": "Dose–response curve", "correct": false, "why": "Dose–response curve (DRC / CRC): Log dose on the x-axis, percent of maximal effect on the y-axis; sigmoid."}, {"t": "Kd", "correct": false, "why": "Kd (dissociation constant): The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect."}, {"t": "Intrinsic activity", "correct": false, "why": "Intrinsic activity: A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue."}], "teach": "A binding curve shows binding only; a dose–response curve shows effect (Emax, EC50). Drug C “requires less dose to bind 50% of the receptors” so it has the highest affinity.", "fg": "binding-kd", "dupOf": "T-binding-curve-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-mass-action", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~45; transcript 9/24", "quote": "The more I have either of the receptors or the more I have either the drug, the greater the capacity of binding to something is going to be, right?", "id": "T-mass-action-1", "stem": "Which term fits this situation? Two hearts get the same dose of norepinephrine, one with 10 receptors and one with 100; the heart with 100 responds at a lower dose, though norepinephrine itself is unchanged.", "options": [{"t": "Law of mass action", "correct": true, "why": "This situation is law of mass action: More drug or more receptors present, greater the chance of binding."}, {"t": "Allosteric site / modulator", "correct": false, "why": "Allosteric site / modulator would be: A second place on the receptor; changes another drug’s affinity or efficacy; both bound."}, {"t": "Kd", "correct": false, "why": "Kd (dissociation constant) would be: The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect."}, {"t": "Covalent bond", "correct": false, "why": "Covalent (irreversible) bond would be: Shared pair of electrons; unbreakable at body temperature; aspirin, omeprazole, phenoxybenzamine form it."}], "teach": "More drug or more receptors present, greater the chance of binding. More receptors in a tissue make the same dose of norepinephrine appear more potent (curve shifts left) while its Kd, affinity and efficacy are unchanged; what changed is the tissue."},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-mass-action", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~45; transcript 9/24", "quote": "The more I have either of the receptors or the more I have either the drug, the greater the capacity of binding to something is going to be, right?", "id": "T-mass-action-2", "stem": "Law of mass action means:", "options": [{"t": "More drug or more receptors present, greater the chance of binding.", "correct": true, "why": "That is law of mass action."}, {"t": "The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect.", "correct": false, "why": "That is kd (dissociation constant), not law of mass action."}, {"t": "Shared pair of electrons; unbreakable at body temperature; aspirin, omeprazole, phenoxybenzamine form it.", "correct": false, "why": "That is covalent (irreversible) bond, not law of mass action."}, {"t": "The receptor’s own pocket where the endogenous agonist binds; one or the other.", "correct": false, "why": "That is orthosteric site, not law of mass action."}], "teach": "More drug or more receptors present, greater the chance of binding. More receptors in a tissue make the same dose of norepinephrine appear more potent (curve shifts left) while its Kd, affinity and efficacy are unchanged; what changed is the tissue.", "dupOf": "T-mass-action-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-mass-action", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~45; transcript 9/24", "quote": "The more I have either of the receptors or the more I have either the drug, the greater the capacity of binding to something is going to be, right?", "id": "T-mass-action-3", "stem": "Which term is defined as: More drug or more receptors present, greater the chance of binding?", "options": [{"t": "Law of mass action", "correct": true, "why": "This is the definition of Law of mass action."}, {"t": "Allosteric site / modulator", "correct": false, "why": "Allosteric site / modulator: A second place on the receptor; changes another drug’s affinity or efficacy; both bound."}, {"t": "Kd", "correct": false, "why": "Kd (dissociation constant): The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect."}, {"t": "Covalent bond", "correct": false, "why": "Covalent (irreversible) bond: Shared pair of electrons; unbreakable at body temperature; aspirin, omeprazole, phenoxybenzamine form it."}], "teach": "More receptors in a tissue make the same dose of norepinephrine appear more potent (curve shifts left) while its Kd, affinity and efficacy are unchanged; what changed is the tissue.", "dupOf": "T-mass-action-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-covalent-bond", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~15–~16; transcript 9/23; transcript 9/24", "quote": "They can be classified as irreversible, insurmountable, and non-competitive, which means is They all mean the same thing ... What does that mean? Once they are bound, they’re not coming off, OK?", "id": "T-covalent-bond-1", "stem": "Which term fits this situation? Aspirin, omeprazole and phenoxybenzamine each attach to their target by sharing a pair of electrons; at body temperature the attachment cannot be broken, so the body must make new protein to recover.", "options": [{"t": "Covalent bond", "correct": true, "why": "This situation is covalent (irreversible) bond: Shared pair of electrons; unbreakable at body temperature; aspirin, omeprazole, phenoxybenzamine form it."}, {"t": "Two-state model", "correct": false, "why": "Two-state model would be: Receptors flip between inactive R and active R*; drugs shift the balance."}, {"t": "Affinity", "correct": false, "why": "Affinity would be: How likely a drug binds and stays bound; depends on the bonds formed."}, {"t": "Kd", "correct": false, "why": "Kd (dissociation constant) would be: The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect."}], "teach": "Shared pair of electrons; unbreakable at body temperature; aspirin, omeprazole, phenoxybenzamine form it. Aspirin, omeprazole and phenoxybenzamine form covalent bonds; a covalent binder has the highest affinity and the smallest Kd. Weak-bond drugs must fit the pocket like a hand in a glove, which is where selectivity comes from."},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-covalent-bond", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~15–~16; transcript 9/23; transcript 9/24", "quote": "They can be classified as irreversible, insurmountable, and non-competitive, which means is They all mean the same thing ... What does that mean? Once they are bound, they’re not coming off, OK?", "id": "T-covalent-bond-2", "stem": "Covalent bond means:", "options": [{"t": "Shared pair of electrons; unbreakable at body temperature; aspirin, omeprazole, phenoxybenzamine form it.", "correct": true, "why": "That is covalent (irreversible) bond."}, {"t": "A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane.", "correct": false, "why": "That is rapid desensitization (grk / β-arrestin), not covalent (irreversible) bond."}, {"t": "How likely a drug binds and stays bound; depends on the bonds formed.", "correct": false, "why": "That is affinity, not covalent (irreversible) bond."}, {"t": "Receptors flip between inactive R and active R*; drugs shift the balance.", "correct": false, "why": "That is two-state model, not covalent (irreversible) bond."}], "teach": "Shared pair of electrons; unbreakable at body temperature; aspirin, omeprazole, phenoxybenzamine form it. Aspirin, omeprazole and phenoxybenzamine form covalent bonds; a covalent binder has the highest affinity and the smallest Kd. Weak-bond drugs must fit the pocket like a hand in a glove, which is where selectivity comes from.", "dupOf": "T-covalent-bond-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-covalent-bond", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~15–~16; transcript 9/23; transcript 9/24", "quote": "They can be classified as irreversible, insurmountable, and non-competitive, which means is They all mean the same thing ... What does that mean? Once they are bound, they’re not coming off, OK?", "id": "T-covalent-bond-3", "stem": "Which term is defined as: Shared pair of electrons; unbreakable at body temperature; aspirin, omeprazole, phenoxybenzamine form it?", "options": [{"t": "Covalent bond", "correct": true, "why": "This is the definition of Covalent (irreversible) bond."}, {"t": "Two-state model", "correct": false, "why": "Two-state model: Receptors flip between inactive R and active R*; drugs shift the balance."}, {"t": "Affinity", "correct": false, "why": "Affinity: How likely a drug binds and stays bound; depends on the bonds formed."}, {"t": "Kd", "correct": false, "why": "Kd (dissociation constant): The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect."}], "teach": "Aspirin, omeprazole and phenoxybenzamine form covalent bonds; a covalent binder has the highest affinity and the smallest Kd. Weak-bond drugs must fit the pocket like a hand in a glove, which is where selectivity comes from.", "dupOf": "T-covalent-bond-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-orthosteric", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~18–~19; transcript 9/23; transcript 9/24", "quote": "How we define orthostatic. So they compete for the same binding pocket, right? ... with orthostatic, we can have either one or the other, not both at the same time. As with allosteric, we can have one in the other", "id": "T-orthosteric-1", "stem": "Which term fits this situation? Phenylephrine, prazosin and phenoxybenzamine all go for the same pocket on the α1 receptor, the one norepinephrine uses, so only one of them can be in it at a time.", "options": [{"t": "Orthosteric site", "correct": true, "why": "This situation is orthosteric site: The receptor’s own pocket where the endogenous agonist binds; one or the other."}, {"t": "Allosteric site / modulator", "correct": false, "why": "Allosteric site / modulator would be: A second place on the receptor; changes another drug’s affinity or efficacy; both bound."}, {"t": "Efficacy", "correct": false, "why": "Efficacy (intrinsic efficacy) would be: The ability to change the receptor state; positive activates, negative shuts down."}, {"t": "Two-state model", "correct": false, "why": "Two-state model would be: Receptors flip between inactive R and active R*; drugs shift the balance."}], "teach": "The receptor’s own pocket where the endogenous agonist binds; one or the other. Orthosteric: one or the other. Allosteric: one and the other. Spoken as “orthostatic” in the transcripts; the slide term is orthosteric.", "fg": "sites"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-orthosteric", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~18–~19; transcript 9/23; transcript 9/24", "quote": "How we define orthostatic. So they compete for the same binding pocket, right? ... with orthostatic, we can have either one or the other, not both at the same time. As with allosteric, we can have one in the other", "id": "T-orthosteric-2", "stem": "Orthosteric site means:", "options": [{"t": "The receptor’s own pocket where the endogenous agonist binds; one or the other.", "correct": true, "why": "That is orthosteric site."}, {"t": "A second place on the receptor; changes another drug’s affinity or efficacy; both bound.", "correct": false, "why": "That is allosteric site / modulator, not orthosteric site."}, {"t": "The ability to change the receptor state; positive activates, negative shuts down.", "correct": false, "why": "That is efficacy (intrinsic efficacy), not orthosteric site."}, {"t": "Receptors flip between inactive R and active R*; drugs shift the balance.", "correct": false, "why": "That is two-state model, not orthosteric site."}], "teach": "The receptor’s own pocket where the endogenous agonist binds; one or the other. Orthosteric: one or the other. Allosteric: one and the other. Spoken as “orthostatic” in the transcripts; the slide term is orthosteric.", "fg": "sites", "dupOf": "T-orthosteric-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-orthosteric", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~18–~19; transcript 9/23; transcript 9/24", "quote": "How we define orthostatic. So they compete for the same binding pocket, right? ... with orthostatic, we can have either one or the other, not both at the same time. As with allosteric, we can have one in the other", "id": "T-orthosteric-3", "stem": "Which term is defined as: The receptor’s own binding pocket, where the endogenous agonist binds. Drugs that bind there (phenylephrine, prazosin, phenoxybenzamine at α1) compete for that one pocket, so only one can be bound at a time: either one or the other, not both?", "options": [{"t": "Orthosteric site", "correct": true, "why": "This is the definition of Orthosteric site."}, {"t": "Allosteric site / modulator", "correct": false, "why": "Allosteric site / modulator: A second place on the receptor; changes another drug’s affinity or efficacy; both bound."}, {"t": "Efficacy", "correct": false, "why": "Efficacy (intrinsic efficacy): The ability to change the receptor state; positive activates, negative shuts down."}, {"t": "Two-state model", "correct": false, "why": "Two-state model: Receptors flip between inactive R and active R*; drugs shift the balance."}], "teach": "Orthosteric: one or the other. Allosteric: one and the other. Spoken as “orthostatic” in the transcripts; the slide term is orthosteric.", "fg": "sites", "dupOf": "T-orthosteric-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-allosteric", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~19–~20, ~39, ~44; Pharmacodynamics-Day-1-2026s.pdf slide ~29; transcript 9/22; transcript 9/23", "quote": "These drugs do not bind or compete for the orthostatic binding pocket. They bind someplace else on the receptor.", "id": "T-allosteric-1", "stem": "Which term fits this situation? Propranolol and epinephrine fight over one pocket on the receptor, while drug X binds the same receptor somewhere else and is bound at the same time as either of them, making the pocket work better or worse.", "options": [{"t": "Allosteric site / modulator", "correct": true, "why": "This situation is allosteric site / modulator: A second place on the receptor; changes another drug’s affinity or efficacy; both bound."}, {"t": "Down-regulation / desensitization", "correct": false, "why": "Down-regulation / desensitization would be: Fewer receptors after too much agonist; analogous to an irreversible antagonist."}, {"t": "Indirect antagonist", "correct": false, "why": "Indirect antagonist would be: Binds upstream or downstream of the receptor, never the receptor; raises or lowers response."}, {"t": "Allosteric agonist", "correct": false, "why": "Allosteric agonist (PAM) would be: Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam."}], "teach": "A second place on the receptor; changes another drug’s affinity or efficacy; both bound. “Where the magic in pharmacology is”: they don’t always do things by themselves but make other drugs much better or much worse. Poll traps: allosteric agonists do not compete for the orthosteric pocket and do not have the highest affinity for it.", "fg": "classes"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-allosteric", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~19–~20, ~39, ~44; Pharmacodynamics-Day-1-2026s.pdf slide ~29; transcript 9/22; transcript 9/23", "quote": "These drugs do not bind or compete for the orthostatic binding pocket. They bind someplace else on the receptor.", "id": "T-allosteric-2", "stem": "Allosteric site / modulator means:", "options": [{"t": "A second place on the receptor; changes another drug’s affinity or efficacy; both bound.", "correct": true, "why": "That is allosteric site / modulator."}, {"t": "Binds upstream or downstream of the receptor, never the receptor; raises or lowers response.", "correct": false, "why": "That is indirect antagonist, not allosteric site / modulator."}, {"t": "Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam.", "correct": false, "why": "That is allosteric agonist (pam), not allosteric site / modulator."}, {"t": "The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect.", "correct": false, "why": "That is kd (dissociation constant), not allosteric site / modulator."}], "teach": "A second place on the receptor; changes another drug’s affinity or efficacy; both bound. “Where the magic in pharmacology is”: they don’t always do things by themselves but make other drugs much better or much worse. Poll traps: allosteric agonists do not compete for the orthosteric pocket and do not have the highest affinity for it.", "fg": "classes", "dupOf": "T-allosteric-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-allosteric", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~19–~20, ~39, ~44; Pharmacodynamics-Day-1-2026s.pdf slide ~29; transcript 9/22; transcript 9/23", "quote": "These drugs do not bind or compete for the orthostatic binding pocket. They bind someplace else on the receptor.", "id": "T-allosteric-3", "stem": "Which term is defined as: A second place on the receptor; changes another drug’s affinity or efficacy; both bound?", "options": [{"t": "Allosteric site / modulator", "correct": true, "why": "This is the definition of Allosteric site / modulator."}, {"t": "Down-regulation / desensitization", "correct": false, "why": "Down-regulation / desensitization: Fewer receptors after too much agonist; analogous to an irreversible antagonist."}, {"t": "Indirect antagonist", "correct": false, "why": "Indirect antagonist: Binds upstream or downstream of the receptor, never the receptor; raises or lowers response."}, {"t": "Allosteric agonist", "correct": false, "why": "Allosteric agonist (PAM): Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam."}], "teach": "“Where the magic in pharmacology is”: they don’t always do things by themselves but make other drugs much better or much worse. Poll traps: allosteric agonists do not compete for the orthosteric pocket and do not have the highest affinity for it.", "fg": "classes", "dupOf": "T-allosteric-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-two-state", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slide ~31; Pharmacodynamics-Day-1-2026s.pdf slide ~28; transcript 9/22; transcript 9/23", "quote": "So this two-state model shows that we have receptor two confirmations, active and inactive, and that drugs can shift them once bound to the receptor from one confirmation to the other.", "id": "T-two-state-1", "stem": "Which term fits this situation? A receptor sits inactive most of the time to save energy and flips to active on its own; a drug with affinity for the active form holds it there, a drug preferring the inactive form holds it back.", "options": [{"t": "Two-state model", "correct": true, "why": "This situation is two-state model: Receptors flip between inactive R and active R*; drugs shift the balance."}, {"t": "Intrinsic activity", "correct": false, "why": "Intrinsic activity would be: A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue."}, {"t": "Orthosteric site", "correct": false, "why": "Orthosteric site would be: The receptor’s own pocket where the endogenous agonist binds; one or the other."}, {"t": "Covalent bond", "correct": false, "why": "Covalent (irreversible) bond would be: Shared pair of electrons; unbreakable at body temperature; aspirin, omeprazole, phenoxybenzamine form it."}], "teach": "Receptors flip between inactive R and active R*; drugs shift the balance. “This is gonna be home for us.” It explains inverse agonists, which occupancy theory could not. Most receptors sit in the inactive state to save energy.", "fg": "two-state"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-two-state", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slide ~31; Pharmacodynamics-Day-1-2026s.pdf slide ~28; transcript 9/22; transcript 9/23", "quote": "So this two-state model shows that we have receptor two confirmations, active and inactive, and that drugs can shift them once bound to the receptor from one confirmation to the other.", "id": "T-two-state-2", "stem": "Two-state model means:", "options": [{"t": "Receptors flip between inactive R and active R*; drugs shift the balance.", "correct": true, "why": "That is two-state model."}, {"t": "A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue.", "correct": false, "why": "That is intrinsic activity, not two-state model."}, {"t": "The receptor’s own pocket where the endogenous agonist binds; one or the other.", "correct": false, "why": "That is orthosteric site, not two-state model."}, {"t": "Shared pair of electrons; unbreakable at body temperature; aspirin, omeprazole, phenoxybenzamine form it.", "correct": false, "why": "That is covalent (irreversible) bond, not two-state model."}], "teach": "Receptors flip between inactive R and active R*; drugs shift the balance. “This is gonna be home for us.” It explains inverse agonists, which occupancy theory could not. Most receptors sit in the inactive state to save energy.", "fg": "two-state", "dupOf": "T-two-state-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g2", "skill": "term", "concept": "term-two-state", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slide ~31; Pharmacodynamics-Day-1-2026s.pdf slide ~28; transcript 9/22; transcript 9/23", "quote": "So this two-state model shows that we have receptor two confirmations, active and inactive, and that drugs can shift them once bound to the receptor from one confirmation to the other.", "id": "T-two-state-3", "stem": "Which term is defined as: Receptors flip between inactive R and active R*; drugs shift the balance?", "options": [{"t": "Two-state model", "correct": true, "why": "This is the definition of Two-state model."}, {"t": "Intrinsic activity", "correct": false, "why": "Intrinsic activity: A number: full agonist 1, partial 0 to 1, antagonist 0; ignores the tissue."}, {"t": "Orthosteric site", "correct": false, "why": "Orthosteric site: The receptor’s own pocket where the endogenous agonist binds; one or the other."}, {"t": "Covalent bond", "correct": false, "why": "Covalent (irreversible) bond: Shared pair of electrons; unbreakable at body temperature; aspirin, omeprazole, phenoxybenzamine form it."}], "teach": "“This is gonna be home for us.” It explains inverse agonists, which occupancy theory could not. Most receptors sit in the inactive state to save energy.", "fg": "two-state", "dupOf": "T-two-state-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-full-agonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~33–~41; Pharmacodynamics-Day_2_2026s copy.pdf slides ~32–~34; transcript 9/23; transcript 9/24", "quote": "Let’s think about that we can dim, so we have one that can kind of go full bright or just halfway bright, a full agonist or a partial.", "id": "T-full-agonist-1", "stem": "Which term fits this situation? Norepinephrine on β1 drives the heart rate all the way to 100% of what the heart can produce, and epinephrine on the same receptor does the same; both reversible.", "options": [{"t": "Full agonist", "correct": true, "why": "This situation is full agonist: Prefers the active receptor, positive efficacy, reaches 100% of the system’s maximal response."}, {"t": "Partial agonist", "correct": false, "why": "Partial agonist would be: Positive efficacy but below 100%; may act as agonist or antagonist by state."}, {"t": "Inverse agonist", "correct": false, "why": "Inverse agonist would be: Prefers the inactive receptor; negative efficacy, takes the baseline down to zero."}, {"t": "Competitive antagonist", "correct": false, "why": "Competitive (reversible) antagonist would be: Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum."}], "teach": "Prefers the active receptor, positive efficacy, reaches 100% of the system’s maximal response. Same affinity preference as a partial agonist; the difference is efficacy (100% vs 1–99%). “I do not know of any agonist that is irreversible.”", "fg": "classes"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-full-agonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~33–~41; Pharmacodynamics-Day_2_2026s copy.pdf slides ~32–~34; transcript 9/23; transcript 9/24", "quote": "Let’s think about that we can dim, so we have one that can kind of go full bright or just halfway bright, a full agonist or a partial.", "id": "T-full-agonist-2", "stem": "Full agonist means:", "options": [{"t": "Prefers the active receptor, positive efficacy, reaches 100% of the system’s maximal response.", "correct": true, "why": "That is full agonist."}, {"t": "Blocks the transporter returning the neurotransmitter; more stays in the synapse, curve shifts left.", "correct": false, "why": "That is reuptake inhibitor (ssri / snri), not full agonist."}, {"t": "Positive efficacy but below 100%; may act as agonist or antagonist by state.", "correct": false, "why": "That is partial agonist, not full agonist."}, {"t": "Prefers the inactive receptor; negative efficacy, takes the baseline down to zero.", "correct": false, "why": "That is inverse agonist, not full agonist."}], "teach": "Prefers the active receptor, positive efficacy, reaches 100% of the system’s maximal response. Same affinity preference as a partial agonist; the difference is efficacy (100% vs 1–99%). “I do not know of any agonist that is irreversible.”", "fg": "classes", "dupOf": "T-full-agonist-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-full-agonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~33–~41; Pharmacodynamics-Day_2_2026s copy.pdf slides ~32–~34; transcript 9/23; transcript 9/24", "quote": "Let’s think about that we can dim, so we have one that can kind of go full bright or just halfway bright, a full agonist or a partial.", "id": "T-full-agonist-3", "stem": "Which term is defined as: Binds and stabilizes the receptor in the active state (R*): highest affinity for active-state receptors, positive (high) efficacy, and can reach 100% of the system’s maximal response. Examples: norepinephrine, epinephrine, acetylcholine?", "options": [{"t": "Full agonist", "correct": true, "why": "This is the definition of Full agonist."}, {"t": "Partial agonist", "correct": false, "why": "Partial agonist: Positive efficacy but below 100%; may act as agonist or antagonist by state."}, {"t": "Inverse agonist", "correct": false, "why": "Inverse agonist: Prefers the inactive receptor; negative efficacy, takes the baseline down to zero."}, {"t": "Competitive antagonist", "correct": false, "why": "Competitive (reversible) antagonist: Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum."}], "teach": "Same affinity preference as a partial agonist; the difference is efficacy (100% vs 1–99%). “I do not know of any agonist that is irreversible.”", "fg": "classes", "dupOf": "T-full-agonist-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-partial-agonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~50–~65; Pharmacodynamics-Day_2_2026s copy.pdf slides ~32–~34; transcript 9/23; transcript 9/24", "quote": "So sometimes we may use a partial agonist over a full agonist because we don’t need to get the max effect. We just need to get enough of it.", "id": "T-partial-agonist-1", "stem": "Which term fits this situation? Varenicline at the nicotinic receptor activates it enough to stop cravings in withdrawal but, in a smoker, competes with nicotine and brings the response down; pindolol raises a very low heart rate and lowers a high one.", "options": [{"t": "Partial agonist", "correct": true, "why": "This situation is partial agonist: Positive efficacy but below 100%; may act as agonist or antagonist by state."}, {"t": "Acetylcholinesterase inhibitor", "correct": false, "why": "Acetylcholinesterase inhibitor (physostigmine) would be: Blocks the enzyme breaking down acetylcholine; acetylcholine rises and appears more potent."}, {"t": "Inverse agonist", "correct": false, "why": "Inverse agonist would be: Prefers the inactive receptor; negative efficacy, takes the baseline down to zero."}, {"t": "Surmountable / insurmountable", "correct": false, "why": "Surmountable / insurmountable would be: Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost."}], "teach": "Positive efficacy but below 100%; may act as agonist or antagonist by state. Dual nature: it may act as an agonist or an antagonist depending on the physiological state (varenicline during smoking vs withdrawal). A partial agonist can still be the most potent drug on a graph.", "fg": "classes"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-partial-agonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~50–~65; Pharmacodynamics-Day_2_2026s copy.pdf slides ~32–~34; transcript 9/23; transcript 9/24", "quote": "So sometimes we may use a partial agonist over a full agonist because we don’t need to get the max effect. We just need to get enough of it.", "id": "T-partial-agonist-2", "stem": "Partial agonist means:", "options": [{"t": "Positive efficacy but below 100%; may act as agonist or antagonist by state.", "correct": true, "why": "That is partial agonist."}, {"t": "Prefers the inactive receptor; negative efficacy, takes the baseline down to zero.", "correct": false, "why": "That is inverse agonist, not partial agonist."}, {"t": "Blocks the enzyme breaking down acetylcholine; acetylcholine rises and appears more potent.", "correct": false, "why": "That is acetylcholinesterase inhibitor (physostigmine), not partial agonist."}, {"t": "Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost.", "correct": false, "why": "That is surmountable / insurmountable, not partial agonist."}], "teach": "Positive efficacy but below 100%; may act as agonist or antagonist by state. Dual nature: it may act as an agonist or an antagonist depending on the physiological state (varenicline during smoking vs withdrawal). A partial agonist can still be the most potent drug on a graph.", "fg": "classes", "dupOf": "T-partial-agonist-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-inverse-agonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~35–~36; Pharmacodynamics-Day-1-2026s.pdf slide ~28; transcript 9/22; transcript 9/23", "quote": "These drugs love to bind to receptors that are inactive and keep them inactive. But they have what is called negative efficacy, which means is if they bind to a receptor that is already active, producing a signal, once they are bound, they’re going to shut them off.", "id": "T-inverse-agonist-1", "stem": "Which term fits this situation? In a petri dish where half the H1 receptors are active by themselves, loratadine brings cyclic AMP production to zero; with histamine present, histamine must be raised to compete.", "options": [{"t": "Inverse agonist", "correct": true, "why": "This situation is inverse agonist: Prefers the inactive receptor; negative efficacy, takes the baseline down to zero."}, {"t": "Indirect antagonist", "correct": false, "why": "Indirect antagonist would be: Binds upstream or downstream of the receptor, never the receptor; raises or lowers response."}, {"t": "Antagonist", "correct": false, "why": "Antagonist (neutral, reversible) would be: Zero efficacy, equal affinity for both receptor states; occupies, changes no balance."}, {"t": "Partial agonist", "correct": false, "why": "Partial agonist would be: Positive efficacy but below 100%; may act as agonist or antagonist by state."}], "teach": "Prefers the inactive receptor; negative efficacy, takes the baseline down to zero. Petri dish with 50% of receptors naturally active: an inverse agonist brings cAMP production to zero; a competitive (neutral) antagonist leaves it at 50%.", "fg": "classes"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-inverse-agonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~35–~36; Pharmacodynamics-Day-1-2026s.pdf slide ~28; transcript 9/22; transcript 9/23", "quote": "These drugs love to bind to receptors that are inactive and keep them inactive. But they have what is called negative efficacy, which means is if they bind to a receptor that is already active, producing a signal, once they are bound, they’re going to shut them off.", "id": "T-inverse-agonist-2", "stem": "Inverse agonist means:", "options": [{"t": "Prefers the inactive receptor; negative efficacy, takes the baseline down to zero.", "correct": true, "why": "That is inverse agonist."}, {"t": "Zero efficacy, equal affinity for both receptor states; occupies, changes no balance.", "correct": false, "why": "That is antagonist (neutral, reversible), not inverse agonist."}, {"t": "Positive efficacy but below 100%; may act as agonist or antagonist by state.", "correct": false, "why": "That is partial agonist, not inverse agonist."}, {"t": "Prefers the active receptor, positive efficacy, reaches 100% of the system’s maximal response.", "correct": false, "why": "That is full agonist, not inverse agonist."}], "teach": "Prefers the inactive receptor; negative efficacy, takes the baseline down to zero. Petri dish with 50% of receptors naturally active: an inverse agonist brings cAMP production to zero; a competitive (neutral) antagonist leaves it at 50%.", "fg": "classes", "dupOf": "T-inverse-agonist-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-inverse-agonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~35–~36; Pharmacodynamics-Day-1-2026s.pdf slide ~28; transcript 9/22; transcript 9/23", "quote": "These drugs love to bind to receptors that are inactive and keep them inactive. But they have what is called negative efficacy, which means is if they bind to a receptor that is already active, producing a signal, once they are bound, they’re going to shut them off.", "id": "T-inverse-agonist-3", "stem": "Which term is defined as: Has the highest affinity for inactive receptors and negative efficacy: if it binds an active receptor it inhibits it, shifting receptors to the inactive state. Example: the antihistamine loratadine at H1?", "options": [{"t": "Inverse agonist", "correct": true, "why": "This is the definition of Inverse agonist."}, {"t": "Indirect antagonist", "correct": false, "why": "Indirect antagonist: Binds upstream or downstream of the receptor, never the receptor; raises or lowers response."}, {"t": "Antagonist", "correct": false, "why": "Antagonist (neutral, reversible): Zero efficacy, equal affinity for both receptor states; occupies, changes no balance."}, {"t": "Partial agonist", "correct": false, "why": "Partial agonist: Positive efficacy but below 100%; may act as agonist or antagonist by state."}], "teach": "Petri dish with 50% of receptors naturally active: an inverse agonist brings cAMP production to zero; a competitive (neutral) antagonist leaves it at 50%.", "fg": "classes", "dupOf": "T-inverse-agonist-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-neutral-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~37–~38; transcript 9/23; transcript 9/24", "quote": "Antagonists, they’re neutral. Like they don’t care if the receptor is active or inactive, they have equal affinity for both receptor states.", "id": "T-neutral-antagonist-1", "stem": "Which term fits this situation? In a petri dish with half the receptors active, prazosin or metoprolol is added and the cyclic AMP stays at 50%: a straight line, the receptors keep whatever state they had.", "options": [{"t": "Antagonist", "correct": true, "why": "This situation is antagonist (neutral, reversible): Zero efficacy, equal affinity for both receptor states; occupies, changes no balance."}, {"t": "Inverse agonist", "correct": false, "why": "Inverse agonist would be: Prefers the inactive receptor; negative efficacy, takes the baseline down to zero."}, {"t": "Partial agonist", "correct": false, "why": "Partial agonist would be: Positive efficacy but below 100%; may act as agonist or antagonist by state."}, {"t": "Surmountable / insurmountable", "correct": false, "why": "Surmountable / insurmountable would be: Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost."}], "teach": "Zero efficacy, equal affinity for both receptor states; occupies, changes no balance. “Just a straight line”: an antagonist does not change the balance of receptors; an inverse agonist wants to keep everybody inactive. Intrinsic activity of an antagonist is zero.", "fg": "classes"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-neutral-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~37–~38; transcript 9/23; transcript 9/24", "quote": "Antagonists, they’re neutral. Like they don’t care if the receptor is active or inactive, they have equal affinity for both receptor states.", "id": "T-neutral-antagonist-2", "stem": "Antagonist means:", "options": [{"t": "Zero efficacy, equal affinity for both receptor states; occupies, changes no balance.", "correct": true, "why": "That is antagonist (neutral, reversible)."}, {"t": "Blocks the transporter returning the neurotransmitter; more stays in the synapse, curve shifts left.", "correct": false, "why": "That is reuptake inhibitor (ssri / snri), not antagonist (neutral, reversible)."}, {"t": "Prefers the inactive receptor; negative efficacy, takes the baseline down to zero.", "correct": false, "why": "That is inverse agonist, not antagonist (neutral, reversible)."}, {"t": "Positive efficacy but below 100%; may act as agonist or antagonist by state.", "correct": false, "why": "That is partial agonist, not antagonist (neutral, reversible)."}], "teach": "Zero efficacy, equal affinity for both receptor states; occupies, changes no balance. “Just a straight line”: an antagonist does not change the balance of receptors; an inverse agonist wants to keep everybody inactive. Intrinsic activity of an antagonist is zero.", "fg": "classes", "dupOf": "T-neutral-antagonist-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-neutral-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~37–~38; transcript 9/23; transcript 9/24", "quote": "Antagonists, they’re neutral. Like they don’t care if the receptor is active or inactive, they have equal affinity for both receptor states.", "id": "T-neutral-antagonist-3", "stem": "Which term is defined as: Zero efficacy, equal affinity for both receptor states; occupies, changes no balance?", "options": [{"t": "Antagonist", "correct": true, "why": "This is the definition of Antagonist (neutral, reversible)."}, {"t": "Inverse agonist", "correct": false, "why": "Inverse agonist: Prefers the inactive receptor; negative efficacy, takes the baseline down to zero."}, {"t": "Partial agonist", "correct": false, "why": "Partial agonist: Positive efficacy but below 100%; may act as agonist or antagonist by state."}, {"t": "Surmountable / insurmountable", "correct": false, "why": "Surmountable / insurmountable: Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost."}], "teach": "“Just a straight line”: an antagonist does not change the balance of receptors; an inverse agonist wants to keep everybody inactive. Intrinsic activity of an antagonist is zero.", "fg": "classes", "dupOf": "T-neutral-antagonist-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-competitive-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~15–~16, ~18, ~37; transcript 9/23", "quote": "when we think about uh ionic bonds, hydrogen bonds, [van der Waals] bonds, those are going to be reversible, surmountable, competitive. Different words ... they’re gonna bind and they’re gonna come off.", "id": "T-competitive-antagonist-1", "stem": "Which term fits this situation? Prazosin sits in the α1 pocket but comes off, so when norepinephrine is raised tenfold it wins back the receptors; the curve moves right in equal steps and still reaches its top.", "options": [{"t": "Competitive antagonist", "correct": true, "why": "This situation is competitive (reversible) antagonist: Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum."}, {"t": "Irreversible antagonist", "correct": false, "why": "Irreversible (non-competitive) antagonist would be: Covalent, never comes off; agonist cannot outcompete it, the maximum falls toward zero."}, {"t": "Indirect antagonist", "correct": false, "why": "Indirect antagonist would be: Binds upstream or downstream of the receptor, never the receptor; raises or lowers response."}, {"t": "Chemical antagonist", "correct": false, "why": "Chemical antagonist would be: Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury."}], "teach": "Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum. Every drug on the Exam 1 drug list is reversible and competitive except phenoxybenzamine. On the curve: shift to the right, symmetrical shifts toward infinity, no change to the baseline, no change to the Emax, because they bind and they come off.", "fg": "classes"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-competitive-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~15–~16, ~18, ~37; transcript 9/23", "quote": "when we think about uh ionic bonds, hydrogen bonds, [van der Waals] bonds, those are going to be reversible, surmountable, competitive. Different words ... they’re gonna bind and they’re gonna come off.", "id": "T-competitive-antagonist-2", "stem": "Competitive antagonist means:", "options": [{"t": "Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum.", "correct": true, "why": "That is competitive (reversible) antagonist."}, {"t": "Covalent, never comes off; agonist cannot outcompete it, the maximum falls toward zero.", "correct": false, "why": "That is irreversible (non-competitive) antagonist, not competitive (reversible) antagonist."}, {"t": "Binds upstream or downstream of the receptor, never the receptor; raises or lowers response.", "correct": false, "why": "That is indirect antagonist, not competitive (reversible) antagonist."}, {"t": "Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury.", "correct": false, "why": "That is chemical antagonist, not competitive (reversible) antagonist."}], "teach": "Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum. Every drug on the Exam 1 drug list is reversible and competitive except phenoxybenzamine. On the curve: shift to the right, symmetrical shifts toward infinity, no change to the baseline, no change to the Emax, because they bind and they come off.", "fg": "classes", "dupOf": "T-competitive-antagonist-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-competitive-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~15–~16, ~18, ~37; transcript 9/23", "quote": "when we think about uh ionic bonds, hydrogen bonds, [van der Waals] bonds, those are going to be reversible, surmountable, competitive. Different words ... they’re gonna bind and they’re gonna come off.", "id": "T-competitive-antagonist-3", "stem": "Which term is defined as: Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum?", "options": [{"t": "Competitive antagonist", "correct": true, "why": "This is the definition of Competitive (reversible) antagonist."}, {"t": "Irreversible antagonist", "correct": false, "why": "Irreversible (non-competitive) antagonist: Covalent, never comes off; agonist cannot outcompete it, the maximum falls toward zero."}, {"t": "Indirect antagonist", "correct": false, "why": "Indirect antagonist: Binds upstream or downstream of the receptor, never the receptor; raises or lowers response."}, {"t": "Chemical antagonist", "correct": false, "why": "Chemical antagonist: Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury."}], "teach": "Every drug on the Exam 1 drug list is reversible and competitive except phenoxybenzamine. On the curve: shift to the right, symmetrical shifts toward infinity, no change to the baseline, no change to the Emax, because they bind and they come off.", "fg": "classes", "dupOf": "T-competitive-antagonist-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-irreversible-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~15, ~18, ~37–~38; transcript 9/23; transcript 9/24", "quote": "This is an irreversible antagonist, non-competitive, insurmountable. So what kind of bo[n]ds does it form? Covalent.", "id": "T-irreversible-antagonist-1", "stem": "Which term fits this situation? Phenoxybenzamine forms a covalent bond at α1 and does not come off; the receptor must be internalized and replaced, and with enough of it norepinephrine can no longer reach its top response.", "options": [{"t": "Irreversible antagonist", "correct": true, "why": "This situation is irreversible (non-competitive) antagonist: Covalent, never comes off; agonist cannot outcompete it, the maximum falls toward zero."}, {"t": "Acetylcholinesterase inhibitor", "correct": false, "why": "Acetylcholinesterase inhibitor (physostigmine) would be: Blocks the enzyme breaking down acetylcholine; acetylcholine rises and appears more potent."}, {"t": "Competitive antagonist", "correct": false, "why": "Competitive (reversible) antagonist would be: Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum."}, {"t": "Inverse agonist", "correct": false, "why": "Inverse agonist would be: Prefers the inactive receptor; negative efficacy, takes the baseline down to zero."}], "teach": "Covalent, never comes off; agonist cannot outcompete it, the maximum falls toward zero. Once phenoxybenzamine is bound the receptor has to be internalized and recycled and the body must make new ones. Poll: phenoxybenzamine has higher affinity than prazosin. On the curve: shift right, no change to the baseline, Emax down, all the way to 0 (can abolish the DRC); spare receptors delay the drop.", "fg": "classes"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-irreversible-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~15, ~18, ~37–~38; transcript 9/23; transcript 9/24", "quote": "This is an irreversible antagonist, non-competitive, insurmountable. So what kind of bo[n]ds does it form? Covalent.", "id": "T-irreversible-antagonist-2", "stem": "Irreversible antagonist means:", "options": [{"t": "Covalent, never comes off; agonist cannot outcompete it, the maximum falls toward zero.", "correct": true, "why": "That is irreversible (non-competitive) antagonist."}, {"t": "Blocks the enzyme breaking down acetylcholine; acetylcholine rises and appears more potent.", "correct": false, "why": "That is acetylcholinesterase inhibitor (physostigmine), not irreversible (non-competitive) antagonist."}, {"t": "Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum.", "correct": false, "why": "That is competitive (reversible) antagonist, not irreversible (non-competitive) antagonist."}, {"t": "Prefers the inactive receptor; negative efficacy, takes the baseline down to zero.", "correct": false, "why": "That is inverse agonist, not irreversible (non-competitive) antagonist."}], "teach": "Covalent, never comes off; agonist cannot outcompete it, the maximum falls toward zero. Once phenoxybenzamine is bound the receptor has to be internalized and recycled and the body must make new ones. Poll: phenoxybenzamine has higher affinity than prazosin. On the curve: shift right, no change to the baseline, Emax down, all the way to 0 (can abolish the DRC); spare receptors delay the drop.", "fg": "classes", "dupOf": "T-irreversible-antagonist-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-irreversible-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~15, ~18, ~37–~38; transcript 9/23; transcript 9/24", "quote": "This is an irreversible antagonist, non-competitive, insurmountable. So what kind of bo[n]ds does it form? Covalent.", "id": "T-irreversible-antagonist-3", "stem": "Which term is defined as: Covalent, never comes off; agonist cannot outcompete it, the maximum falls toward zero?", "options": [{"t": "Irreversible antagonist", "correct": true, "why": "This is the definition of Irreversible (non-competitive) antagonist."}, {"t": "Acetylcholinesterase inhibitor", "correct": false, "why": "Acetylcholinesterase inhibitor (physostigmine): Blocks the enzyme breaking down acetylcholine; acetylcholine rises and appears more potent."}, {"t": "Competitive antagonist", "correct": false, "why": "Competitive (reversible) antagonist: Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum."}, {"t": "Inverse agonist", "correct": false, "why": "Inverse agonist: Prefers the inactive receptor; negative efficacy, takes the baseline down to zero."}], "teach": "Once phenoxybenzamine is bound the receptor has to be internalized and recycled and the body must make new ones. Poll: phenoxybenzamine has higher affinity than prazosin. On the curve: shift right, no change to the baseline, Emax down, all the way to 0 (can abolish the DRC); spare receptors delay the drop.", "fg": "classes", "dupOf": "T-irreversible-antagonist-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-indirect-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~40–~41; Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 4–13; transcript 9/23; transcript 9/24; transcript 9/29", "quote": "So, remember that indirect antagonists can work downstream from the receptor, but also upstream from the receptor, OK?", "id": "T-indirect-antagonist-1", "stem": "Which term fits this situation? Caffeine blocks phosphodiesterase (PDE) so cyclic AMP piles up and the agonist looks more potent; a cancer drug blocks RAS and the cells stop growing. Neither touches the receptor.", "options": [{"t": "Indirect antagonist", "correct": true, "why": "This situation is indirect antagonist: Binds upstream or downstream of the receptor, never the receptor; raises or lowers response."}, {"t": "Allosteric site / modulator", "correct": false, "why": "Allosteric site / modulator would be: A second place on the receptor; changes another drug’s affinity or efficacy; both bound."}, {"t": "Competitive antagonist", "correct": false, "why": "Competitive (reversible) antagonist would be: Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum."}, {"t": "Inverse agonist", "correct": false, "why": "Inverse agonist would be: Prefers the inactive receptor; negative efficacy, takes the baseline down to zero."}], "teach": "Binds upstream or downstream of the receptor, never the receptor; raises or lowers response. It can raise the response (caffeine on PDE raises cAMP; a norepinephrine transporter blocker makes norepinephrine appear more potent) or lower it (RAS blocker stops cell growth). It is not allosteric: it never touches the receptor.", "fg": "ind-ssri"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-indirect-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~40–~41; Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 4–13; transcript 9/23; transcript 9/24; transcript 9/29", "quote": "So, remember that indirect antagonists can work downstream from the receptor, but also upstream from the receptor, OK?", "id": "T-indirect-antagonist-2", "stem": "Indirect antagonist means:", "options": [{"t": "Binds upstream or downstream of the receptor, never the receptor; raises or lowers response.", "correct": true, "why": "That is indirect antagonist."}, {"t": "Blocks the transporter returning the neurotransmitter; more stays in the synapse, curve shifts left.", "correct": false, "why": "That is reuptake inhibitor (ssri / snri), not indirect antagonist."}, {"t": "A second place on the receptor; changes another drug’s affinity or efficacy; both bound.", "correct": false, "why": "That is allosteric site / modulator, not indirect antagonist."}, {"t": "Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum.", "correct": false, "why": "That is competitive (reversible) antagonist, not indirect antagonist."}], "teach": "Binds upstream or downstream of the receptor, never the receptor; raises or lowers response. It can raise the response (caffeine on PDE raises cAMP; a norepinephrine transporter blocker makes norepinephrine appear more potent) or lower it (RAS blocker stops cell growth). It is not allosteric: it never touches the receptor.", "fg": "ind-ssri", "dupOf": "T-indirect-antagonist-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-indirect-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~40–~41; Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 4–13; transcript 9/23; transcript 9/24; transcript 9/29", "quote": "So, remember that indirect antagonists can work downstream from the receptor, but also upstream from the receptor, OK?", "id": "T-indirect-antagonist-3", "stem": "Which term is defined as: A drug that inhibits the generation of a biological response by binding to components upstream or downstream from the receptor rather than the receptor itself; it can be reversible or irreversible. Examples: caffeine blocking PDE, a cancer drug blocking RAS?", "options": [{"t": "Indirect antagonist", "correct": true, "why": "This is the definition of Indirect antagonist."}, {"t": "Allosteric site / modulator", "correct": false, "why": "Allosteric site / modulator: A second place on the receptor; changes another drug’s affinity or efficacy; both bound."}, {"t": "Competitive antagonist", "correct": false, "why": "Competitive (reversible) antagonist: Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum."}, {"t": "Inverse agonist", "correct": false, "why": "Inverse agonist: Prefers the inactive receptor; negative efficacy, takes the baseline down to zero."}], "teach": "It can raise the response (caffeine on PDE raises cAMP; a norepinephrine transporter blocker makes norepinephrine appear more potent) or lower it (RAS blocker stops cell growth). It is not allosteric: it never touches the receptor.", "fg": "ind-ssri", "dupOf": "T-indirect-antagonist-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-allosteric-agonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~21–~24, ~42; transcript 9/23", "quote": "Benzos increase the affinity And/or efficacy of GABA For its receptor", "id": "T-allosteric-agonist-1", "stem": "Which term fits this situation? Diazepam binds the GABA-A chloride channel away from where GABA (gamma-aminobutyric acid) binds, and GABA then opens the channel more readily; add alcohol and two such drugs are on the one receptor.", "options": [{"t": "Allosteric agonist", "correct": true, "why": "This situation is allosteric agonist (pam): Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam."}, {"t": "Surmountable / insurmountable", "correct": false, "why": "Surmountable / insurmountable would be: Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost."}, {"t": "Full agonist", "correct": false, "why": "Full agonist would be: Prefers the active receptor, positive efficacy, reaches 100% of the system’s maximal response."}, {"t": "Chemical antagonist", "correct": false, "why": "Chemical antagonist would be: Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury."}], "teach": "Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam. Diazepam is the allosteric agonist on the drug list “that you have to know for your exam.” A benzodiazepine plus alcohol puts two allosteric agonists on one receptor.", "fg": "classes"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-allosteric-agonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~21–~24, ~42; transcript 9/23", "quote": "Benzos increase the affinity And/or efficacy of GABA For its receptor", "id": "T-allosteric-agonist-2", "stem": "Allosteric agonist means:", "options": [{"t": "Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam.", "correct": true, "why": "That is allosteric agonist (pam)."}, {"t": "Prefers the active receptor, positive efficacy, reaches 100% of the system’s maximal response.", "correct": false, "why": "That is full agonist, not allosteric agonist (pam)."}, {"t": "Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost.", "correct": false, "why": "That is surmountable / insurmountable, not allosteric agonist (pam)."}, {"t": "Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury.", "correct": false, "why": "That is chemical antagonist, not allosteric agonist (pam)."}], "teach": "Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam. Diazepam is the allosteric agonist on the drug list “that you have to know for your exam.” A benzodiazepine plus alcohol puts two allosteric agonists on one receptor.", "fg": "classes", "dupOf": "T-allosteric-agonist-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-allosteric-agonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~21–~24, ~42; transcript 9/23", "quote": "Benzos increase the affinity And/or efficacy of GABA For its receptor", "id": "T-allosteric-agonist-3", "stem": "Which term is defined as: Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam?", "options": [{"t": "Allosteric agonist", "correct": true, "why": "This is the definition of Allosteric agonist (PAM)."}, {"t": "Surmountable / insurmountable", "correct": false, "why": "Surmountable / insurmountable: Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost."}, {"t": "Full agonist", "correct": false, "why": "Full agonist: Prefers the active receptor, positive efficacy, reaches 100% of the system’s maximal response."}, {"t": "Chemical antagonist", "correct": false, "why": "Chemical antagonist: Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury."}], "teach": "Diazepam is the allosteric agonist on the drug list “that you have to know for your exam.” A benzodiazepine plus alcohol puts two allosteric agonists on one receptor.", "fg": "classes", "dupOf": "T-allosteric-agonist-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-allosteric-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~43; transcript 9/23", "quote": "Allosteric Antagonist: Binds at a different binding site in the receptor; Can decrease the affinity and/or efficacy of another drug for the receptor", "id": "T-allosteric-antagonist-1", "stem": "Which term fits this situation? A drug binds the receptor outside the agonist’s pocket, so both are bound at once, and the agonist now needs more dose or cannot reach its top; the shifts are unequal and stop after enough doses.", "options": [{"t": "Allosteric antagonist", "correct": true, "why": "This situation is allosteric antagonist (nam): Binds a second site and decreases another drug’s affinity and/or efficacy; reversible."}, {"t": "Competitive antagonist", "correct": false, "why": "Competitive (reversible) antagonist would be: Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum."}, {"t": "Allosteric agonist", "correct": false, "why": "Allosteric agonist (PAM) would be: Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam."}, {"t": "Indirect antagonist", "correct": false, "why": "Indirect antagonist would be: Binds upstream or downstream of the receptor, never the receptor; raises or lowers response."}], "teach": "Binds a second site and decreases another drug’s affinity and/or efficacy; reversible. Literature name: negative allosteric modulator (NAM); the allosteric agonist is the PAM. It does not compete for the orthosteric pocket; a competitive antagonist does. “As far as I know, all allosteric agonists and antagonists are reversible.”", "fg": "classes"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-allosteric-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~43; transcript 9/23", "quote": "Allosteric Antagonist: Binds at a different binding site in the receptor; Can decrease the affinity and/or efficacy of another drug for the receptor", "id": "T-allosteric-antagonist-2", "stem": "Allosteric antagonist means:", "options": [{"t": "Binds a second site and decreases another drug’s affinity and/or efficacy; reversible.", "correct": true, "why": "That is allosteric antagonist (nam)."}, {"t": "Binds upstream or downstream of the receptor, never the receptor; raises or lowers response.", "correct": false, "why": "That is indirect antagonist, not allosteric antagonist (nam)."}, {"t": "Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam.", "correct": false, "why": "That is allosteric agonist (pam), not allosteric antagonist (nam)."}, {"t": "Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum.", "correct": false, "why": "That is competitive (reversible) antagonist, not allosteric antagonist (nam)."}], "teach": "Binds a second site and decreases another drug’s affinity and/or efficacy; reversible. Literature name: negative allosteric modulator (NAM); the allosteric agonist is the PAM. It does not compete for the orthosteric pocket; a competitive antagonist does. “As far as I know, all allosteric agonists and antagonists are reversible.”", "fg": "classes", "dupOf": "T-allosteric-antagonist-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-allosteric-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~43; transcript 9/23", "quote": "Allosteric Antagonist: Binds at a different binding site in the receptor; Can decrease the affinity and/or efficacy of another drug for the receptor", "id": "T-allosteric-antagonist-3", "stem": "Which term is defined as: Binds at a different site on the receptor and decreases the affinity and/or efficacy of another drug for the receptor?", "options": [{"t": "Allosteric antagonist", "correct": true, "why": "This is the definition of Allosteric antagonist (NAM)."}, {"t": "Competitive antagonist", "correct": false, "why": "Competitive (reversible) antagonist: Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum."}, {"t": "Allosteric agonist", "correct": false, "why": "Allosteric agonist (PAM): Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam."}, {"t": "Indirect antagonist", "correct": false, "why": "Indirect antagonist: Binds upstream or downstream of the receptor, never the receptor; raises or lowers response."}], "teach": "Literature name: negative allosteric modulator (NAM); the allosteric agonist is the PAM. It does not compete for the orthosteric pocket; a competitive antagonist does. “As far as I know, all allosteric agonists and antagonists are reversible.”", "fg": "classes", "dupOf": "T-allosteric-antagonist-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-drc", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~8–~10, ~16–~18; Pharmacodynamics-Day_2_2026s copy.pdf slide ~56; transcript 9/24", "quote": "So my dose is going to be on the bottom, on the X axis. My response is gonna be on the Y axis, which is on the up or down, OK?", "id": "T-drc-1", "stem": "Which term fits this situation? Increasing doses of norepinephrine are given and the heart rate at each is plotted as percent of the maximum against log dose; the points trace an S shape from which the ED50 is read.", "options": [{"t": "Dose–response curve", "correct": true, "why": "This situation is dose–response curve (drc / crc): Log dose on the x-axis, percent of maximal effect on the y-axis; sigmoid."}, {"t": "Symmetrical vs asymmetrical shifts", "correct": false, "why": "Symmetrical vs asymmetrical shifts would be: Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric."}, {"t": "Binding curve", "correct": false, "why": "Binding curve (Bmax) would be: Percent of receptors bound versus log concentration; shows occupancy only, not effect."}, {"t": "Graded response", "correct": false, "why": "Graded response would be: Measured in one biological unit on a continuous scale, rising by degrees with dose."}], "teach": "Log dose on the x-axis, percent of maximal effect on the y-axis; sigmoid. DRC: increasing individual doses in vivo (ADME, apparent potency). CRC: increasing concentration in vitro (molar, pharmacological potency). Affinity is on the x-axis, efficacy on the y-axis, potency a combination of the two.", "fg": "drc-basic"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-drc", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~8–~10, ~16–~18; Pharmacodynamics-Day_2_2026s copy.pdf slide ~56; transcript 9/24", "quote": "So my dose is going to be on the bottom, on the X axis. My response is gonna be on the Y axis, which is on the up or down, OK?", "id": "T-drc-2", "stem": "Dose–response curve means:", "options": [{"t": "Log dose on the x-axis, percent of maximal effect on the y-axis; sigmoid.", "correct": true, "why": "That is dose–response curve (drc / crc)."}, {"t": "Percent of receptors bound versus log concentration; shows occupancy only, not effect.", "correct": false, "why": "That is binding curve (bmax), not dose–response curve (drc / crc)."}, {"t": "Measured in one biological unit on a continuous scale, rising by degrees with dose.", "correct": false, "why": "That is graded response, not dose–response curve (drc / crc)."}, {"t": "In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age.", "correct": false, "why": "That is apparent potency, not dose–response curve (drc / crc)."}], "teach": "Log dose on the x-axis, percent of maximal effect on the y-axis; sigmoid. DRC: increasing individual doses in vivo (ADME, apparent potency). CRC: increasing concentration in vitro (molar, pharmacological potency). Affinity is on the x-axis, efficacy on the y-axis, potency a combination of the two.", "fg": "drc-basic", "dupOf": "T-drc-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-graded-response", "tags": ["term"], "source": "slide", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~10, ~16, ~18; transcript 9/24", "quote": "Graded response by multiple increases of drug doses over a specific range", "id": "T-graded-response-1", "stem": "Which term fits this situation? One strip of muscle in a bath is given nicotine in 10-fold steps and the degree of contraction is measured at each step: a little, then more, then more.", "options": [{"t": "Graded response", "correct": true, "why": "This situation is graded response: Measured in one biological unit on a continuous scale, rising by degrees with dose."}, {"t": "Apparent potency", "correct": false, "why": "Apparent potency would be: In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age."}, {"t": "Threshold", "correct": false, "why": "Threshold would be: The dose right before something happens; below it, no effect at all."}, {"t": "EC50 / ED50", "correct": false, "why": "EC50 / ED50 would be: Concentration (or dose) producing 50% of the maximal response; smaller means more potent."}], "teach": "Measured in one biological unit on a continuous scale, rising by degrees with dose. The y-axis is normalized (% of maximum response or response per tissue weight) to eliminate biological variability between individuals: “now I can compare apples with apples.”"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-graded-response", "tags": ["term"], "source": "slide", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~10, ~16, ~18; transcript 9/24", "quote": "Graded response by multiple increases of drug doses over a specific range", "id": "T-graded-response-2", "stem": "Graded response means:", "options": [{"t": "Measured in one biological unit on a continuous scale, rising by degrees with dose.", "correct": true, "why": "That is graded response."}, {"t": "Concentration (or dose) producing 50% of the maximal response; smaller means more potent.", "correct": false, "why": "That is ec50 / ed50, not graded response."}, {"t": "The dose right before something happens; below it, no effect at all.", "correct": false, "why": "That is threshold, not graded response."}, {"t": "Where the curve starts: receptor activity before any drug; 0% if most inactive.", "correct": false, "why": "That is baseline (point of reference), not graded response."}], "teach": "Measured in one biological unit on a continuous scale, rising by degrees with dose. The y-axis is normalized (% of maximum response or response per tissue weight) to eliminate biological variability between individuals: “now I can compare apples with apples.”", "dupOf": "T-graded-response-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-graded-response", "tags": ["term"], "source": "slide", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~10, ~16, ~18; transcript 9/24", "quote": "Graded response by multiple increases of drug doses over a specific range", "id": "T-graded-response-3", "stem": "Which term is defined as: Measured in one biological unit on a continuous scale, rising by degrees with dose?", "options": [{"t": "Graded response", "correct": true, "why": "This is the definition of Graded response."}, {"t": "Apparent potency", "correct": false, "why": "Apparent potency: In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age."}, {"t": "Threshold", "correct": false, "why": "Threshold: The dose right before something happens; below it, no effect at all."}, {"t": "EC50 / ED50", "correct": false, "why": "EC50 / ED50: Concentration (or dose) producing 50% of the maximal response; smaller means more potent."}], "teach": "The y-axis is normalized (% of maximum response or response per tissue weight) to eliminate biological variability between individuals: “now I can compare apples with apples.”", "dupOf": "T-graded-response-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-threshold", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~20–~21; transcript 9/24", "quote": "Remember that the threshold is the dose right before something happens, right? So I know that at any dose below this, no effect.", "id": "T-threshold-1", "stem": "Which term fits this situation? A tissue is given 10^-9 molar and nothing happens; at 10^-8 the first effect appears. The dose right before the effect appeared is where the curve starts.", "options": [{"t": "Threshold", "correct": true, "why": "This situation is threshold: The dose right before something happens; below it, no effect at all."}, {"t": "Therapeutic index", "correct": false, "why": "Therapeutic index (TI) would be: Lethal dose for 50% over effective dose for 50%; larger is safer."}, {"t": "Slope", "correct": false, "why": "Slope would be: The linear mid-section; greatest change in effect from the smallest change in dose."}, {"t": "Symmetrical vs asymmetrical shifts", "correct": false, "why": "Symmetrical vs asymmetrical shifts would be: Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric."}], "teach": "The dose right before something happens; below it, no effect at all. Threshold is where the curve starts; EC50 is the halfway point; Emax is the ceiling.", "fg": "drc-basic"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-threshold", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~20–~21; transcript 9/24", "quote": "Remember that the threshold is the dose right before something happens, right? So I know that at any dose below this, no effect.", "id": "T-threshold-2", "stem": "Threshold means:", "options": [{"t": "The dose right before something happens; below it, no effect at all.", "correct": true, "why": "That is threshold."}, {"t": "The linear mid-section; greatest change in effect from the smallest change in dose.", "correct": false, "why": "That is slope, not threshold."}, {"t": "Lethal dose for 50% over effective dose for 50%; larger is safer.", "correct": false, "why": "That is therapeutic index (ti), not threshold."}, {"t": "Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric.", "correct": false, "why": "That is symmetrical vs asymmetrical shifts, not threshold."}], "teach": "The dose right before something happens; below it, no effect at all. Threshold is where the curve starts; EC50 is the halfway point; Emax is the ceiling.", "fg": "drc-basic", "dupOf": "T-threshold-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-threshold", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~20–~21; transcript 9/24", "quote": "Remember that the threshold is the dose right before something happens, right? So I know that at any dose below this, no effect.", "id": "T-threshold-3", "stem": "Which term is defined as: The concentration of the drug below which there is no response: the dose right before something happens. It must be known, with Emax, to calculate the EC50/ED50?", "options": [{"t": "Threshold", "correct": true, "why": "This is the definition of Threshold."}, {"t": "Therapeutic index", "correct": false, "why": "Therapeutic index (TI): Lethal dose for 50% over effective dose for 50%; larger is safer."}, {"t": "Slope", "correct": false, "why": "Slope: The linear mid-section; greatest change in effect from the smallest change in dose."}, {"t": "Symmetrical vs asymmetrical shifts", "correct": false, "why": "Symmetrical vs asymmetrical shifts: Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric."}], "teach": "Threshold is where the curve starts; EC50 is the halfway point; Emax is the ceiling.", "fg": "drc-basic", "dupOf": "T-threshold-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-emax", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~11–~14, ~20–~21, ~27; transcript 9/24", "quote": "What are the two reasons why we have reached the Emacs and we can’t keep going up? All the receptors are occupied or I max out the physiological system, right?", "id": "T-emax-1", "stem": "Which term fits this situation? Adding more norepinephrine past a certain dose does not raise the heart rate any further, either because every receptor is occupied or because the heart cannot beat faster.", "options": [{"t": "Emax", "correct": true, "why": "This situation is emax (maximal response, ceiling): The plateau: all receptors occupied or the physiological system maxed out."}, {"t": "EC50 / ED50", "correct": false, "why": "EC50 / ED50 would be: Concentration (or dose) producing 50% of the maximal response; smaller means more potent."}, {"t": "Threshold", "correct": false, "why": "Threshold would be: The dose right before something happens; below it, no effect at all."}, {"t": "Therapeutic index", "correct": false, "why": "Therapeutic index (TI) would be: Lethal dose for 50% over effective dose for 50%; larger is safer."}], "teach": "The plateau: all receptors occupied or the physiological system maxed out. Giving more drug past the ceiling does no more good. Curves with equal Emax differ by affinity; when EC50 is equal, greater efficacy makes the drug more potent (Relative Efficacy slide).", "fg": "drc-basic"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-emax", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~11–~14, ~20–~21, ~27; transcript 9/24", "quote": "What are the two reasons why we have reached the Emacs and we can’t keep going up? All the receptors are occupied or I max out the physiological system, right?", "id": "T-emax-2", "stem": "Emax means:", "options": [{"t": "The plateau: all receptors occupied or the physiological system maxed out.", "correct": true, "why": "That is emax (maximal response, ceiling)."}, {"t": "Concentration (or dose) producing 50% of the maximal response; smaller means more potent.", "correct": false, "why": "That is ec50 / ed50, not emax (maximal response, ceiling)."}, {"t": "The dose right before something happens; below it, no effect at all.", "correct": false, "why": "That is threshold, not emax (maximal response, ceiling)."}, {"t": "Lethal dose for 50% over effective dose for 50%; larger is safer.", "correct": false, "why": "That is therapeutic index (ti), not emax (maximal response, ceiling)."}], "teach": "The plateau: all receptors occupied or the physiological system maxed out. Giving more drug past the ceiling does no more good. Curves with equal Emax differ by affinity; when EC50 is equal, greater efficacy makes the drug more potent (Relative Efficacy slide).", "fg": "drc-basic", "dupOf": "T-emax-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-emax", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~11–~14, ~20–~21, ~27; transcript 9/24", "quote": "What are the two reasons why we have reached the Emacs and we can’t keep going up? All the receptors are occupied or I max out the physiological system, right?", "id": "T-emax-3", "stem": "Which term is defined as: The plateau: all receptors occupied or the physiological system maxed out?", "options": [{"t": "Emax", "correct": true, "why": "This is the definition of Emax (maximal response, ceiling)."}, {"t": "EC50 / ED50", "correct": false, "why": "EC50 / ED50: Concentration (or dose) producing 50% of the maximal response; smaller means more potent."}, {"t": "Threshold", "correct": false, "why": "Threshold: The dose right before something happens; below it, no effect at all."}, {"t": "Therapeutic index", "correct": false, "why": "Therapeutic index (TI): Lethal dose for 50% over effective dose for 50%; larger is safer."}], "teach": "Giving more drug past the ceiling does no more good. Curves with equal Emax differ by affinity; when EC50 is equal, greater efficacy makes the drug more potent (Relative Efficacy slide).", "fg": "drc-basic", "dupOf": "T-emax-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-slope", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~20–~21; transcript 9/24", "quote": "In that slope in that area of the curve, this is when I’m going to get the most bang for my buck. This is I’m going to get the greatest change in the response with the smallest change in the dose.", "id": "T-slope-1", "stem": "Which term fits this situation? Two drugs: one goes from no effect to its top within a narrow range of doses, the other needs a much wider range of doses before it tops out and gives more room before toxicity.", "options": [{"t": "Slope", "correct": true, "why": "This situation is slope: The linear mid-section; greatest change in effect from the smallest change in dose."}, {"t": "Threshold", "correct": false, "why": "Threshold would be: The dose right before something happens; below it, no effect at all."}, {"t": "Potency", "correct": false, "why": "Potency (pharmacological) would be: How much drug is needed; a combination of affinity, efficacy and the tissue."}, {"t": "Graded response", "correct": false, "why": "Graded response would be: Measured in one biological unit on a continuous scale, rising by degrees with dose."}], "teach": "The linear mid-section; greatest change in effect from the smallest change in dose. Which is better “depends”: the steep curve goes from no effect to max all at once; the shallow one gives a greater range of doses before a toxic effect."},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-slope", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~20–~21; transcript 9/24", "quote": "In that slope in that area of the curve, this is when I’m going to get the most bang for my buck. This is I’m going to get the greatest change in the response with the smallest change in the dose.", "id": "T-slope-2", "stem": "Slope means:", "options": [{"t": "The linear mid-section; greatest change in effect from the smallest change in dose.", "correct": true, "why": "That is slope."}, {"t": "The range of steady-state concentrations giving efficacy with minimal toxicity; not a ratio.", "correct": false, "why": "That is therapeutic window, not slope."}, {"t": "The dose right before something happens; below it, no effect at all.", "correct": false, "why": "That is threshold, not slope."}, {"t": "How much drug is needed; a combination of affinity, efficacy and the tissue.", "correct": false, "why": "That is potency (pharmacological), not slope."}], "teach": "The linear mid-section; greatest change in effect from the smallest change in dose. Which is better “depends”: the steep curve goes from no effect to max all at once; the shallow one gives a greater range of doses before a toxic effect.", "dupOf": "T-slope-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-slope", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~20–~21; transcript 9/24", "quote": "In that slope in that area of the curve, this is when I’m going to get the most bang for my buck. This is I’m going to get the greatest change in the response with the smallest change in the dose.", "id": "T-slope-3", "stem": "Which term is defined as: The linear mid-section; greatest change in effect from the smallest change in dose?", "options": [{"t": "Slope", "correct": true, "why": "This is the definition of Slope."}, {"t": "Threshold", "correct": false, "why": "Threshold: The dose right before something happens; below it, no effect at all."}, {"t": "Potency", "correct": false, "why": "Potency (pharmacological): How much drug is needed; a combination of affinity, efficacy and the tissue."}, {"t": "Graded response", "correct": false, "why": "Graded response: Measured in one biological unit on a continuous scale, rising by degrees with dose."}], "teach": "Which is better “depends”: the steep curve goes from no effect to max all at once; the shallow one gives a greater range of doses before a toxic effect.", "dupOf": "T-slope-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-ec50", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~57–~58; Pharmacodynamics-Day_3_2026s.pdf slides ~20–~22, ~29; transcript 9/24", "quote": "So, the take-home message that you can’t forget is that the smallest the ED50 is or the [EC]50, the greater the potency is gonna be. They’re inverse proportional.", "id": "T-ec50-1", "stem": "Which term fits this situation? From the heart-rate curve the point halfway between no effect and the top is dropped to the x-axis, and the concentration read there is the one used to compare drugs; in the whole animal it is a dose instead.", "options": [{"t": "EC50 / ED50", "correct": true, "why": "This situation is ec50 / ed50: Concentration (or dose) producing 50% of the maximal response; smaller means more potent."}, {"t": "Therapeutic index", "correct": false, "why": "Therapeutic index (TI) would be: Lethal dose for 50% over effective dose for 50%; larger is safer."}, {"t": "Kd", "correct": false, "why": "Kd (dissociation constant) would be: The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect."}, {"t": "Emax", "correct": false, "why": "Emax (maximal response, ceiling) would be: The plateau: all receptors occupied or the physiological system maxed out."}], "teach": "Concentration (or dose) producing 50% of the maximal response; smaller means more potent. Kd is the concentration binding 50% of receptors (affinity, no effect); EC50 is 50% of the response (potency). Both are read on the x-axis. “Philosophically identical”: one is a dose, the other a concentration.", "fg": "drc-basic"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-ec50", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~57–~58; Pharmacodynamics-Day_3_2026s.pdf slides ~20–~22, ~29; transcript 9/24", "quote": "So, the take-home message that you can’t forget is that the smallest the ED50 is or the [EC]50, the greater the potency is gonna be. They’re inverse proportional.", "id": "T-ec50-2", "stem": "EC50 / ED50 means:", "options": [{"t": "Concentration (or dose) producing 50% of the maximal response; smaller means more potent.", "correct": true, "why": "That is ec50 / ed50."}, {"t": "The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect.", "correct": false, "why": "That is kd (dissociation constant), not ec50 / ed50."}, {"t": "The plateau: all receptors occupied or the physiological system maxed out.", "correct": false, "why": "That is emax (maximal response, ceiling), not ec50 / ed50."}, {"t": "Lethal dose for 50% over effective dose for 50%; larger is safer.", "correct": false, "why": "That is therapeutic index (ti), not ec50 / ed50."}], "teach": "Concentration (or dose) producing 50% of the maximal response; smaller means more potent. Kd is the concentration binding 50% of receptors (affinity, no effect); EC50 is 50% of the response (potency). Both are read on the x-axis. “Philosophically identical”: one is a dose, the other a concentration.", "fg": "drc-basic", "dupOf": "T-ec50-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-ec50", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~57–~58; Pharmacodynamics-Day_3_2026s.pdf slides ~20–~22, ~29; transcript 9/24", "quote": "So, the take-home message that you can’t forget is that the smallest the ED50 is or the [EC]50, the greater the potency is gonna be. They’re inverse proportional.", "id": "T-ec50-3", "stem": "Which term is defined as: The effective concentration (in vitro) or effective dose (in vivo) that produces 50% of a drug’s maximal response: the indicator of potency. The smaller it is, the greater the potency (inversely proportional)?", "options": [{"t": "EC50 / ED50", "correct": true, "why": "This is the definition of EC50 / ED50."}, {"t": "Therapeutic index", "correct": false, "why": "Therapeutic index (TI): Lethal dose for 50% over effective dose for 50%; larger is safer."}, {"t": "Kd", "correct": false, "why": "Kd (dissociation constant): The concentration binding 50% of receptors; smaller means greater affinity, says nothing of effect."}, {"t": "Emax", "correct": false, "why": "Emax (maximal response, ceiling): The plateau: all receptors occupied or the physiological system maxed out."}], "teach": "Kd is the concentration binding 50% of receptors (affinity, no effect); EC50 is 50% of the response (potency). Both are read on the x-axis. “Philosophically identical”: one is a dose, the other a concentration.", "fg": "drc-basic", "dupOf": "T-ec50-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-potency", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~7, ~22, ~27–~29; Pharmacodynamics-Day_2_2026s copy.pdf slides ~52–~54; Pharmacodynamics-Day-1-2026s.pdf slides ~21–~22, ~27; transcript 9/22; transcript 9/23; transcript 9/24", "quote": "The take home message over here is that potency is not only going to be defined by the efficacy of the affinity, but also the tissue that is going to be bound to.", "id": "T-potency-1", "stem": "Which term fits this situation? Of five curves on one plot, drug A sits furthest left, needing the smallest dose for an equivalent effect, even though drug B reaches a higher top; put the same drug A in a tissue with more receptors and it needs even less.", "options": [{"t": "Potency", "correct": true, "why": "This situation is potency (pharmacological): How much drug is needed; a combination of affinity, efficacy and the tissue."}, {"t": "Apparent potency", "correct": false, "why": "Apparent potency would be: In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age."}, {"t": "Threshold", "correct": false, "why": "Threshold would be: The dose right before something happens; below it, no effect at all."}, {"t": "Therapeutic index", "correct": false, "why": "Therapeutic index (TI) would be: Lethal dose for 50% over effective dose for 50%; larger is safer."}], "teach": "How much drug is needed; a combination of affinity, efficacy and the tissue. Potency ≠ efficacy: the most potent drug (smallest EC50) can be a partial agonist; the most efficacious has the highest Emax. “Affinity is gonna be on the bottom, efficacy is gonna be on the Y axis, and potency is gonna be a combination of the two.”", "fg": "potency"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-potency", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~7, ~22, ~27–~29; Pharmacodynamics-Day_2_2026s copy.pdf slides ~52–~54; Pharmacodynamics-Day-1-2026s.pdf slides ~21–~22, ~27; transcript 9/22; transcript 9/23; transcript 9/24", "quote": "The take home message over here is that potency is not only going to be defined by the efficacy of the affinity, but also the tissue that is going to be bound to.", "id": "T-potency-2", "stem": "Potency means:", "options": [{"t": "How much drug is needed; a combination of affinity, efficacy and the tissue.", "correct": true, "why": "That is potency (pharmacological)."}, {"t": "In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age.", "correct": false, "why": "That is apparent potency, not potency (pharmacological)."}, {"t": "The dose right before something happens; below it, no effect at all.", "correct": false, "why": "That is threshold, not potency (pharmacological)."}, {"t": "Lethal dose for 50% over effective dose for 50%; larger is safer.", "correct": false, "why": "That is therapeutic index (ti), not potency (pharmacological)."}], "teach": "How much drug is needed; a combination of affinity, efficacy and the tissue. Potency ≠ efficacy: the most potent drug (smallest EC50) can be a partial agonist; the most efficacious has the highest Emax. “Affinity is gonna be on the bottom, efficacy is gonna be on the Y axis, and potency is gonna be a combination of the two.”", "fg": "potency", "dupOf": "T-potency-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-potency", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~7, ~22, ~27–~29; Pharmacodynamics-Day_2_2026s copy.pdf slides ~52–~54; Pharmacodynamics-Day-1-2026s.pdf slides ~21–~22, ~27; transcript 9/22; transcript 9/23; transcript 9/24", "quote": "The take home message over here is that potency is not only going to be defined by the efficacy of the affinity, but also the tissue that is going to be bound to.", "id": "T-potency-3", "stem": "Which term is defined as: How much drug is needed for a given response, measured by the EC50 or ED50 and read on the x-axis (further left = more potent). It is a combination of affinity, efficacy and the tissue (number of receptors)?", "options": [{"t": "Potency", "correct": true, "why": "This is the definition of Potency (pharmacological)."}, {"t": "Apparent potency", "correct": false, "why": "Apparent potency: In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age."}, {"t": "Threshold", "correct": false, "why": "Threshold: The dose right before something happens; below it, no effect at all."}, {"t": "Therapeutic index", "correct": false, "why": "Therapeutic index (TI): Lethal dose for 50% over effective dose for 50%; larger is safer."}], "teach": "Potency ≠ efficacy: the most potent drug (smallest EC50) can be a partial agonist; the most efficacious has the highest Emax. “Affinity is gonna be on the bottom, efficacy is gonna be on the Y axis, and potency is gonna be a combination of the two.”", "fg": "potency", "dupOf": "T-potency-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-apparent-potency", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~23, ~27; Pharmacodynamics-Day_3_2026s.pdf slide ~8; transcript 9/22", "quote": "So this is going to give us our apparent potency. Why is apparent? ... It’s only appearing because it’s not the total concentration of the drug.", "id": "T-apparent-potency-1", "stem": "Which term fits this situation? The same drug given by mouth and by vein: by vein 100% reaches the blood, by mouth the liver removes part on the first pass, so the oral dose seems weaker though the drug’s affinity and efficacy are identical.", "options": [{"t": "Apparent potency", "correct": true, "why": "This situation is apparent potency: In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age."}, {"t": "Therapeutic window", "correct": false, "why": "Therapeutic window would be: The range of steady-state concentrations giving efficacy with minimal toxicity; not a ratio."}, {"t": "Safety index", "correct": false, "why": "Safety index (safety ratio) would be: Dose killing 1% divided by dose treating 99%; the tails, not the middles."}, {"t": "Baseline", "correct": false, "why": "Baseline (point of reference) would be: Where the curve starts: receptor activity before any drug; 0% if most inactive."}], "teach": "In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age. Route of administration and first-pass metabolism change apparent potency (IV has 100% bioavailability); they do not change the drug’s affinity or efficacy, which set pharmacological potency."},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-apparent-potency", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~23, ~27; Pharmacodynamics-Day_3_2026s.pdf slide ~8; transcript 9/22", "quote": "So this is going to give us our apparent potency. Why is apparent? ... It’s only appearing because it’s not the total concentration of the drug.", "id": "T-apparent-potency-2", "stem": "Apparent potency means:", "options": [{"t": "In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age.", "correct": true, "why": "That is apparent potency."}, {"t": "The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C.", "correct": false, "why": "That is effector (signal amplifier), not apparent potency."}, {"t": "Dose killing 1% divided by dose treating 99%; the tails, not the middles.", "correct": false, "why": "That is safety index (safety ratio), not apparent potency."}, {"t": "Where the curve starts: receptor activity before any drug; 0% if most inactive.", "correct": false, "why": "That is baseline (point of reference), not apparent potency."}], "teach": "In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age. Route of administration and first-pass metabolism change apparent potency (IV has 100% bioavailability); they do not change the drug’s affinity or efficacy, which set pharmacological potency.", "dupOf": "T-apparent-potency-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-relative-potency", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slide ~23; transcript 9/24", "quote": "We can say that a drug A is 1000 times more potent than drug B because it requires 1000 times less drug to produce equivalent responses.", "id": "T-relative-potency-1", "stem": "Which term fits this situation? Drug A needs 1000 times less than drug B to produce an equivalent effect, so dividing B’s half-maximal dose by A’s gives 1000, and the comparison is made at 50%, never at 100%.", "options": [{"t": "Relative potency", "correct": true, "why": "This situation is relative potency: The ratio of two drugs’ ED50 values, compared at equivalent effects."}, {"t": "Symmetrical vs asymmetrical shifts", "correct": false, "why": "Symmetrical vs asymmetrical shifts would be: Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric."}, {"t": "Potency", "correct": false, "why": "Potency (pharmacological) would be: How much drug is needed; a combination of affinity, efficacy and the tissue."}, {"t": "Slope", "correct": false, "why": "Slope would be: The linear mid-section; greatest change in effect from the smallest change in dose."}], "teach": "The ratio of two drugs’ ED50 values, compared at equivalent effects. Compare potency at equivalent effects (e.g., 50%), not at 100%, because a partial agonist never reaches 100%. “Math is gonna be minimal.”"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-relative-potency", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slide ~23; transcript 9/24", "quote": "We can say that a drug A is 1000 times more potent than drug B because it requires 1000 times less drug to produce equivalent responses.", "id": "T-relative-potency-2", "stem": "Relative potency means:", "options": [{"t": "The ratio of two drugs’ ED50 values, compared at equivalent effects.", "correct": true, "why": "That is relative potency."}, {"t": "How much drug is needed; a combination of affinity, efficacy and the tissue.", "correct": false, "why": "That is potency (pharmacological), not relative potency."}, {"t": "The linear mid-section; greatest change in effect from the smallest change in dose.", "correct": false, "why": "That is slope, not relative potency."}, {"t": "Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric.", "correct": false, "why": "That is symmetrical vs asymmetrical shifts, not relative potency."}], "teach": "The ratio of two drugs’ ED50 values, compared at equivalent effects. Compare potency at equivalent effects (e.g., 50%), not at 100%, because a partial agonist never reaches 100%. “Math is gonna be minimal.”", "dupOf": "T-relative-potency-1"},
{"lecture": "L03", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-relative-potency", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_3_2026s.pdf slide ~23; transcript 9/24", "quote": "We can say that a drug A is 1000 times more potent than drug B because it requires 1000 times less drug to produce equivalent responses.", "id": "T-relative-potency-3", "stem": "Which term is defined as: The ratio of two drugs’ ED50 (or EC50) values, ED50B / ED50A. A drug that needs 1000 times less drug to produce an equivalent response is 1000X more potent?", "options": [{"t": "Relative potency", "correct": true, "why": "This is the definition of Relative potency."}, {"t": "Symmetrical vs asymmetrical shifts", "correct": false, "why": "Symmetrical vs asymmetrical shifts: Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric."}, {"t": "Potency", "correct": false, "why": "Potency (pharmacological): How much drug is needed; a combination of affinity, efficacy and the tissue."}, {"t": "Slope", "correct": false, "why": "Slope: The linear mid-section; greatest change in effect from the smallest change in dose."}], "teach": "Compare potency at equivalent effects (e.g., 50%), not at 100%, because a partial agonist never reaches 100%. “Math is gonna be minimal.”", "dupOf": "T-relative-potency-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-signal-transduction", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~25–~28; transcript 9/23", "quote": "Signal Transduction: Signal ... Receptor ... Transducer ... Effector (Signal Amplifier) ... 2nd Messenger ... Physiological Response", "id": "T-signal-transduction-1", "stem": "Which term fits this situation? Epinephrine arrives at β1, the Gαs subunit translates the change, adenylate cyclase amplifies it into cyclic AMP, and the heart rate rises: five steps in a row from arrival to effect.", "options": [{"t": "Signal transduction", "correct": true, "why": "This situation is signal transduction: The whole sequence: signal, receptor, transducer, effector, second messenger, physiological response."}, {"t": "Constitutive activity", "correct": false, "why": "Constitutive activity would be: Receptors active on their own, no drug present; what an inverse agonist removes."}, {"t": "Nuclear receptor", "correct": false, "why": "Nuclear (intracellular) receptor would be: Inside the cell; steroid binds, and gene expression and messenger RNA production change."}, {"t": "Gαs, Gαi and Gαq", "correct": false, "why": "Gαs, Gαi and Gαq would be: Three α types: s raises cyclic AMP, i lowers it, q releases calcium."}], "teach": "The whole sequence: signal, receptor, transducer, effector, second messenger, physiological response. Exam ask: identify what is a signal, a receptor, a transducer, an effector (“factor system”) and a second messenger in a pathway like epinephrine → β1 → Gαs → AC → cAMP.", "fg": "gpcr"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-signal-transduction", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~25–~28; transcript 9/23", "quote": "Signal Transduction: Signal ... Receptor ... Transducer ... Effector (Signal Amplifier) ... 2nd Messenger ... Physiological Response", "id": "T-signal-transduction-2", "stem": "Signal transduction means:", "options": [{"t": "The whole sequence: signal, receptor, transducer, effector, second messenger, physiological response.", "correct": true, "why": "That is signal transduction."}, {"t": "A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane.", "correct": false, "why": "That is rapid desensitization (grk / β-arrestin), not signal transduction."}, {"t": "Receptors active on their own, no drug present; what an inverse agonist removes.", "correct": false, "why": "That is constitutive activity, not signal transduction."}, {"t": "Inside the cell; steroid binds, and gene expression and messenger RNA production change.", "correct": false, "why": "That is nuclear (intracellular) receptor, not signal transduction."}], "teach": "The whole sequence: signal, receptor, transducer, effector, second messenger, physiological response. Exam ask: identify what is a signal, a receptor, a transducer, an effector (“factor system”) and a second messenger in a pathway like epinephrine → β1 → Gαs → AC → cAMP.", "fg": "gpcr", "dupOf": "T-signal-transduction-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-transducer", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~26–~28; transcript 9/23", "quote": "Our G protein, for example, can understand that change in the receptor. And by understanding and translating that change, it’s going to be called the transducer.", "id": "T-transducer-1", "stem": "Which term fits this situation? Norepinephrine changes the shape of β1, and the Gαs protein understands that change and passes it along to adenylate cyclase; it neither receives the hormone nor makes cyclic AMP.", "options": [{"t": "Transducer", "correct": true, "why": "This situation is transducer: Translates the activated receptor’s change to the effector; the G protein."}, {"t": "Second messenger", "correct": false, "why": "Second messenger would be: The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets."}, {"t": "Rapid desensitization", "correct": false, "why": "Rapid desensitization (GRK / β-arrestin) would be: A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane."}, {"t": "Gαs, Gαi and Gαq", "correct": false, "why": "Gαs, Gαi and Gαq would be: Three α types: s raises cyclic AMP, i lowers it, q releases calcium."}], "teach": "Translates the activated receptor’s change to the effector; the G protein. “Fancy name for translation.” Transducer = G protein; effector = the enzyme it activates (AC, PLC); second messenger = the small molecule the effector makes (cAMP, IP3).", "fg": "gpcr-steps"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-transducer", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~26–~28; transcript 9/23", "quote": "Our G protein, for example, can understand that change in the receptor. And by understanding and translating that change, it’s going to be called the transducer.", "id": "T-transducer-2", "stem": "Transducer means:", "options": [{"t": "Translates the activated receptor’s change to the effector; the G protein.", "correct": true, "why": "That is transducer."}, {"t": "The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets.", "correct": false, "why": "That is second messenger, not transducer."}, {"t": "A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane.", "correct": false, "why": "That is rapid desensitization (grk / β-arrestin), not transducer."}, {"t": "Three α types: s raises cyclic AMP, i lowers it, q releases calcium.", "correct": false, "why": "That is gαs, gαi and gαq, not transducer."}], "teach": "Translates the activated receptor’s change to the effector; the G protein. “Fancy name for translation.” Transducer = G protein; effector = the enzyme it activates (AC, PLC); second messenger = the small molecule the effector makes (cAMP, IP3).", "fg": "gpcr-steps", "dupOf": "T-transducer-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-transducer", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~26–~28; transcript 9/23", "quote": "Our G protein, for example, can understand that change in the receptor. And by understanding and translating that change, it’s going to be called the transducer.", "id": "T-transducer-3", "stem": "Which term is defined as: The component that translates, integrates and coordinates the signal from the activated receptor, e.g., the G protein?", "options": [{"t": "Transducer", "correct": true, "why": "This is the definition of Transducer."}, {"t": "Second messenger", "correct": false, "why": "Second messenger: The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets."}, {"t": "Rapid desensitization", "correct": false, "why": "Rapid desensitization (GRK / β-arrestin): A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane."}, {"t": "Gαs, Gαi and Gαq", "correct": false, "why": "Gαs, Gαi and Gαq: Three α types: s raises cyclic AMP, i lowers it, q releases calcium."}], "teach": "“Fancy name for translation.” Transducer = G protein; effector = the enzyme it activates (AC, PLC); second messenger = the small molecule the effector makes (cAMP, IP3).", "fg": "gpcr-steps", "dupOf": "T-transducer-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-effector", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~26–~28; transcript 9/23", "quote": "Frequently, the proximal cellular effector protein is not the ultimate physiological target but rather is an enzyme, ion channel, or transport protein that creates, moves, or degrades a small molecule or ions", "id": "T-effector-1", "stem": "Which term fits this situation? Once Gαq reaches it, phospholipase C converts PIP2 (phosphatidylinositol bisphosphate) into IP3 (inositol trisphosphate): it is the enzyme that makes the small molecule, not the small molecule itself.", "options": [{"t": "Effector", "correct": true, "why": "This situation is effector (signal amplifier): The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C."}, {"t": "Transducer", "correct": false, "why": "Transducer would be: Translates the activated receptor’s change to the effector; the G protein."}, {"t": "Long-term down-regulation", "correct": false, "why": "Long-term down-regulation (internalization) would be: Receptor taken into the cell by endocytosis, then recycled or degraded in a lysosome."}, {"t": "Receptor tyrosine kinase", "correct": false, "why": "Receptor tyrosine kinase (RTK, 1-TM) would be: Crosses the membrane once; binding outside, enzyme activity inside; insulin, growth factors."}], "teach": "The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C. Poll trap: “phospholipase C is an example of a second messenger” — no, PLC is the effector (his “factor system”); IP3 is its second messenger.", "fg": "gpcr-steps"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-effector", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~26–~28; transcript 9/23", "quote": "Frequently, the proximal cellular effector protein is not the ultimate physiological target but rather is an enzyme, ion channel, or transport protein that creates, moves, or degrades a small molecule or ions", "id": "T-effector-2", "stem": "Effector means:", "options": [{"t": "The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C.", "correct": true, "why": "That is effector (signal amplifier)."}, {"t": "More receptors made after chronic antagonist; a compensatory mechanism, agonist becomes more potent.", "correct": false, "why": "That is up-regulation, not effector (signal amplifier)."}, {"t": "Translates the activated receptor’s change to the effector; the G protein.", "correct": false, "why": "That is transducer, not effector (signal amplifier)."}, {"t": "Receptor taken into the cell by endocytosis, then recycled or degraded in a lysosome.", "correct": false, "why": "That is long-term down-regulation (internalization), not effector (signal amplifier)."}], "teach": "The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C. Poll trap: “phospholipase C is an example of a second messenger” — no, PLC is the effector (his “factor system”); IP3 is its second messenger.", "fg": "gpcr-steps", "dupOf": "T-effector-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-effector", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~26–~28; transcript 9/23", "quote": "Frequently, the proximal cellular effector protein is not the ultimate physiological target but rather is an enzyme, ion channel, or transport protein that creates, moves, or degrades a small molecule or ions", "id": "T-effector-3", "stem": "Which term is defined as: The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C?", "options": [{"t": "Effector", "correct": true, "why": "This is the definition of Effector (signal amplifier)."}, {"t": "Transducer", "correct": false, "why": "Transducer: Translates the activated receptor’s change to the effector; the G protein."}, {"t": "Long-term down-regulation", "correct": false, "why": "Long-term down-regulation (internalization): Receptor taken into the cell by endocytosis, then recycled or degraded in a lysosome."}, {"t": "Receptor tyrosine kinase", "correct": false, "why": "Receptor tyrosine kinase (RTK, 1-TM): Crosses the membrane once; binding outside, enzyme activity inside; insulin, growth factors."}], "teach": "Poll trap: “phospholipase C is an example of a second messenger” — no, PLC is the effector (his “factor system”); IP3 is its second messenger.", "fg": "gpcr-steps", "dupOf": "T-effector-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-second-messenger", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~29; Pharmacodynamics-Day-1-2026s.pdf slides ~52–~53; transcript 9/23", "quote": "The production of the second messenger, which then is going to activate another 2nd messenger and then another 2nd messenger, just like a domino cascade until I get the physiological response that I want.", "id": "T-second-messenger-1", "stem": "Which term fits this situation? Adenylate cyclase turns ATP (adenosine triphosphate) into cyclic AMP, which spreads near where it was made and activates protein kinase A, which activates the next step, until the heart beats faster.", "options": [{"t": "Second messenger", "correct": true, "why": "This situation is second messenger: The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets."}, {"t": "Rapid desensitization", "correct": false, "why": "Rapid desensitization (GRK / β-arrestin) would be: A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane."}, {"t": "Transducer", "correct": false, "why": "Transducer would be: Translates the activated receptor’s change to the effector; the G protein."}, {"t": "Constitutive activity", "correct": false, "why": "Constitutive activity would be: Receptors active on their own, no drug present; what an inverse agonist removes."}], "teach": "The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets. “If there is cAMP and PKA, then select all ... you shouldn’t be picking the receptor or the AC or the calcium channel.” For the Gq pathway the two to know are IP3 and Ca++.", "fg": "gpcr-steps"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-second-messenger", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~29; Pharmacodynamics-Day-1-2026s.pdf slides ~52–~53; transcript 9/23", "quote": "The production of the second messenger, which then is going to activate another 2nd messenger and then another 2nd messenger, just like a domino cascade until I get the physiological response that I want.", "id": "T-second-messenger-2", "stem": "Second messenger means:", "options": [{"t": "The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets.", "correct": true, "why": "That is second messenger."}, {"t": "A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane.", "correct": false, "why": "That is rapid desensitization (grk / β-arrestin), not second messenger."}, {"t": "Translates the activated receptor’s change to the effector; the G protein.", "correct": false, "why": "That is transducer, not second messenger."}, {"t": "Receptors active on their own, no drug present; what an inverse agonist removes.", "correct": false, "why": "That is constitutive activity, not second messenger."}], "teach": "The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets. “If there is cAMP and PKA, then select all ... you shouldn’t be picking the receptor or the AC or the calcium channel.” For the Gq pathway the two to know are IP3 and Ca++.", "fg": "gpcr-steps", "dupOf": "T-second-messenger-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-second-messenger", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~29; Pharmacodynamics-Day-1-2026s.pdf slides ~52–~53; transcript 9/23", "quote": "The production of the second messenger, which then is going to activate another 2nd messenger and then another 2nd messenger, just like a domino cascade until I get the physiological response that I want.", "id": "T-second-messenger-3", "stem": "Which term is defined as: Small molecules created, degraded or moved by an enzyme, ion channel or transport protein (the effector); they diffuse near their site of synthesis and convey information to a variety of targets. Slide examples: cAMP, PKA, PKC, IP3, Ca++?", "options": [{"t": "Second messenger", "correct": true, "why": "This is the definition of Second messenger."}, {"t": "Rapid desensitization", "correct": false, "why": "Rapid desensitization (GRK / β-arrestin): A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane."}, {"t": "Transducer", "correct": false, "why": "Transducer: Translates the activated receptor’s change to the effector; the G protein."}, {"t": "Constitutive activity", "correct": false, "why": "Constitutive activity: Receptors active on their own, no drug present; what an inverse agonist removes."}], "teach": "“If there is cAMP and PKA, then select all ... you shouldn’t be picking the receptor or the AC or the calcium channel.” For the Gq pathway the two to know are IP3 and Ca++.", "fg": "gpcr-steps", "dupOf": "T-second-messenger-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-g-protein", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~49–~55; Pharmacodynamics-Day_2_2026s copy.pdf slide ~3; transcript 9/23", "quote": "The GDP, the diphosphate, has to come off, and the G[T]P, as in taxes, the triphosphate has to come in. The removal of the GDP and replacement with the G[T]P is what triggers them to separate from each other.", "id": "T-g-protein-1", "stem": "Which term fits this situation? Norepinephrine binds β1 in the heart; the α subunit lets its diphosphate off, takes a triphosphate on, breaks away from β and γ and switches on adenylate cyclase. Then the extra phosphate is removed and α rejoins β and γ.", "options": [{"t": "G protein", "correct": true, "why": "This situation is g protein (heterotrimeric): Three subunits; diphosphate off, triphosphate on, α leaves β and γ, activates the effector."}, {"t": "Gαs, Gαi and Gαq", "correct": false, "why": "Gαs, Gαi and Gαq would be: Three α types: s raises cyclic AMP, i lowers it, q releases calcium."}, {"t": "Cross-talk", "correct": false, "why": "Cross-talk would be: Two receptors in one cell share an effector; the response is their net."}, {"t": "Second messenger", "correct": false, "why": "Second messenger would be: The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets."}], "teach": "Three subunits; diphosphate off, triphosphate on, α leaves β and γ, activates the effector. The G protein is the transducer. Poll trap: G proteins are defined by the α subunit, not the β subunit.", "fg": "gpcr-steps"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-g-protein", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~49–~55; Pharmacodynamics-Day_2_2026s copy.pdf slide ~3; transcript 9/23", "quote": "The GDP, the diphosphate, has to come off, and the G[T]P, as in taxes, the triphosphate has to come in. The removal of the GDP and replacement with the G[T]P is what triggers them to separate from each other.", "id": "T-g-protein-2", "stem": "G protein means:", "options": [{"t": "Three subunits; diphosphate off, triphosphate on, α leaves β and γ, activates the effector.", "correct": true, "why": "That is g protein (heterotrimeric)."}, {"t": "A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane.", "correct": false, "why": "That is rapid desensitization (grk / β-arrestin), not g protein (heterotrimeric)."}, {"t": "Three α types: s raises cyclic AMP, i lowers it, q releases calcium.", "correct": false, "why": "That is gαs, gαi and gαq, not g protein (heterotrimeric)."}, {"t": "Two receptors in one cell share an effector; the response is their net.", "correct": false, "why": "That is cross-talk, not g protein (heterotrimeric)."}], "teach": "Three subunits; diphosphate off, triphosphate on, α leaves β and γ, activates the effector. The G protein is the transducer. Poll trap: G proteins are defined by the α subunit, not the β subunit.", "fg": "gpcr-steps", "dupOf": "T-g-protein-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-g-protein", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~49–~55; Pharmacodynamics-Day_2_2026s copy.pdf slide ~3; transcript 9/23", "quote": "The GDP, the diphosphate, has to come off, and the G[T]P, as in taxes, the triphosphate has to come in. The removal of the GDP and replacement with the G[T]P is what triggers them to separate from each other.", "id": "T-g-protein-3", "stem": "Which term is defined as: Three subunits; diphosphate off, triphosphate on, α leaves β and γ, activates the effector?", "options": [{"t": "G protein", "correct": true, "why": "This is the definition of G protein (heterotrimeric)."}, {"t": "Gαs, Gαi and Gαq", "correct": false, "why": "Gαs, Gαi and Gαq: Three α types: s raises cyclic AMP, i lowers it, q releases calcium."}, {"t": "Cross-talk", "correct": false, "why": "Cross-talk: Two receptors in one cell share an effector; the response is their net."}, {"t": "Second messenger", "correct": false, "why": "Second messenger: The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets."}], "teach": "The G protein is the transducer. Poll trap: G proteins are defined by the α subunit, not the β subunit.", "fg": "gpcr-steps", "dupOf": "T-g-protein-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-g-alpha", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~3, ~30; Pharmacodynamics-Day-1-2026s.pdf slides ~50–~55; transcript 9/23", "quote": "We know that the alpha S always is going to be associated with the AC and always is going to increase the camp. The alphai, which is the opposite, also is going to be associated with the AC, but in this case it’s going to suppress the camp. And then the alpha Q is going to increase IP3 and calcium.", "id": "T-g-alpha-1", "stem": "Which term fits this situation? At β1 in the heart the α subunit turns adenylate cyclase on and cyclic AMP rises; at M2 a different α subunit turns the same enzyme down; at α1 in smooth muscle a third α subunit turns on phospholipase C and calcium is released.", "options": [{"t": "Gαs, Gαi and Gαq", "correct": true, "why": "This situation is gαs, gαi and gαq: Three α types: s raises cyclic AMP, i lowers it, q releases calcium."}, {"t": "Receptor tyrosine kinase", "correct": false, "why": "Receptor tyrosine kinase (RTK, 1-TM) would be: Crosses the membrane once; binding outside, enzyme activity inside; insulin, growth factors."}, {"t": "G protein", "correct": false, "why": "G protein (heterotrimeric) would be: Three subunits; diphosphate off, triphosphate on, α leaves β and γ, activates the effector."}, {"t": "Effector", "correct": false, "why": "Effector (signal amplifier) would be: The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C."}], "teach": "Three α types: s raises cyclic AMP, i lowers it, q releases calcium. His cue: adenylate cyclase goes with cyclic AMP; αq goes with phospholipase C and IP3. Gαi is the trap: same effector as Gαs, opposite direction.", "fg": "gpcr"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-g-alpha", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~3, ~30; Pharmacodynamics-Day-1-2026s.pdf slides ~50–~55; transcript 9/23", "quote": "We know that the alpha S always is going to be associated with the AC and always is going to increase the camp. The alphai, which is the opposite, also is going to be associated with the AC, but in this case it’s going to suppress the camp. And then the alpha Q is going to increase IP3 and calcium.", "id": "T-g-alpha-2", "stem": "Gαs, Gαi and Gαq means:", "options": [{"t": "Three α types: s raises cyclic AMP, i lowers it, q releases calcium.", "correct": true, "why": "That is gαs, gαi and gαq."}, {"t": "Three subunits; diphosphate off, triphosphate on, α leaves β and γ, activates the effector.", "correct": false, "why": "That is g protein (heterotrimeric), not gαs, gαi and gαq."}, {"t": "The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C.", "correct": false, "why": "That is effector (signal amplifier), not gαs, gαi and gαq."}, {"t": "Two receptors in one cell share an effector; the response is their net.", "correct": false, "why": "That is cross-talk, not gαs, gαi and gαq."}], "teach": "Three α types: s raises cyclic AMP, i lowers it, q releases calcium. His cue: adenylate cyclase goes with cyclic AMP; αq goes with phospholipase C and IP3. Gαi is the trap: same effector as Gαs, opposite direction.", "fg": "gpcr", "dupOf": "T-g-alpha-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-g-alpha", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~3, ~30; Pharmacodynamics-Day-1-2026s.pdf slides ~50–~55; transcript 9/23", "quote": "We know that the alpha S always is going to be associated with the AC and always is going to increase the camp. The alphai, which is the opposite, also is going to be associated with the AC, but in this case it’s going to suppress the camp. And then the alpha Q is going to increase IP3 and calcium.", "id": "T-g-alpha-3", "stem": "Which term is defined as: The three α subunit types to know: one (stimulation) activates adenylate cyclase and increases cAMP (β1 in the heart, ↑HR); one (inhibition) inhibits adenylate cyclase and decreases cAMP (M2 in the heart, ↓HR; α2 in the CNS); one activates phospholipase C, which converts PIP2 to IP3 and releases Ca++ from the ER (α1 in smooth muscle)?", "options": [{"t": "Gαs, Gαi and Gαq", "correct": true, "why": "This is the definition of Gαs, Gαi and Gαq."}, {"t": "Receptor tyrosine kinase", "correct": false, "why": "Receptor tyrosine kinase (RTK, 1-TM): Crosses the membrane once; binding outside, enzyme activity inside; insulin, growth factors."}, {"t": "G protein", "correct": false, "why": "G protein (heterotrimeric): Three subunits; diphosphate off, triphosphate on, α leaves β and γ, activates the effector."}, {"t": "Effector", "correct": false, "why": "Effector (signal amplifier): The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C."}], "teach": "His cue: adenylate cyclase goes with cyclic AMP; αq goes with phospholipase C and IP3. Gαi is the trap: same effector as Gαs, opposite direction.", "fg": "gpcr", "dupOf": "T-g-alpha-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-gpcr", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~35–~36, ~49; transcript 9/22", "quote": "About 60 or more% of all drugs in the market target one of kind of these receptors. So if you know how they work, you’ve got 60% of the drugs in your pocket.", "id": "T-gpcr-1", "stem": "Which term fits this situation? A protein that crosses the membrane seven times; epinephrine binds on the outside and an α subunit inside passes the activation on to adenylate cyclase. More than 60% of medicines on the market act on this class.", "options": [{"t": "G protein–coupled receptor", "correct": true, "why": "This situation is g protein–coupled receptor (gpcr, 7-tm): Crosses the membrane seven times, coupled to a G protein; 60% of drugs."}, {"t": "Down-regulation / desensitization", "correct": false, "why": "Down-regulation / desensitization would be: Fewer receptors after too much agonist; analogous to an irreversible antagonist."}, {"t": "Ion channel", "correct": false, "why": "Ion channel (ligand-gated) would be: A membrane pore usually closed; the binding pocket is in the channel itself."}, {"t": "Second messenger", "correct": false, "why": "Second messenger would be: The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets."}], "teach": "Crosses the membrane seven times, coupled to a G protein; 60% of drugs. Four receptor classes: ion channels (L-type Ca++, GABA), 7-TM GPCRs, 1-TM (tyrosine kinases), intracellular/nuclear (steroid hormones). “If you know how they work, you’ve got 60% of the drugs in your pocket.”", "fg": "gpcr-steps"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-gpcr", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~35–~36, ~49; transcript 9/22", "quote": "About 60 or more% of all drugs in the market target one of kind of these receptors. So if you know how they work, you’ve got 60% of the drugs in your pocket.", "id": "T-gpcr-2", "stem": "G protein–coupled receptor means:", "options": [{"t": "Crosses the membrane seven times, coupled to a G protein; 60% of drugs.", "correct": true, "why": "That is g protein–coupled receptor (gpcr, 7-tm)."}, {"t": "A membrane pore usually closed; the binding pocket is in the channel itself.", "correct": false, "why": "That is ion channel (ligand-gated), not g protein–coupled receptor (gpcr, 7-tm)."}, {"t": "The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets.", "correct": false, "why": "That is second messenger, not g protein–coupled receptor (gpcr, 7-tm)."}, {"t": "The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C.", "correct": false, "why": "That is effector (signal amplifier), not g protein–coupled receptor (gpcr, 7-tm)."}], "teach": "Crosses the membrane seven times, coupled to a G protein; 60% of drugs. Four receptor classes: ion channels (L-type Ca++, GABA), 7-TM GPCRs, 1-TM (tyrosine kinases), intracellular/nuclear (steroid hormones). “If you know how they work, you’ve got 60% of the drugs in your pocket.”", "fg": "gpcr-steps", "dupOf": "T-gpcr-1"},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-ion-channel", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~35–~36, ~39–~48; transcript 9/23", "quote": "You have a drug, a neurotransmitter, a hormone that is binding to a specific receptor. Once it’s bound, you can open it and allow things to move through it.", "id": "T-ion-channel-1", "stem": "Which term fits this situation? Acetylcholine binds two α subunits of the nicotinic protein; the pore opens, sodium flows in, and the membrane becomes less negative.", "options": [{"t": "Ion channel", "correct": true, "why": "This situation is ion channel (ligand-gated): A membrane pore usually closed; the binding pocket is in the channel itself."}, {"t": "Spare receptors", "correct": false, "why": "Spare receptors would be: Agonists need only a fraction of receptors for maximal effect; the rest are extra."}, {"t": "Down-regulation / desensitization", "correct": false, "why": "Down-regulation / desensitization would be: Fewer receptors after too much agonist; analogous to an irreversible antagonist."}, {"t": "Transducer", "correct": false, "why": "Transducer would be: Translates the activated receptor’s change to the effector; the G protein."}], "teach": "A membrane pore usually closed; the binding pocket is in the channel itself. Passive: always open (resting potential, funny channel). Voltage-gated: open only at certain membrane potentials (Ca++ channels open as the membrane becomes more positive). Stretch: pressure sensitive (baroreceptors). Pumps: move ions against the gradient (Na+/K+ ATPase)."},
{"lecture": "L01", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-ion-channel", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day-1-2026s.pdf slides ~35–~36, ~39–~48; transcript 9/23", "quote": "You have a drug, a neurotransmitter, a hormone that is binding to a specific receptor. Once it’s bound, you can open it and allow things to move through it.", "id": "T-ion-channel-2", "stem": "Ion channel means:", "options": [{"t": "A membrane pore usually closed; the binding pocket is in the channel itself.", "correct": true, "why": "That is ion channel (ligand-gated)."}, {"t": "Agonists need only a fraction of receptors for maximal effect; the rest are extra.", "correct": false, "why": "That is spare receptors, not ion channel (ligand-gated)."}, {"t": "Fewer receptors after too much agonist; analogous to an irreversible antagonist.", "correct": false, "why": "That is down-regulation / desensitization, not ion channel (ligand-gated)."}, {"t": "Translates the activated receptor’s change to the effector; the G protein.", "correct": false, "why": "That is transducer, not ion channel (ligand-gated)."}], "teach": "A membrane pore usually closed; the binding pocket is in the channel itself. Passive: always open (resting potential, funny channel). Voltage-gated: open only at certain membrane potentials (Ca++ channels open as the membrane becomes more positive). Stretch: pressure sensitive (baroreceptors). Pumps: move ions against the gradient (Na+/K+ ATPase).", "dupOf": "T-ion-channel-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-rtk", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~4–~11; Pharmacodynamics-Day-1-2026s.pdf slides ~35–~36; transcript 9/23", "quote": "They have this binding pocket on the outside, and they have this enzymatic activity inside of the cell. Typically those are transcription factors like insulin growth factors.", "id": "T-rtk-1", "stem": "Which term fits this situation? Insulin binds the outer part of a protein that crosses the membrane once; two of them pair up, phosphorylate each other inside the cell, and the cascade runs through RAS, RAF, MEK and ERK to gene transcription.", "options": [{"t": "Receptor tyrosine kinase", "correct": true, "why": "This situation is receptor tyrosine kinase (rtk, 1-tm): Crosses the membrane once; binding outside, enzyme activity inside; insulin, growth factors."}, {"t": "G protein–coupled receptor", "correct": false, "why": "G protein–coupled receptor (GPCR, 7-TM) would be: Crosses the membrane seven times, coupled to a G protein; 60% of drugs."}, {"t": "Nuclear receptor", "correct": false, "why": "Nuclear (intracellular) receptor would be: Inside the cell; steroid binds, and gene expression and messenger RNA production change."}, {"t": "Ion channel", "correct": false, "why": "Ion channel (ligand-gated) would be: A membrane pore usually closed; the binding pocket is in the channel itself."}], "teach": "Crosses the membrane once; binding outside, enzyme activity inside; insulin, growth factors. Downstream: Grb2 → GEF → RAS → RAF → MEK → ERK → gene transcription; 20–25% of cancers contain a RAS mutation, so a RAS blocker is an indirect antagonist that stops cell growth."},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-rtk", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~4–~11; Pharmacodynamics-Day-1-2026s.pdf slides ~35–~36; transcript 9/23", "quote": "They have this binding pocket on the outside, and they have this enzymatic activity inside of the cell. Typically those are transcription factors like insulin growth factors.", "id": "T-rtk-2", "stem": "Receptor tyrosine kinase means:", "options": [{"t": "Crosses the membrane once; binding outside, enzyme activity inside; insulin, growth factors.", "correct": true, "why": "That is receptor tyrosine kinase (rtk, 1-tm)."}, {"t": "A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane.", "correct": false, "why": "That is rapid desensitization (grk / β-arrestin), not receptor tyrosine kinase (rtk, 1-tm)."}, {"t": "Crosses the membrane seven times, coupled to a G protein; 60% of drugs.", "correct": false, "why": "That is g protein–coupled receptor (gpcr, 7-tm), not receptor tyrosine kinase (rtk, 1-tm)."}, {"t": "Inside the cell; steroid binds, and gene expression and messenger RNA production change.", "correct": false, "why": "That is nuclear (intracellular) receptor, not receptor tyrosine kinase (rtk, 1-tm)."}], "teach": "Crosses the membrane once; binding outside, enzyme activity inside; insulin, growth factors. Downstream: Grb2 → GEF → RAS → RAF → MEK → ERK → gene transcription; 20–25% of cancers contain a RAS mutation, so a RAS blocker is an indirect antagonist that stops cell growth.", "dupOf": "T-rtk-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-rtk", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~4–~11; Pharmacodynamics-Day-1-2026s.pdf slides ~35–~36; transcript 9/23", "quote": "They have this binding pocket on the outside, and they have this enzymatic activity inside of the cell. Typically those are transcription factors like insulin growth factors.", "id": "T-rtk-3", "stem": "Which term is defined as: Crosses the membrane once; binding outside, enzyme activity inside; insulin, growth factors?", "options": [{"t": "Receptor tyrosine kinase", "correct": true, "why": "This is the definition of Receptor tyrosine kinase (RTK, 1-TM)."}, {"t": "G protein–coupled receptor", "correct": false, "why": "G protein–coupled receptor (GPCR, 7-TM): Crosses the membrane seven times, coupled to a G protein; 60% of drugs."}, {"t": "Nuclear receptor", "correct": false, "why": "Nuclear (intracellular) receptor: Inside the cell; steroid binds, and gene expression and messenger RNA production change."}, {"t": "Ion channel", "correct": false, "why": "Ion channel (ligand-gated): A membrane pore usually closed; the binding pocket is in the channel itself."}], "teach": "Downstream: Grb2 → GEF → RAS → RAF → MEK → ERK → gene transcription; 20–25% of cancers contain a RAS mutation, so a RAS blocker is an indirect antagonist that stops cell growth.", "dupOf": "T-rtk-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-nuclear-receptor", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~12–~14; Pharmacodynamics-Day-1-2026s.pdf slides ~35–~36; transcript 9/23", "quote": "Those are glucocor[tico]steroids. They are nuclear receptors. They affect DNA. They affect messenger RNA production.", "id": "T-nuclear-receptor-1", "stem": "Which term fits this situation? Aldosterone enters the principal cell and binds a protein in the cytosol or nucleus; the genes are read differently and more messenger RNA for pumps and channels is made, so sodium is saved and potassium wasted.", "options": [{"t": "Nuclear receptor", "correct": true, "why": "This situation is nuclear (intracellular) receptor: Inside the cell; steroid binds, and gene expression and messenger RNA production change."}, {"t": "Down-regulation / desensitization", "correct": false, "why": "Down-regulation / desensitization would be: Fewer receptors after too much agonist; analogous to an irreversible antagonist."}, {"t": "Spare receptors", "correct": false, "why": "Spare receptors would be: Agonists need only a fraction of receptors for maximal effect; the rest are extra."}, {"t": "Up-regulation", "correct": false, "why": "Up-regulation would be: More receptors made after chronic antagonist; a compensatory mechanism, agonist becomes more potent."}], "teach": "Inside the cell; steroid binds, and gene expression and messenger RNA production change. Aldosterone at the mineralocorticoid receptor codes mRNA for more pumps and channels in the principal cell: sodium saving, potassium wasting. Exam ask: “what is the function of a nuclear receptor? How do they work”."},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-nuclear-receptor", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~12–~14; Pharmacodynamics-Day-1-2026s.pdf slides ~35–~36; transcript 9/23", "quote": "Those are glucocor[tico]steroids. They are nuclear receptors. They affect DNA. They affect messenger RNA production.", "id": "T-nuclear-receptor-2", "stem": "Nuclear receptor means:", "options": [{"t": "Inside the cell; steroid binds, and gene expression and messenger RNA production change.", "correct": true, "why": "That is nuclear (intracellular) receptor."}, {"t": "More receptors made after chronic antagonist; a compensatory mechanism, agonist becomes more potent.", "correct": false, "why": "That is up-regulation, not nuclear (intracellular) receptor."}, {"t": "Agonists need only a fraction of receptors for maximal effect; the rest are extra.", "correct": false, "why": "That is spare receptors, not nuclear (intracellular) receptor."}, {"t": "Fewer receptors after too much agonist; analogous to an irreversible antagonist.", "correct": false, "why": "That is down-regulation / desensitization, not nuclear (intracellular) receptor."}], "teach": "Inside the cell; steroid binds, and gene expression and messenger RNA production change. Aldosterone at the mineralocorticoid receptor codes mRNA for more pumps and channels in the principal cell: sodium saving, potassium wasting. Exam ask: “what is the function of a nuclear receptor? How do they work”.", "dupOf": "T-nuclear-receptor-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-nuclear-receptor", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slides ~12–~14; Pharmacodynamics-Day-1-2026s.pdf slides ~35–~36; transcript 9/23", "quote": "Those are glucocor[tico]steroids. They are nuclear receptors. They affect DNA. They affect messenger RNA production.", "id": "T-nuclear-receptor-3", "stem": "Which term is defined as: Inside the cell; steroid binds, and gene expression and messenger RNA production change?", "options": [{"t": "Nuclear receptor", "correct": true, "why": "This is the definition of Nuclear (intracellular) receptor."}, {"t": "Down-regulation / desensitization", "correct": false, "why": "Down-regulation / desensitization: Fewer receptors after too much agonist; analogous to an irreversible antagonist."}, {"t": "Spare receptors", "correct": false, "why": "Spare receptors: Agonists need only a fraction of receptors for maximal effect; the rest are extra."}, {"t": "Up-regulation", "correct": false, "why": "Up-regulation: More receptors made after chronic antagonist; a compensatory mechanism, agonist becomes more potent."}], "teach": "Aldosterone at the mineralocorticoid receptor codes mRNA for more pumps and channels in the principal cell: sodium saving, potassium wasting. Exam ask: “what is the function of a nuclear receptor? How do they work”.", "dupOf": "T-nuclear-receptor-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-cross-talk", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~30; transcript 9/23", "quote": "So we have multiple receptors that can be activated at the same time as we talked a little bit about that earlier in our heart, we have two major receptors, the beta 1s, which are sympathetic, and the M2s, muscarinics, which are parasympathetic, right?", "id": "T-cross-talk-1", "stem": "Which term fits this situation? In one heart cell norepinephrine at β1 raises cyclic AMP while acetylcholine at M2 lowers it; the heart rate that results is the balance of the two.", "options": [{"t": "Cross-talk", "correct": true, "why": "This situation is cross-talk: Two receptors in one cell share an effector; the response is their net."}, {"t": "Gαs, Gαi and Gαq", "correct": false, "why": "Gαs, Gαi and Gαq would be: Three α types: s raises cyclic AMP, i lowers it, q releases calcium."}, {"t": "Second messenger", "correct": false, "why": "Second messenger would be: The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets."}, {"t": "Long-term down-regulation", "correct": false, "why": "Long-term down-regulation (internalization) would be: Receptor taken into the cell by endocytosis, then recycled or degraded in a lysosome."}], "teach": "Two receptors in one cell share an effector; the response is their net. Two receptors, two G proteins, one effector (AC): the heart rate is the net of the two.", "fg": "crosstalk"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-cross-talk", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~30; transcript 9/23", "quote": "So we have multiple receptors that can be activated at the same time as we talked a little bit about that earlier in our heart, we have two major receptors, the beta 1s, which are sympathetic, and the M2s, muscarinics, which are parasympathetic, right?", "id": "T-cross-talk-2", "stem": "Cross-talk means:", "options": [{"t": "Two receptors in one cell share an effector; the response is their net.", "correct": true, "why": "That is cross-talk."}, {"t": "The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets.", "correct": false, "why": "That is second messenger, not cross-talk."}, {"t": "Three α types: s raises cyclic AMP, i lowers it, q releases calcium.", "correct": false, "why": "That is gαs, gαi and gαq, not cross-talk."}, {"t": "Receptor taken into the cell by endocytosis, then recycled or degraded in a lysosome.", "correct": false, "why": "That is long-term down-regulation (internalization), not cross-talk."}], "teach": "Two receptors in one cell share an effector; the response is their net. Two receptors, two G proteins, one effector (AC): the heart rate is the net of the two.", "fg": "crosstalk", "dupOf": "T-cross-talk-1"},
{"lecture": "L02", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-cross-talk", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_2_2026s copy.pdf slide ~30; transcript 9/23", "quote": "So we have multiple receptors that can be activated at the same time as we talked a little bit about that earlier in our heart, we have two major receptors, the beta 1s, which are sympathetic, and the M2s, muscarinics, which are parasympathetic, right?", "id": "T-cross-talk-3", "stem": "Which term is defined as: Interaction between signal transduction pathways within the same cell that yields a net response. In the heart, M2 (Gαi, ↓cAMP, ↓HR) and β1 (Gαs, ↑cAMP, ↑HR) both act on adenylate cyclase?", "options": [{"t": "Cross-talk", "correct": true, "why": "This is the definition of Cross-talk."}, {"t": "Gαs, Gαi and Gαq", "correct": false, "why": "Gαs, Gαi and Gαq: Three α types: s raises cyclic AMP, i lowers it, q releases calcium."}, {"t": "Second messenger", "correct": false, "why": "Second messenger: The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets."}, {"t": "Long-term down-regulation", "correct": false, "why": "Long-term down-regulation (internalization): Receptor taken into the cell by endocytosis, then recycled or degraded in a lysosome."}], "teach": "Two receptors, two G proteins, one effector (AC): the heart rate is the net of the two.", "fg": "crosstalk", "dupOf": "T-cross-talk-1"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-baseline", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slides ~15, ~45–~46; transcript 9/28", "quote": "The baseline is just a reflection of the receptor activity that is happening.", "id": "T-baseline-1", "stem": "Which term fits this situation? In one cell line nearly all receptors sit inactive, so the agonist’s curve begins at 0%; in another, half the receptors are active on their own and the same agonist’s curve begins at 50%.", "options": [{"t": "Baseline", "correct": true, "why": "This situation is baseline (point of reference): Where the curve starts: receptor activity before any drug; 0% if most inactive."}, {"t": "Two-state model", "correct": false, "why": "Two-state model would be: Receptors flip between inactive R and active R*; drugs shift the balance."}, {"t": "Emax", "correct": false, "why": "Emax (maximal response, ceiling) would be: The plateau: all receptors occupied or the physiological system maxed out."}, {"t": "Quantal response", "correct": false, "why": "Quantal response would be: All-or-none in a population: alive or dead; cumulative plot gives a sigmoid."}], "teach": "Where the curve starts: receptor activity before any drug; 0% if most inactive. One \"greater than\" sign on the exam means about 99% of receptors are inactive and the baseline is zero. Full agonist raises it, inverse agonist lowers it to zero, neutral antagonists leave it alone.", "fg": "two-state"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-baseline", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slides ~15, ~45–~46; transcript 9/28", "quote": "The baseline is just a reflection of the receptor activity that is happening.", "id": "T-baseline-2", "stem": "Baseline means:", "options": [{"t": "Where the curve starts: receptor activity before any drug; 0% if most inactive.", "correct": true, "why": "That is baseline (point of reference)."}, {"t": "The linear mid-section; greatest change in effect from the smallest change in dose.", "correct": false, "why": "That is slope, not baseline (point of reference)."}, {"t": "The plateau: all receptors occupied or the physiological system maxed out.", "correct": false, "why": "That is emax (maximal response, ceiling), not baseline (point of reference)."}, {"t": "Receptors flip between inactive R and active R*; drugs shift the balance.", "correct": false, "why": "That is two-state model, not baseline (point of reference)."}], "teach": "Where the curve starts: receptor activity before any drug; 0% if most inactive. One \"greater than\" sign on the exam means about 99% of receptors are inactive and the baseline is zero. Full agonist raises it, inverse agonist lowers it to zero, neutral antagonists leave it alone.", "fg": "two-state", "dupOf": "T-baseline-1"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-baseline", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slides ~15, ~45–~46; transcript 9/28", "quote": "The baseline is just a reflection of the receptor activity that is happening.", "id": "T-baseline-3", "stem": "Which term is defined as: Where the curve starts: receptor activity before any drug; 0% if most inactive?", "options": [{"t": "Baseline", "correct": true, "why": "This is the definition of Baseline (point of reference)."}, {"t": "Two-state model", "correct": false, "why": "Two-state model: Receptors flip between inactive R and active R*; drugs shift the balance."}, {"t": "Emax", "correct": false, "why": "Emax (maximal response, ceiling): The plateau: all receptors occupied or the physiological system maxed out."}, {"t": "Quantal response", "correct": false, "why": "Quantal response: All-or-none in a population: alive or dead; cumulative plot gives a sigmoid."}], "teach": "One \"greater than\" sign on the exam means about 99% of receptors are inactive and the baseline is zero. Full agonist raises it, inverse agonist lowers it to zero, neutral antagonists leave it alone.", "fg": "two-state", "dupOf": "T-baseline-1"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-constitutive-activity", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~23; transcript 9/28", "quote": "Receptors that have constitutive activity are more sensitive to inverse agonists", "id": "T-constitutive-activity-1", "stem": "Which term fits this situation? A cell line’s histamine receptors produce a signal with no histamine in the dish; loratadine or cetirizine brings that signal to zero, which is why they were reclassified from antagonists.", "options": [{"t": "Constitutive activity", "correct": true, "why": "This situation is constitutive activity: Receptors active on their own, no drug present; what an inverse agonist removes."}, {"t": "G protein–coupled receptor", "correct": false, "why": "G protein–coupled receptor (GPCR, 7-TM) would be: Crosses the membrane seven times, coupled to a G protein; 60% of drugs."}, {"t": "Antagonist", "correct": false, "why": "Antagonist (neutral, reversible) would be: Zero efficacy, equal affinity for both receptor states; occupies, changes no balance."}, {"t": "G protein", "correct": false, "why": "G protein (heterotrimeric) would be: Three subunits; diphosphate off, triphosphate on, α leaves β and γ, activates the effector."}], "teach": "Receptors active on their own, no drug present; what an inverse agonist removes. Antihistamines were called antagonists until cell lines with naturally active receptors showed that loratadine and cetirizine bring the activity to zero. Listed receptors: histamine, opioid, cannabinoid, dopamine, bradykinin, adenosine.", "fg": "inverse"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-constitutive-activity", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~23; transcript 9/28", "quote": "Receptors that have constitutive activity are more sensitive to inverse agonists", "id": "T-constitutive-activity-2", "stem": "Constitutive activity means:", "options": [{"t": "Receptors active on their own, no drug present; what an inverse agonist removes.", "correct": true, "why": "That is constitutive activity."}, {"t": "Zero efficacy, equal affinity for both receptor states; occupies, changes no balance.", "correct": false, "why": "That is antagonist (neutral, reversible), not constitutive activity."}, {"t": "Three subunits; diphosphate off, triphosphate on, α leaves β and γ, activates the effector.", "correct": false, "why": "That is g protein (heterotrimeric), not constitutive activity."}, {"t": "Two receptors in one cell share an effector; the response is their net.", "correct": false, "why": "That is cross-talk, not constitutive activity."}], "teach": "Receptors active on their own, no drug present; what an inverse agonist removes. Antihistamines were called antagonists until cell lines with naturally active receptors showed that loratadine and cetirizine bring the activity to zero. Listed receptors: histamine, opioid, cannabinoid, dopamine, bradykinin, adenosine.", "fg": "inverse", "dupOf": "T-constitutive-activity-1"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-constitutive-activity", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~23; transcript 9/28", "quote": "Receptors that have constitutive activity are more sensitive to inverse agonists", "id": "T-constitutive-activity-3", "stem": "Which term is defined as: Receptors active on their own, no drug present; what an inverse agonist removes?", "options": [{"t": "Constitutive activity", "correct": true, "why": "This is the definition of Constitutive activity."}, {"t": "G protein–coupled receptor", "correct": false, "why": "G protein–coupled receptor (GPCR, 7-TM): Crosses the membrane seven times, coupled to a G protein; 60% of drugs."}, {"t": "Antagonist", "correct": false, "why": "Antagonist (neutral, reversible): Zero efficacy, equal affinity for both receptor states; occupies, changes no balance."}, {"t": "G protein", "correct": false, "why": "G protein (heterotrimeric): Three subunits; diphosphate off, triphosphate on, α leaves β and γ, activates the effector."}], "teach": "Antihistamines were called antagonists until cell lines with naturally active receptors showed that loratadine and cetirizine bring the activity to zero. Listed receptors: histamine, opioid, cannabinoid, dopamine, bradykinin, adenosine.", "fg": "inverse", "dupOf": "T-constitutive-activity-1"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-chemical-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~35; transcript 9/28", "quote": "Chemical: Direct chemical interaction between the agonist and antagonist. E.g. Chelating agents, dimercaprol", "id": "T-chemical-antagonist-1", "stem": "Which term fits this situation? A patient poisoned with mercury is given dimercaprol, which binds the metal directly so the body can excrete it; no receptor is involved anywhere.", "options": [{"t": "Chemical antagonist", "correct": true, "why": "This situation is chemical antagonist: Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury."}, {"t": "Physiological antagonist", "correct": false, "why": "Physiological antagonist would be: Two agonists at different receptors in one organ, pushing in opposite directions."}, {"t": "Competitive antagonist", "correct": false, "why": "Competitive (reversible) antagonist would be: Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum."}, {"t": "Irreversible antagonist", "correct": false, "why": "Irreversible (non-competitive) antagonist would be: Covalent, never comes off; agonist cannot outcompete it, the maximum falls toward zero."}], "teach": "Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury. No receptor is involved; the antagonist binds the chemical itself. Contrast physiological antagonism (two receptors, opposite effects)."},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-chemical-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~35; transcript 9/28", "quote": "Chemical: Direct chemical interaction between the agonist and antagonist. E.g. Chelating agents, dimercaprol", "id": "T-chemical-antagonist-2", "stem": "Chemical antagonist means:", "options": [{"t": "Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury.", "correct": true, "why": "That is chemical antagonist."}, {"t": "Covalent, never comes off; agonist cannot outcompete it, the maximum falls toward zero.", "correct": false, "why": "That is irreversible (non-competitive) antagonist, not chemical antagonist."}, {"t": "Two agonists at different receptors in one organ, pushing in opposite directions.", "correct": false, "why": "That is physiological antagonist, not chemical antagonist."}, {"t": "Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum.", "correct": false, "why": "That is competitive (reversible) antagonist, not chemical antagonist."}], "teach": "Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury. No receptor is involved; the antagonist binds the chemical itself. Contrast physiological antagonism (two receptors, opposite effects).", "dupOf": "T-chemical-antagonist-1"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-chemical-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~35; transcript 9/28", "quote": "Chemical: Direct chemical interaction between the agonist and antagonist. E.g. Chelating agents, dimercaprol", "id": "T-chemical-antagonist-3", "stem": "Which term is defined as: Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury?", "options": [{"t": "Chemical antagonist", "correct": true, "why": "This is the definition of Chemical antagonist."}, {"t": "Physiological antagonist", "correct": false, "why": "Physiological antagonist: Two agonists at different receptors in one organ, pushing in opposite directions."}, {"t": "Competitive antagonist", "correct": false, "why": "Competitive (reversible) antagonist: Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum."}, {"t": "Irreversible antagonist", "correct": false, "why": "Irreversible (non-competitive) antagonist: Covalent, never comes off; agonist cannot outcompete it, the maximum falls toward zero."}], "teach": "No receptor is involved; the antagonist binds the chemical itself. Contrast physiological antagonism (two receptors, opposite effects).", "dupOf": "T-chemical-antagonist-1"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-physiological-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~35; transcript 9/28", "quote": "They bind to two different receptors in the same organ and producing opposite effects. They’re not competing for the same receptor, they’re just producing different effects.", "id": "T-physiological-antagonist-1", "stem": "Which term fits this situation? Acetylcholine at muscarinic receptors slows the heart while epinephrine at β1 speeds it up; neither drug touches the other’s receptor, yet each undoes the other’s effect.", "options": [{"t": "Physiological antagonist", "correct": true, "why": "This situation is physiological antagonist: Two agonists at different receptors in one organ, pushing in opposite directions."}, {"t": "Surmountable / insurmountable", "correct": false, "why": "Surmountable / insurmountable would be: Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost."}, {"t": "Chemical antagonist", "correct": false, "why": "Chemical antagonist would be: Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury."}, {"t": "Competitive antagonist", "correct": false, "why": "Competitive (reversible) antagonist would be: Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum."}], "teach": "Two agonists at different receptors in one organ, pushing in opposite directions. They are not competing for the same receptor; they are affecting the physiology in opposite directions."},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-physiological-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~35; transcript 9/28", "quote": "They bind to two different receptors in the same organ and producing opposite effects. They’re not competing for the same receptor, they’re just producing different effects.", "id": "T-physiological-antagonist-2", "stem": "Physiological antagonist means:", "options": [{"t": "Two agonists at different receptors in one organ, pushing in opposite directions.", "correct": true, "why": "That is physiological antagonist."}, {"t": "Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury.", "correct": false, "why": "That is chemical antagonist, not physiological antagonist."}, {"t": "Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum.", "correct": false, "why": "That is competitive (reversible) antagonist, not physiological antagonist."}, {"t": "Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost.", "correct": false, "why": "That is surmountable / insurmountable, not physiological antagonist."}], "teach": "Two agonists at different receptors in one organ, pushing in opposite directions. They are not competing for the same receptor; they are affecting the physiology in opposite directions.", "dupOf": "T-physiological-antagonist-1"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-physiological-antagonist", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~35; transcript 9/28", "quote": "They bind to two different receptors in the same organ and producing opposite effects. They’re not competing for the same receptor, they’re just producing different effects.", "id": "T-physiological-antagonist-3", "stem": "Which term is defined as: Two agonists acting independently of each other at different receptors in the same organ and producing opposing effects. Example of the year: acetylcholine at muscarinic receptors lowers heart rate while epinephrine at β1 raises it?", "options": [{"t": "Physiological antagonist", "correct": true, "why": "This is the definition of Physiological antagonist."}, {"t": "Surmountable / insurmountable", "correct": false, "why": "Surmountable / insurmountable: Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost."}, {"t": "Chemical antagonist", "correct": false, "why": "Chemical antagonist: Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury."}, {"t": "Competitive antagonist", "correct": false, "why": "Competitive (reversible) antagonist: Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum."}], "teach": "They are not competing for the same receptor; they are affecting the physiology in opposite directions.", "dupOf": "T-physiological-antagonist-1"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-surmountable", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~36; transcript 9/28", "quote": "One is competitive antagonist, also known as reversible antagonists, also known as surmountable antagonists, different names for the same drug. They bind and they come off.", "id": "T-surmountable-1", "stem": "Which term fits this situation? With prazosin on board, raising norepinephrine enough restores the top response; with phenoxybenzamine on board, no amount of norepinephrine brings it back.", "options": [{"t": "Surmountable / insurmountable", "correct": true, "why": "This situation is surmountable / insurmountable: Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost."}, {"t": "Acetylcholinesterase inhibitor", "correct": false, "why": "Acetylcholinesterase inhibitor (physostigmine) would be: Blocks the enzyme breaking down acetylcholine; acetylcholine rises and appears more potent."}, {"t": "Inverse agonist", "correct": false, "why": "Inverse agonist would be: Prefers the inactive receptor; negative efficacy, takes the baseline down to zero."}, {"t": "Chemical antagonist", "correct": false, "why": "Chemical antagonist would be: Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury."}], "teach": "Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost. When to apply it: ask \"can the agonist still reach its maximum if I give enough?\" Yes, curve shifted right with the same top = surmountable (metoprolol, prazosin). No, the top comes down = insurmountable (phenoxybenzamine).", "fg": "shift-competitive"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-surmountable", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slide ~36; transcript 9/28", "quote": "One is competitive antagonist, also known as reversible antagonists, also known as surmountable antagonists, different names for the same drug. They bind and they come off.", "id": "T-surmountable-2", "stem": "Surmountable / insurmountable means:", "options": [{"t": "Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost.", "correct": true, "why": "That is surmountable / insurmountable."}, {"t": "Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury.", "correct": false, "why": "That is chemical antagonist, not surmountable / insurmountable."}, {"t": "Prefers the inactive receptor; negative efficacy, takes the baseline down to zero.", "correct": false, "why": "That is inverse agonist, not surmountable / insurmountable."}, {"t": "Positive efficacy but below 100%; may act as agonist or antagonist by state.", "correct": false, "why": "That is partial agonist, not surmountable / insurmountable."}], "teach": "Surmountable: more agonist wins back the full Emax. Insurmountable: the Emax is lost. When to apply it: ask \"can the agonist still reach its maximum if I give enough?\" Yes, curve shifted right with the same top = surmountable (metoprolol, prazosin). No, the top comes down = insurmountable (phenoxybenzamine).", "fg": "shift-competitive", "dupOf": "T-surmountable-1"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-symmetrical-shift", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slides ~30–~34, ~38, ~48–~50, ~53–~54; transcript 9/28", "quote": "if I increase the dose by tenfold, I have to increase the dose of the other by tenfold to outcompete them.", "id": "T-symmetrical-shift-2", "stem": "Symmetrical vs asymmetrical shifts means:", "options": [{"t": "Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric.", "correct": true, "why": "That is symmetrical vs asymmetrical shifts."}, {"t": "In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age.", "correct": false, "why": "That is apparent potency, not symmetrical vs asymmetrical shifts."}, {"t": "Once every allosteric site is occupied, more drug produces no further shift.", "correct": false, "why": "That is saturability (allosteric), not symmetrical vs asymmetrical shifts."}, {"t": "All-or-none in a population: alive or dead; cumulative plot gives a sigmoid.", "correct": false, "why": "That is quantal response, not symmetrical vs asymmetrical shifts."}], "teach": "Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric. Asymmetrical plus saturable is how an allosteric drug is recognized on a figure.", "fg": "competitive"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-saturability", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slides ~30–~34; transcript 9/28", "quote": "I can keep giving more and more of my allosteric, and he can’t go more to the left. He has maxed out all that he can do to the system.", "id": "T-saturability-1", "stem": "Which term fits this situation? At 100x, 1000x and 10,000x the second drug the agonist’s curve stops moving; every one of the second drug’s sites on the receptor is already taken, while more prazosin would keep moving it toward infinity.", "options": [{"t": "Saturability", "correct": true, "why": "This situation is saturability (allosteric): Once every allosteric site is occupied, more drug produces no further shift."}, {"t": "Symmetrical vs asymmetrical shifts", "correct": false, "why": "Symmetrical vs asymmetrical shifts would be: Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric."}, {"t": "Irreversible antagonist", "correct": false, "why": "Irreversible (non-competitive) antagonist would be: Covalent, never comes off; agonist cannot outcompete it, the maximum falls toward zero."}, {"t": "Baseline", "correct": false, "why": "Baseline (point of reference) would be: Where the curve starts: receptor activity before any drug; 0% if most inactive."}], "teach": "Once every allosteric site is occupied, more drug produces no further shift. An allosteric antagonist cannot bring the response all the way to zero; an irreversible antagonist can."},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-saturability", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slides ~30–~34; transcript 9/28", "quote": "I can keep giving more and more of my allosteric, and he can’t go more to the left. He has maxed out all that he can do to the system.", "id": "T-saturability-2", "stem": "Saturability means:", "options": [{"t": "Once every allosteric site is occupied, more drug produces no further shift.", "correct": true, "why": "That is saturability (allosteric)."}, {"t": "Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric.", "correct": false, "why": "That is symmetrical vs asymmetrical shifts, not saturability (allosteric)."}, {"t": "Covalent, never comes off; agonist cannot outcompete it, the maximum falls toward zero.", "correct": false, "why": "That is irreversible (non-competitive) antagonist, not saturability (allosteric)."}, {"t": "Where the curve starts: receptor activity before any drug; 0% if most inactive.", "correct": false, "why": "That is baseline (point of reference), not saturability (allosteric)."}], "teach": "Once every allosteric site is occupied, more drug produces no further shift. An allosteric antagonist cannot bring the response all the way to zero; an irreversible antagonist can.", "dupOf": "T-saturability-1"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-spare-receptors", "tags": ["term"], "source": "both", "cite": "transcript 9/28; Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slides ~54, ~56; Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 1–3; transcript 9/29", "quote": "Our agonists don’t have to occupy 100% of the receptors to produce a response. They only have to occupy a certain percentage of those receptors to do so.", "id": "T-spare-receptors-1", "stem": "Which term fits this situation? A tissue reaches its full response when only 10% of its receptors are occupied; blocking 75% of them irreversibly still allows the maximal response at a higher dose.", "options": [{"t": "Spare receptors", "correct": true, "why": "This situation is spare receptors: Agonists need only a fraction of receptors for maximal effect; the rest are extra."}, {"t": "G protein–coupled receptor", "correct": false, "why": "G protein–coupled receptor (GPCR, 7-TM) would be: Crosses the membrane seven times, coupled to a G protein; 60% of drugs."}, {"t": "Effector", "correct": false, "why": "Effector (signal amplifier) would be: The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C."}, {"t": "Second messenger", "correct": false, "why": "Second messenger would be: The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets."}], "teach": "Agonists need only a fraction of receptors for maximal effect; the rest are extra. Worked example: agonist needs 10%; blocking 75% or 85% still allows the max response at a higher dose; below 10% available the Emax drops toward zero. Take-home 9/29: the more spare receptors, the more potent the agonist; a tissue with many receptors responds to an irreversible antagonist as if it were competitive at first.", "fg": "spare"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-spare-receptors", "tags": ["term"], "source": "both", "cite": "transcript 9/28; Pharmacodynamics-Day_4_-_5_2026s_pptx.pdf slides ~54, ~56; Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 1–3; transcript 9/29", "quote": "Our agonists don’t have to occupy 100% of the receptors to produce a response. They only have to occupy a certain percentage of those receptors to do so.", "id": "T-spare-receptors-2", "stem": "Spare receptors means:", "options": [{"t": "Agonists need only a fraction of receptors for maximal effect; the rest are extra.", "correct": true, "why": "That is spare receptors."}, {"t": "The enzyme or channel making or degrading the second messenger; adenylate cyclase, phospholipase C.", "correct": false, "why": "That is effector (signal amplifier), not spare receptors."}, {"t": "Crosses the membrane seven times, coupled to a G protein; 60% of drugs.", "correct": false, "why": "That is g protein–coupled receptor (gpcr, 7-tm), not spare receptors."}, {"t": "The small molecule the effector makes: cyclic AMP, calcium; it diffuses to its targets.", "correct": false, "why": "That is second messenger, not spare receptors."}], "teach": "Agonists need only a fraction of receptors for maximal effect; the rest are extra. Worked example: agonist needs 10%; blocking 75% or 85% still allows the max response at a higher dose; below 10% available the Emax drops toward zero. Take-home 9/29: the more spare receptors, the more potent the agonist; a tissue with many receptors responds to an irreversible antagonist as if it were competitive at first.", "fg": "spare", "dupOf": "T-spare-receptors-1"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-withdrawal-syndrome", "tags": ["term"], "source": "transcript", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~64–~65; transcript 9/28", "quote": "Withdrawal syndrome is the opposite of what the drug produces.", "id": "T-withdrawal-syndrome-1", "stem": "Which term fits this situation? Nicotine relaxed a smoker, lowered appetite and raised blood pressure; when the cigarettes stop, irritability, overeating and lower blood pressure take their place.", "options": [{"t": "Withdrawal syndrome", "correct": true, "why": "This situation is withdrawal syndrome: The opposite of what the drug produced, appearing when the drug is stopped."}, {"t": "Natural dietary supplement", "correct": false, "why": "Natural dietary supplement (NDS) would be: Regulated as food, not as a drug; the label cannot claim to cure."}, {"t": "Addition", "correct": false, "why": "Addition (drug–drug) would be: Two drugs with the same effect; the result equals the sum of each."}, {"t": "Pharmacokinetics", "correct": false, "why": "Pharmacokinetics (PK) would be: Absorption, distribution, metabolism, excretion: how much drug gets to the site of action."}], "teach": "The opposite of what the drug produced, appearing when the drug is stopped. The reason people cannot stop smoking; the reason a partial agonist is used for smoking cessation.", "fg": "partial"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-withdrawal-syndrome", "tags": ["term"], "source": "transcript", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~64–~65; transcript 9/28", "quote": "Withdrawal syndrome is the opposite of what the drug produces.", "id": "T-withdrawal-syndrome-2", "stem": "Withdrawal syndrome means:", "options": [{"t": "The opposite of what the drug produced, appearing when the drug is stopped.", "correct": true, "why": "That is withdrawal syndrome."}, {"t": "Absorption, distribution, metabolism, excretion: how much drug gets to the site of action.", "correct": false, "why": "That is pharmacokinetics (pk), not withdrawal syndrome."}, {"t": "Two drugs with the same effect; the result equals the sum of each.", "correct": false, "why": "That is addition (drug–drug), not withdrawal syndrome."}, {"t": "Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food.", "correct": false, "why": "That is ligand, not withdrawal syndrome."}], "teach": "The opposite of what the drug produced, appearing when the drug is stopped. The reason people cannot stop smoking; the reason a partial agonist is used for smoking cessation.", "fg": "partial", "dupOf": "T-withdrawal-syndrome-1"},
{"lecture": "L04", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-withdrawal-syndrome", "tags": ["term"], "source": "transcript", "cite": "Pharmacodynamics-Day_3_2026s.pdf slides ~64–~65; transcript 9/28", "quote": "Withdrawal syndrome is the opposite of what the drug produces.", "id": "T-withdrawal-syndrome-3", "stem": "Which term is defined as: The opposite of what the drug produced, appearing when the drug is stopped?", "options": [{"t": "Withdrawal syndrome", "correct": true, "why": "This is the definition of Withdrawal syndrome."}, {"t": "Natural dietary supplement", "correct": false, "why": "Natural dietary supplement (NDS): Regulated as food, not as a drug; the label cannot claim to cure."}, {"t": "Addition", "correct": false, "why": "Addition (drug–drug): Two drugs with the same effect; the result equals the sum of each."}, {"t": "Pharmacokinetics", "correct": false, "why": "Pharmacokinetics (PK): Absorption, distribution, metabolism, excretion: how much drug gets to the site of action."}], "teach": "The reason people cannot stop smoking; the reason a partial agonist is used for smoking cessation.", "fg": "partial", "dupOf": "T-withdrawal-syndrome-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-up-regulation", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 17–19; transcript 9/29", "quote": "So typically an antagonist will up regulate, an agonist is going to down regulate because our body is going to do the opposite to maintain that homeostasis.", "id": "T-up-regulation-1", "stem": "Which term fits this situation? After months on a β-blocker the heart has grown many more β receptors; stop the blocker cold turkey and norepinephrine meets all of them at once, a hypertensive crisis, so the dose is tapered stepwise.", "options": [{"t": "Up-regulation", "correct": true, "why": "This situation is up-regulation: More receptors made after chronic antagonist; a compensatory mechanism, agonist becomes more potent."}, {"t": "Down-regulation / desensitization", "correct": false, "why": "Down-regulation / desensitization would be: Fewer receptors after too much agonist; analogous to an irreversible antagonist."}, {"t": "Transducer", "correct": false, "why": "Transducer would be: Translates the activated receptor’s change to the effector; the G protein."}, {"t": "Cross-talk", "correct": false, "why": "Cross-talk would be: Two receptors in one cell share an effector; the response is their net."}], "teach": "More receptors made after chronic antagonist; a compensatory mechanism, agonist becomes more potent. Stopping a β-blocker cold turkey leaves many up-regulated receptors unblocked: hypertensive crisis, so taper stepwise. Other examples: chronic denervation, thyroid hormone.", "fg": "regulation"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-up-regulation", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 17–19; transcript 9/29", "quote": "So typically an antagonist will up regulate, an agonist is going to down regulate because our body is going to do the opposite to maintain that homeostasis.", "id": "T-up-regulation-2", "stem": "Up-regulation means:", "options": [{"t": "More receptors made after chronic antagonist; a compensatory mechanism, agonist becomes more potent.", "correct": true, "why": "That is up-regulation."}, {"t": "A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane.", "correct": false, "why": "That is rapid desensitization (grk / β-arrestin), not up-regulation."}, {"t": "Fewer receptors after too much agonist; analogous to an irreversible antagonist.", "correct": false, "why": "That is down-regulation / desensitization, not up-regulation."}, {"t": "Translates the activated receptor’s change to the effector; the G protein.", "correct": false, "why": "That is transducer, not up-regulation."}], "teach": "More receptors made after chronic antagonist; a compensatory mechanism, agonist becomes more potent. Stopping a β-blocker cold turkey leaves many up-regulated receptors unblocked: hypertensive crisis, so taper stepwise. Other examples: chronic denervation, thyroid hormone.", "fg": "regulation", "dupOf": "T-up-regulation-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-up-regulation", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 17–19; transcript 9/29", "quote": "So typically an antagonist will up regulate, an agonist is going to down regulate because our body is going to do the opposite to maintain that homeostasis.", "id": "T-up-regulation-3", "stem": "Which term is defined as: An increase in the number of receptors (more spare receptors) that follows chronic reduction of receptor stimulation, typically by an antagonist or inverse agonist; a compensatory mechanism. It increases the potency of a full agonist (shift left) and the potency and/or maximal response of a partial agonist?", "options": [{"t": "Up-regulation", "correct": true, "why": "This is the definition of Up-regulation."}, {"t": "Down-regulation / desensitization", "correct": false, "why": "Down-regulation / desensitization: Fewer receptors after too much agonist; analogous to an irreversible antagonist."}, {"t": "Transducer", "correct": false, "why": "Transducer: Translates the activated receptor’s change to the effector; the G protein."}, {"t": "Cross-talk", "correct": false, "why": "Cross-talk: Two receptors in one cell share an effector; the response is their net."}], "teach": "Stopping a β-blocker cold turkey leaves many up-regulated receptors unblocked: hypertensive crisis, so taper stepwise. Other examples: chronic denervation, thyroid hormone.", "fg": "regulation", "dupOf": "T-up-regulation-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-down-regulation", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 20–21, 25–29; transcript 9/29", "quote": "Down-Regulation/Desensitization: Analogous to the effects of irreversible acting antagonists", "id": "T-down-regulation-1", "stem": "Which term fits this situation? A Levophed (norepinephrine) drip has run for days and the cell has removed many of its receptors; shut the drip off and the blood pressure tanks.", "options": [{"t": "Down-regulation / desensitization", "correct": true, "why": "This situation is down-regulation / desensitization: Fewer receptors after too much agonist; analogous to an irreversible antagonist."}, {"t": "Symmetrical vs asymmetrical shifts", "correct": false, "why": "Symmetrical vs asymmetrical shifts would be: Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric."}, {"t": "Up-regulation", "correct": false, "why": "Up-regulation would be: More receptors made after chronic antagonist; a compensatory mechanism, agonist becomes more potent."}, {"t": "Tolerance", "correct": false, "why": "Tolerance would be: Continued exposure to the same concentration gives a diminished effect; the clinical manifestation."}], "teach": "Fewer receptors after too much agonist; analogous to an irreversible antagonist. Clinical manifestations: tolerance (opioids, Afrin-type nasal decongestants, cocaine) and myasthenia gravis. Shut off a Levophed drip and the pressure tanks.", "fg": "regulation"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-down-regulation", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 20–21, 25–29; transcript 9/29", "quote": "Down-Regulation/Desensitization: Analogous to the effects of irreversible acting antagonists", "id": "T-down-regulation-2", "stem": "Down-regulation / desensitization means:", "options": [{"t": "Fewer receptors after too much agonist; analogous to an irreversible antagonist.", "correct": true, "why": "That is down-regulation / desensitization."}, {"t": "More receptors made after chronic antagonist; a compensatory mechanism, agonist becomes more potent.", "correct": false, "why": "That is up-regulation, not down-regulation / desensitization."}, {"t": "Continued exposure to the same concentration gives a diminished effect; the clinical manifestation.", "correct": false, "why": "That is tolerance, not down-regulation / desensitization."}, {"t": "Inside the cell; steroid binds, and gene expression and messenger RNA production change.", "correct": false, "why": "That is nuclear (intracellular) receptor, not down-regulation / desensitization."}], "teach": "Fewer receptors after too much agonist; analogous to an irreversible antagonist. Clinical manifestations: tolerance (opioids, Afrin-type nasal decongestants, cocaine) and myasthenia gravis. Shut off a Levophed drip and the pressure tanks.", "fg": "regulation", "dupOf": "T-down-regulation-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-down-regulation", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 20–21, 25–29; transcript 9/29", "quote": "Down-Regulation/Desensitization: Analogous to the effects of irreversible acting antagonists", "id": "T-down-regulation-3", "stem": "Which term is defined as: Fewer receptors after too much agonist; analogous to an irreversible antagonist?", "options": [{"t": "Down-regulation / desensitization", "correct": true, "why": "This is the definition of Down-regulation / desensitization."}, {"t": "Symmetrical vs asymmetrical shifts", "correct": false, "why": "Symmetrical vs asymmetrical shifts: Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric."}, {"t": "Up-regulation", "correct": false, "why": "Up-regulation: More receptors made after chronic antagonist; a compensatory mechanism, agonist becomes more potent."}, {"t": "Tolerance", "correct": false, "why": "Tolerance: Continued exposure to the same concentration gives a diminished effect; the clinical manifestation."}], "teach": "Clinical manifestations: tolerance (opioids, Afrin-type nasal decongestants, cocaine) and myasthenia gravis. Shut off a Levophed drip and the pressure tanks.", "fg": "regulation", "dupOf": "T-down-regulation-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-rapid-desensitization", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 21–24; transcript 9/29", "quote": "GRK phosphorylates and allows the binding of β-arrestin", "id": "T-rapid-desensitization-1", "stem": "Which term fits this situation? With the agonist still bound, the receptor’s tail is phosphorylated and a regulatory protein attaches, and the cyclic AMP trace falls flat within milliseconds; once the agonist leaves, the receptor resets. It never left the membrane.", "options": [{"t": "Rapid desensitization", "correct": true, "why": "This situation is rapid desensitization (grk / β-arrestin): A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane."}, {"t": "Down-regulation / desensitization", "correct": false, "why": "Down-regulation / desensitization would be: Fewer receptors after too much agonist; analogous to an irreversible antagonist."}, {"t": "Long-term down-regulation", "correct": false, "why": "Long-term down-regulation (internalization) would be: Receptor taken into the cell by endocytosis, then recycled or degraded in a lysosome."}, {"t": "Cross-talk", "correct": false, "why": "Cross-talk would be: Two receptors in one cell share an effector; the response is their net."}], "teach": "A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane. β-arrestin is the stop plug; long-term regulation (synthesis, degradation, internalization) takes time. Poll trap: short-term regulation does not involve relocation into the cell.", "fg": "desens-rapid"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-long-term-down-regulation", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 21, 27; transcript 9/29", "quote": "Endocytosis · Binding to coated pits · Recycling · Degradation", "id": "T-long-term-down-regulation-1", "stem": "Which term fits this situation? With cocaine or opioids stimulating the receptors day after day, β-arrestin pulls receptors into coated pits, they are taken inside by endocytosis and sent to a lysosome, and the surface count stays low.", "options": [{"t": "Long-term down-regulation", "correct": true, "why": "This situation is long-term down-regulation (internalization): Receptor taken into the cell by endocytosis, then recycled or degraded in a lysosome."}, {"t": "Down-regulation / desensitization", "correct": false, "why": "Down-regulation / desensitization would be: Fewer receptors after too much agonist; analogous to an irreversible antagonist."}, {"t": "Rapid desensitization", "correct": false, "why": "Rapid desensitization (GRK / β-arrestin) would be: A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane."}, {"t": "Constitutive activity", "correct": false, "why": "Constitutive activity would be: Receptors active on their own, no drug present; what an inverse agonist removes."}], "teach": "Receptor taken into the cell by endocytosis, then recycled or degraded in a lysosome. Endocytosis, binding to coated pits, recycling, degradation. Cocaine or opioid use keeps stimulating, so the cell gets rid of receptors and keeps them low.", "fg": "desens-long"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-long-term-down-regulation", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 21, 27; transcript 9/29", "quote": "Endocytosis · Binding to coated pits · Recycling · Degradation", "id": "T-long-term-down-regulation-2", "stem": "Long-term down-regulation means:", "options": [{"t": "Receptor taken into the cell by endocytosis, then recycled or degraded in a lysosome.", "correct": true, "why": "That is long-term down-regulation (internalization)."}, {"t": "A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane.", "correct": false, "why": "That is rapid desensitization (grk / β-arrestin), not long-term down-regulation (internalization)."}, {"t": "Fewer receptors after too much agonist; analogous to an irreversible antagonist.", "correct": false, "why": "That is down-regulation / desensitization, not long-term down-regulation (internalization)."}, {"t": "Receptors active on their own, no drug present; what an inverse agonist removes.", "correct": false, "why": "That is constitutive activity, not long-term down-regulation (internalization)."}], "teach": "Receptor taken into the cell by endocytosis, then recycled or degraded in a lysosome. Endocytosis, binding to coated pits, recycling, degradation. Cocaine or opioid use keeps stimulating, so the cell gets rid of receptors and keeps them low.", "fg": "desens-long", "dupOf": "T-long-term-down-regulation-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g5", "skill": "term", "concept": "term-long-term-down-regulation", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 21, 27; transcript 9/29", "quote": "Endocytosis · Binding to coated pits · Recycling · Degradation", "id": "T-long-term-down-regulation-3", "stem": "Which term is defined as: With continued over-stimulation, β-arrestin facilitates uptake of the receptor into coated pits; the receptor is removed from the surface by endocytosis and then either recycled back or degraded in a lysosome. A receptor that is not in the cell membrane cannot bind anything?", "options": [{"t": "Long-term down-regulation", "correct": true, "why": "This is the definition of Long-term down-regulation (internalization)."}, {"t": "Down-regulation / desensitization", "correct": false, "why": "Down-regulation / desensitization: Fewer receptors after too much agonist; analogous to an irreversible antagonist."}, {"t": "Rapid desensitization", "correct": false, "why": "Rapid desensitization (GRK / β-arrestin): A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane."}, {"t": "Constitutive activity", "correct": false, "why": "Constitutive activity: Receptors active on their own, no drug present; what an inverse agonist removes."}], "teach": "Endocytosis, binding to coated pits, recycling, degradation. Cocaine or opioid use keeps stimulating, so the cell gets rid of receptors and keeps them low.", "fg": "desens-long", "dupOf": "T-long-term-down-regulation-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-tolerance", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 29; transcript 9/29", "quote": "Tolerance: The effects that follow continue exposure to the same concentration of drug is diminished", "id": "T-tolerance-1", "stem": "Which term fits this situation? A patient uses a nasal decongestant spray every day past the 2 to 3 days the box allows; soon the same dose no longer opens the nose and more is needed.", "options": [{"t": "Tolerance", "correct": true, "why": "This situation is tolerance: Continued exposure to the same concentration gives a diminished effect; the clinical manifestation."}, {"t": "Withdrawal syndrome", "correct": false, "why": "Withdrawal syndrome would be: The opposite of what the drug produced, appearing when the drug is stopped."}, {"t": "Addition", "correct": false, "why": "Addition (drug–drug) would be: Two drugs with the same effect; the result equals the sum of each."}, {"t": "Pharmacokinetics", "correct": false, "why": "Pharmacokinetics (PK) would be: Absorption, distribution, metabolism, excretion: how much drug gets to the site of action."}], "teach": "Continued exposure to the same concentration gives a diminished effect; the clinical manifestation. The Afrin box says 2 to 3 days only; the body lowers the receptor number to counteract the stimulation, so more drug is needed for the same effect.", "fg": "desens-long"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-tolerance", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 29; transcript 9/29", "quote": "Tolerance: The effects that follow continue exposure to the same concentration of drug is diminished", "id": "T-tolerance-2", "stem": "Tolerance means:", "options": [{"t": "Continued exposure to the same concentration gives a diminished effect; the clinical manifestation.", "correct": true, "why": "That is tolerance."}, {"t": "Shared pair of electrons; unbreakable at body temperature; aspirin, omeprazole, phenoxybenzamine form it.", "correct": false, "why": "That is covalent (irreversible) bond, not tolerance."}, {"t": "The opposite of what the drug produced, appearing when the drug is stopped.", "correct": false, "why": "That is withdrawal syndrome, not tolerance."}, {"t": "Two drugs with the same effect; the result equals the sum of each.", "correct": false, "why": "That is addition (drug–drug), not tolerance."}], "teach": "Continued exposure to the same concentration gives a diminished effect; the clinical manifestation. The Afrin box says 2 to 3 days only; the body lowers the receptor number to counteract the stimulation, so more drug is needed for the same effect.", "fg": "desens-long", "dupOf": "T-tolerance-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-tolerance", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 29; transcript 9/29", "quote": "Tolerance: The effects that follow continue exposure to the same concentration of drug is diminished", "id": "T-tolerance-3", "stem": "Which term is defined as: The effects that follow continued exposure to the same concentration of a drug are diminished. A clinical manifestation of receptor down-regulation: opioid analgesics, α-adrenoreceptor agonists used as nasal decongestants?", "options": [{"t": "Tolerance", "correct": true, "why": "This is the definition of Tolerance."}, {"t": "Withdrawal syndrome", "correct": false, "why": "Withdrawal syndrome: The opposite of what the drug produced, appearing when the drug is stopped."}, {"t": "Addition", "correct": false, "why": "Addition (drug–drug): Two drugs with the same effect; the result equals the sum of each."}, {"t": "Pharmacokinetics", "correct": false, "why": "Pharmacokinetics (PK): Absorption, distribution, metabolism, excretion: how much drug gets to the site of action."}], "teach": "The Afrin box says 2 to 3 days only; the body lowers the receptor number to counteract the stimulation, so more drug is needed for the same effect.", "fg": "desens-long", "dupOf": "T-tolerance-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-reuptake-inhibitor", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 9–11; transcript 9/29", "quote": "making serotonin more potent by taking away its break down", "id": "T-reuptake-inhibitor-1", "stem": "Which term fits this situation? Fluoxetine blocks the transporter that carries serotonin back into the neuron, so serotonin stays in the synapse longer; its curve moves left with the same top, since the drug is still serotonin.", "options": [{"t": "Reuptake inhibitor", "correct": true, "why": "This situation is reuptake inhibitor (ssri / snri): Blocks the transporter returning the neurotransmitter; more stays in the synapse, curve shifts left."}, {"t": "Chemical antagonist", "correct": false, "why": "Chemical antagonist would be: Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury."}, {"t": "Allosteric agonist", "correct": false, "why": "Allosteric agonist (PAM) would be: Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam."}, {"t": "Inverse agonist", "correct": false, "why": "Inverse agonist would be: Prefers the inactive receptor; negative efficacy, takes the baseline down to zero."}], "teach": "Blocks the transporter returning the neurotransmitter; more stays in the synapse, curve shifts left. Same principle, different target as physostigmine (enzyme blocker). Cocaine blocks norepinephrine reuptake the same way and leads to down-regulation.", "fg": "ind-ssri"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-reuptake-inhibitor", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 9–11; transcript 9/29", "quote": "making serotonin more potent by taking away its break down", "id": "T-reuptake-inhibitor-2", "stem": "Reuptake inhibitor means:", "options": [{"t": "Blocks the transporter returning the neurotransmitter; more stays in the synapse, curve shifts left.", "correct": true, "why": "That is reuptake inhibitor (ssri / snri)."}, {"t": "A kinase phosphorylates the agonist-bound receptor, β-arrestin stops it; milliseconds, reversible, stays in membrane.", "correct": false, "why": "That is rapid desensitization (grk / β-arrestin), not reuptake inhibitor (ssri / snri)."}, {"t": "Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam.", "correct": false, "why": "That is allosteric agonist (pam), not reuptake inhibitor (ssri / snri)."}, {"t": "Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury.", "correct": false, "why": "That is chemical antagonist, not reuptake inhibitor (ssri / snri)."}], "teach": "Blocks the transporter returning the neurotransmitter; more stays in the synapse, curve shifts left. Same principle, different target as physostigmine (enzyme blocker). Cocaine blocks norepinephrine reuptake the same way and leads to down-regulation.", "fg": "ind-ssri", "dupOf": "T-reuptake-inhibitor-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-reuptake-inhibitor", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 9–11; transcript 9/29", "quote": "making serotonin more potent by taking away its break down", "id": "T-reuptake-inhibitor-3", "stem": "Which term is defined as: An indirect antagonist that blocks the transporter returning a neurotransmitter to the neuron (fluoxetine at SERT; duloxetine at the serotonin and norepinephrine transporters). More neurotransmitter stays in the synapse, so it appears more potent: its curve shifts left with the same Emax?", "options": [{"t": "Reuptake inhibitor", "correct": true, "why": "This is the definition of Reuptake inhibitor (SSRI / SNRI)."}, {"t": "Chemical antagonist", "correct": false, "why": "Chemical antagonist: Binds the agonist or toxin itself, no receptor involved; dimercaprol chelates mercury."}, {"t": "Allosteric agonist", "correct": false, "why": "Allosteric agonist (PAM): Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam."}, {"t": "Inverse agonist", "correct": false, "why": "Inverse agonist: Prefers the inactive receptor; negative efficacy, takes the baseline down to zero."}], "teach": "Same principle, different target as physostigmine (enzyme blocker). Cocaine blocks norepinephrine reuptake the same way and leads to down-regulation.", "fg": "ind-ssri", "dupOf": "T-reuptake-inhibitor-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-acetylcholinesterase-inhibitor", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 12–13, 29; transcript 9/29", "quote": "by blocking the enzyme, I can increase the levels of acetylcholine, the more acetylcholine I have, the more receptors I can bind, and thus make acetylcholine more potent, thus shifting to the left.", "id": "T-acetylcholinesterase-inhibitor-1", "stem": "Which term fits this situation? In myasthenia gravis, antibodies have removed nicotinic receptors from skeletal muscle; a -stigmine drug stops the enzyme that destroys acetylcholine, more acetylcholine reaches the receptors left, and the weakness eases.", "options": [{"t": "Acetylcholinesterase inhibitor", "correct": true, "why": "This situation is acetylcholinesterase inhibitor (physostigmine): Blocks the enzyme breaking down acetylcholine; acetylcholine rises and appears more potent."}, {"t": "Symmetrical vs asymmetrical shifts", "correct": false, "why": "Symmetrical vs asymmetrical shifts would be: Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric."}, {"t": "Reuptake inhibitor", "correct": false, "why": "Reuptake inhibitor (SSRI / SNRI) would be: Blocks the transporter returning the neurotransmitter; more stays in the synapse, curve shifts left."}, {"t": "Allosteric agonist", "correct": false, "why": "Allosteric agonist (PAM) would be: Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam."}], "teach": "Blocks the enzyme breaking down acetylcholine; acetylcholine rises and appears more potent. Any drug ending in -stigmine. Myasthenia gravis: about 90% autoimmune, antibodies target the nicotinic receptors of skeletal muscle (down-regulation), progressive weakness through the day.", "fg": "ind-ache"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-acetylcholinesterase-inhibitor", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 12–13, 29; transcript 9/29", "quote": "by blocking the enzyme, I can increase the levels of acetylcholine, the more acetylcholine I have, the more receptors I can bind, and thus make acetylcholine more potent, thus shifting to the left.", "id": "T-acetylcholinesterase-inhibitor-2", "stem": "Acetylcholinesterase inhibitor means:", "options": [{"t": "Blocks the enzyme breaking down acetylcholine; acetylcholine rises and appears more potent.", "correct": true, "why": "That is acetylcholinesterase inhibitor (physostigmine)."}, {"t": "Blocks the transporter returning the neurotransmitter; more stays in the synapse, curve shifts left.", "correct": false, "why": "That is reuptake inhibitor (ssri / snri), not acetylcholinesterase inhibitor (physostigmine)."}, {"t": "Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam.", "correct": false, "why": "That is allosteric agonist (pam), not acetylcholinesterase inhibitor (physostigmine)."}, {"t": "Weak bonds, same pocket, binds and comes off; more agonist still reaches the maximum.", "correct": false, "why": "That is competitive (reversible) antagonist, not acetylcholinesterase inhibitor (physostigmine)."}], "teach": "Blocks the enzyme breaking down acetylcholine; acetylcholine rises and appears more potent. Any drug ending in -stigmine. Myasthenia gravis: about 90% autoimmune, antibodies target the nicotinic receptors of skeletal muscle (down-regulation), progressive weakness through the day.", "fg": "ind-ache", "dupOf": "T-acetylcholinesterase-inhibitor-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g3", "skill": "term", "concept": "term-acetylcholinesterase-inhibitor", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 12–13, 29; transcript 9/29", "quote": "by blocking the enzyme, I can increase the levels of acetylcholine, the more acetylcholine I have, the more receptors I can bind, and thus make acetylcholine more potent, thus shifting to the left.", "id": "T-acetylcholinesterase-inhibitor-3", "stem": "Which term is defined as: An indirect antagonist that blocks the enzyme on parasympathetic cell membranes that breaks down acetylcholine. Acetylcholine levels rise, more receptors are bound, and acetylcholine appears more potent (shift left). Used in myasthenia gravis?", "options": [{"t": "Acetylcholinesterase inhibitor", "correct": true, "why": "This is the definition of Acetylcholinesterase inhibitor (physostigmine)."}, {"t": "Symmetrical vs asymmetrical shifts", "correct": false, "why": "Symmetrical vs asymmetrical shifts: Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric."}, {"t": "Reuptake inhibitor", "correct": false, "why": "Reuptake inhibitor (SSRI / SNRI): Blocks the transporter returning the neurotransmitter; more stays in the synapse, curve shifts left."}, {"t": "Allosteric agonist", "correct": false, "why": "Allosteric agonist (PAM): Binds a second site and raises another drug’s affinity and/or efficacy, like diazepam."}], "teach": "Any drug ending in -stigmine. Myasthenia gravis: about 90% autoimmune, antibodies target the nicotinic receptors of skeletal muscle (down-regulation), progressive weakness through the day.", "fg": "ind-ache", "dupOf": "T-acetylcholinesterase-inhibitor-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-addition", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 30; transcript 9/29", "quote": "Result is equal to the sum of the individual effect", "id": "T-addition-1", "stem": "Which term fits this situation? Trimethoprim kills 50% of a bacterial colony and sulfamethoxazole kills 50%; given together they kill 100%, exactly the sum of the two.", "options": [{"t": "Addition", "correct": true, "why": "This situation is addition (drug–drug): Two drugs with the same effect; the result equals the sum of each."}, {"t": "Synergism", "correct": false, "why": "Synergism would be: Two drugs with the same effect; the result is greater than their sum."}, {"t": "Potentiation", "correct": false, "why": "Potentiation would be: One drug has no effect alone but increases the effect of another."}, {"t": "Side effect", "correct": false, "why": "Side effect (ADR) would be: An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known."}], "teach": "Two drugs with the same effect; the result equals the sum of each. One plus one equals two: two antibiotics each killing 50% of a colony kill 100% together."},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-addition", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 30; transcript 9/29", "quote": "Result is equal to the sum of the individual effect", "id": "T-addition-2", "stem": "Addition means:", "options": [{"t": "Two drugs with the same effect; the result equals the sum of each.", "correct": true, "why": "That is addition (drug–drug)."}, {"t": "Two drugs with the same effect; the result is greater than their sum.", "correct": false, "why": "That is synergism, not addition (drug–drug)."}, {"t": "One drug has no effect alone but increases the effect of another.", "correct": false, "why": "That is potentiation, not addition (drug–drug)."}, {"t": "An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known.", "correct": false, "why": "That is side effect (adr), not addition (drug–drug)."}], "teach": "Two drugs with the same effect; the result equals the sum of each. One plus one equals two: two antibiotics each killing 50% of a colony kill 100% together.", "dupOf": "T-addition-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-synergism", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 30; transcript 9/29", "quote": "So they both have an effect and when we put them together, they’re greater than the independently they do together.", "id": "T-synergism-1", "stem": "Which term fits this situation? Penicillin alone kills 30% of a Pseudomonas colony and gentamicin alone 50%; given together they kill 100%, more than the two numbers combined.", "options": [{"t": "Synergism", "correct": true, "why": "This situation is synergism: Two drugs with the same effect; the result is greater than their sum."}, {"t": "Potentiation", "correct": false, "why": "Potentiation would be: One drug has no effect alone but increases the effect of another."}, {"t": "Addition", "correct": false, "why": "Addition (drug–drug) would be: Two drugs with the same effect; the result equals the sum of each."}, {"t": "Mechanism of action", "correct": false, "why": "Mechanism of action (MOA) would be: Which receptor the drug binds and what it does there: activates, inhibits, binds."}], "teach": "Two drugs with the same effect; the result is greater than their sum. One plus one equals five: penicillin kills 30%, gentamicin 50%, together 100%. Both drugs have an effect by themselves, unlike potentiation."},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-synergism", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 30; transcript 9/29", "quote": "So they both have an effect and when we put them together, they’re greater than the independently they do together.", "id": "T-synergism-2", "stem": "Synergism means:", "options": [{"t": "Two drugs with the same effect; the result is greater than their sum.", "correct": true, "why": "That is synergism."}, {"t": "Which receptor the drug binds and what it does there: activates, inhibits, binds.", "correct": false, "why": "That is mechanism of action (moa), not synergism."}, {"t": "Two drugs with the same effect; the result equals the sum of each.", "correct": false, "why": "That is addition (drug–drug), not synergism."}, {"t": "One drug has no effect alone but increases the effect of another.", "correct": false, "why": "That is potentiation, not synergism."}], "teach": "Two drugs with the same effect; the result is greater than their sum. One plus one equals five: penicillin kills 30%, gentamicin 50%, together 100%. Both drugs have an effect by themselves, unlike potentiation.", "dupOf": "T-synergism-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-synergism", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 30; transcript 9/29", "quote": "So they both have an effect and when we put them together, they’re greater than the independently they do together.", "id": "T-synergism-3", "stem": "Which term is defined as: Two different drugs with the same effect are given together and the result is an effect greater in magnitude than the sum of each drug alone. Example: penicillin and gentamicin (antipseudomonal activity)?", "options": [{"t": "Synergism", "correct": true, "why": "This is the definition of Synergism."}, {"t": "Potentiation", "correct": false, "why": "Potentiation: One drug has no effect alone but increases the effect of another."}, {"t": "Addition", "correct": false, "why": "Addition (drug–drug): Two drugs with the same effect; the result equals the sum of each."}, {"t": "Mechanism of action", "correct": false, "why": "Mechanism of action (MOA): Which receptor the drug binds and what it does there: activates, inhibits, binds."}], "teach": "One plus one equals five: penicillin kills 30%, gentamicin 50%, together 100%. Both drugs have an effect by themselves, unlike potentiation.", "dupOf": "T-synergism-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-potentiation", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 31; transcript 9/29", "quote": "Here, one is neutral, has no effect by itself, but it can make the other a lot more potent.", "id": "T-potentiation-1", "stem": "Which term fits this situation? Carbidopa given by itself does nothing for a Parkinson’s patient, but given with dopa it blocks the breakdown of dopa in the gut and far more dopa reaches the brain.", "options": [{"t": "Potentiation", "correct": true, "why": "This situation is potentiation: One drug has no effect alone but increases the effect of another."}, {"t": "Indirect antagonist", "correct": false, "why": "Indirect antagonist would be: Binds upstream or downstream of the receptor, never the receptor; raises or lowers response."}, {"t": "Synergism", "correct": false, "why": "Synergism would be: Two drugs with the same effect; the result is greater than their sum."}, {"t": "Ligand", "correct": false, "why": "Ligand would be: Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food."}], "teach": "One drug has no effect alone but increases the effect of another. Carbidopa alone does nothing for a Parkinson’s patient; it is classified as an indirect antagonist."},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-potentiation", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 31; transcript 9/29", "quote": "Here, one is neutral, has no effect by itself, but it can make the other a lot more potent.", "id": "T-potentiation-2", "stem": "Potentiation means:", "options": [{"t": "One drug has no effect alone but increases the effect of another.", "correct": true, "why": "That is potentiation."}, {"t": "Two drugs with the same effect; the result is greater than their sum.", "correct": false, "why": "That is synergism, not potentiation."}, {"t": "Binds upstream or downstream of the receptor, never the receptor; raises or lowers response.", "correct": false, "why": "That is indirect antagonist, not potentiation."}, {"t": "Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food.", "correct": false, "why": "That is ligand, not potentiation."}], "teach": "One drug has no effect alone but increases the effect of another. Carbidopa alone does nothing for a Parkinson’s patient; it is classified as an indirect antagonist.", "dupOf": "T-potentiation-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-potentiation", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 31; transcript 9/29", "quote": "Here, one is neutral, has no effect by itself, but it can make the other a lot more potent.", "id": "T-potentiation-3", "stem": "Which term is defined as: One drug lacks an effect on its own but increases the effect of another. Example: carbidopa and dopa; carbidopa is an inactive analog that blocks the breakdown of dopa in the gut, so more reaches the brain?", "options": [{"t": "Potentiation", "correct": true, "why": "This is the definition of Potentiation."}, {"t": "Indirect antagonist", "correct": false, "why": "Indirect antagonist: Binds upstream or downstream of the receptor, never the receptor; raises or lowers response."}, {"t": "Synergism", "correct": false, "why": "Synergism: Two drugs with the same effect; the result is greater than their sum."}, {"t": "Ligand", "correct": false, "why": "Ligand: Any chemical a receptor recognizes and binds: hormone, neurotransmitter, drug, supplement, food."}], "teach": "Carbidopa alone does nothing for a Parkinson’s patient; it is classified as an indirect antagonist.", "dupOf": "T-potentiation-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-quantal-response", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 32–34; transcript 9/29", "quote": "Populations usually studied with “Quantal” response", "id": "T-quantal-response-1", "stem": "Which term fits this situation? Dogs each get a dose of epinephrine between 7.7 and 108 ng/kg/min and each is scored only as responding or not; the count responding at each dose forms a normal distribution, and the running total a sigmoid.", "options": [{"t": "Quantal response", "correct": true, "why": "This situation is quantal response: All-or-none in a population: alive or dead; cumulative plot gives a sigmoid."}, {"t": "Symmetrical vs asymmetrical shifts", "correct": false, "why": "Symmetrical vs asymmetrical shifts would be: Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric."}, {"t": "Graded response", "correct": false, "why": "Graded response would be: Measured in one biological unit on a continuous scale, rising by degrees with dose."}, {"t": "ED50 / LD50", "correct": false, "why": "ED50 / LD50 (population) would be: Doses treating 50% and killing 50% of a population on cumulative quantal curves."}], "teach": "All-or-none in a population: alive or dead; cumulative plot gives a sigmoid. Contrast the graded response measured on one sample (degree of contraction with nicotine, degree of paralysis by curare). The dogs and epinephrine (7.7–108 ng/kg/min) figure; ED50 ≈ 29 ng/kg/min."},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-quantal-response", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 32–34; transcript 9/29", "quote": "Populations usually studied with “Quantal” response", "id": "T-quantal-response-2", "stem": "Quantal response means:", "options": [{"t": "All-or-none in a population: alive or dead; cumulative plot gives a sigmoid.", "correct": true, "why": "That is quantal response."}, {"t": "Measured in one biological unit on a continuous scale, rising by degrees with dose.", "correct": false, "why": "That is graded response, not quantal response."}, {"t": "Doses treating 50% and killing 50% of a population on cumulative quantal curves.", "correct": false, "why": "That is ed50 / ld50 (population), not quantal response."}, {"t": "Once every allosteric site is occupied, more drug produces no further shift.", "correct": false, "why": "That is saturability (allosteric), not quantal response."}], "teach": "All-or-none in a population: alive or dead; cumulative plot gives a sigmoid. Contrast the graded response measured on one sample (degree of contraction with nicotine, degree of paralysis by curare). The dogs and epinephrine (7.7–108 ng/kg/min) figure; ED50 ≈ 29 ng/kg/min.", "dupOf": "T-quantal-response-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-quantal-response", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 32–34; transcript 9/29", "quote": "Populations usually studied with “Quantal” response", "id": "T-quantal-response-3", "stem": "Which term is defined as: All-or-none in a population: alive or dead; cumulative plot gives a sigmoid?", "options": [{"t": "Quantal response", "correct": true, "why": "This is the definition of Quantal response."}, {"t": "Symmetrical vs asymmetrical shifts", "correct": false, "why": "Symmetrical vs asymmetrical shifts: Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric."}, {"t": "Graded response", "correct": false, "why": "Graded response: Measured in one biological unit on a continuous scale, rising by degrees with dose."}, {"t": "ED50 / LD50", "correct": false, "why": "ED50 / LD50 (population): Doses treating 50% and killing 50% of a population on cumulative quantal curves."}], "teach": "Contrast the graded response measured on one sample (degree of contraction with nicotine, degree of paralysis by curare). The dogs and epinephrine (7.7–108 ng/kg/min) figure; ED50 ≈ 29 ng/kg/min.", "dupOf": "T-quantal-response-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-ed50-population", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 36–40; transcript 9/29", "quote": "Dose of the drug that protects 50% of the population (ED50) ... Dose of the drug that kills 50% of the population (LD50)", "id": "T-ed50-population-1", "stem": "Which term fits this situation? In a headache study, 325 mg of acetaminophen, the regular-strength tablet, relieves half the people; the dose that would kill half comes from animals or from overdoses reported after marketing.", "options": [{"t": "ED50 / LD50", "correct": true, "why": "This situation is ed50 / ld50 (population): Doses treating 50% and killing 50% of a population on cumulative quantal curves."}, {"t": "Apparent potency", "correct": false, "why": "Apparent potency would be: In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age."}, {"t": "EC50 / ED50", "correct": false, "why": "EC50 / ED50 would be: Concentration (or dose) producing 50% of the maximal response; smaller means more potent."}, {"t": "Potency", "correct": false, "why": "Potency (pharmacological) would be: How much drug is needed; a combination of affinity, efficacy and the tissue."}], "teach": "Doses treating 50% and killing 50% of a population on cumulative quantal curves. Acetaminophen headache study: ED50 ≈ 325 mg, the regular-strength tablet; > 4000 mg/day is liver toxicity. LD50 comes from animals or from overdoses after marketing (warfarin)."},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-ed50-population", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 36–40; transcript 9/29", "quote": "Dose of the drug that protects 50% of the population (ED50) ... Dose of the drug that kills 50% of the population (LD50)", "id": "T-ed50-population-2", "stem": "ED50 / LD50 means:", "options": [{"t": "Doses treating 50% and killing 50% of a population on cumulative quantal curves.", "correct": true, "why": "That is ed50 / ld50 (population)."}, {"t": "Concentration (or dose) producing 50% of the maximal response; smaller means more potent.", "correct": false, "why": "That is ec50 / ed50, not ed50 / ld50 (population)."}, {"t": "In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age.", "correct": false, "why": "That is apparent potency, not ed50 / ld50 (population)."}, {"t": "How much drug is needed; a combination of affinity, efficacy and the tissue.", "correct": false, "why": "That is potency (pharmacological), not ed50 / ld50 (population)."}], "teach": "Doses treating 50% and killing 50% of a population on cumulative quantal curves. Acetaminophen headache study: ED50 ≈ 325 mg, the regular-strength tablet; > 4000 mg/day is liver toxicity. LD50 comes from animals or from overdoses after marketing (warfarin).", "dupOf": "T-ed50-population-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-therapeutic-index", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 35, 39–41; transcript 9/29", "quote": "The larger the ratio the safer the drug", "id": "T-therapeutic-index-1", "stem": "Which term fits this situation? On the figure the curve for death crosses 50% at 160 mg and the curve for the desired effect at 10 mg; 160 divided by 10 gives 16. For codeine the number is huge for cough and tiny for pain.", "options": [{"t": "Therapeutic index", "correct": true, "why": "This situation is therapeutic index (ti): Lethal dose for 50% over effective dose for 50%; larger is safer."}, {"t": "Symmetrical vs asymmetrical shifts", "correct": false, "why": "Symmetrical vs asymmetrical shifts would be: Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric."}, {"t": "Saturability", "correct": false, "why": "Saturability (allosteric) would be: Once every allosteric site is occupied, more drug produces no further shift."}, {"t": "Emax", "correct": false, "why": "Emax (maximal response, ceiling) would be: The plateau: all receptors occupied or the physiological system maxed out."}], "teach": "Lethal dose for 50% over effective dose for 50%; larger is safer. Phenobarbital 40/4 = 10, alprazolam 2500; figure 160/10 = 16; hypnosis/death 400/100 = 4. Codeine has a huge TI for cough and a tiny one for pain: it is per effect measured. Distractors invert the ratio."},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-therapeutic-index", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 35, 39–41; transcript 9/29", "quote": "The larger the ratio the safer the drug", "id": "T-therapeutic-index-2", "stem": "Therapeutic index means:", "options": [{"t": "Lethal dose for 50% over effective dose for 50%; larger is safer.", "correct": true, "why": "That is therapeutic index (ti)."}, {"t": "Once every allosteric site is occupied, more drug produces no further shift.", "correct": false, "why": "That is saturability (allosteric), not therapeutic index (ti)."}, {"t": "The plateau: all receptors occupied or the physiological system maxed out.", "correct": false, "why": "That is emax (maximal response, ceiling), not therapeutic index (ti)."}, {"t": "The linear mid-section; greatest change in effect from the smallest change in dose.", "correct": false, "why": "That is slope, not therapeutic index (ti)."}], "teach": "Lethal dose for 50% over effective dose for 50%; larger is safer. Phenobarbital 40/4 = 10, alprazolam 2500; figure 160/10 = 16; hypnosis/death 400/100 = 4. Codeine has a huge TI for cough and a tiny one for pain: it is per effect measured. Distractors invert the ratio.", "dupOf": "T-therapeutic-index-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-therapeutic-index", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 35, 39–41; transcript 9/29", "quote": "The larger the ratio the safer the drug", "id": "T-therapeutic-index-3", "stem": "Which term is defined as: Lethal dose for 50% over effective dose for 50%; larger is safer?", "options": [{"t": "Therapeutic index", "correct": true, "why": "This is the definition of Therapeutic index (TI)."}, {"t": "Symmetrical vs asymmetrical shifts", "correct": false, "why": "Symmetrical vs asymmetrical shifts: Equal steps between curves mean an orthosteric competitor; unequal steps mean allosteric."}, {"t": "Saturability", "correct": false, "why": "Saturability (allosteric): Once every allosteric site is occupied, more drug produces no further shift."}, {"t": "Emax", "correct": false, "why": "Emax (maximal response, ceiling): The plateau: all receptors occupied or the physiological system maxed out."}], "teach": "Phenobarbital 40/4 = 10, alprazolam 2500; figure 160/10 = 16; hypnosis/death 400/100 = 4. Codeine has a huge TI for cough and a tiny one for pain: it is per effect measured. Distractors invert the ratio.", "dupOf": "T-therapeutic-index-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-safety-index", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 42; transcript 9/29", "quote": "For a drug to be safe the ED99 should be less than the LD1", "id": "T-safety-index-1", "stem": "Which term fits this situation? A sleeping drug: the dose that puts 99 of 100 patients to sleep is 10, and the dose that kills 1 of 100 is 1; dividing 1 by 10 gives 0.1, so one patient dies before everyone sleeps, though the 50% figures gave 1000.", "options": [{"t": "Safety index", "correct": true, "why": "This situation is safety index (safety ratio): Dose killing 1% divided by dose treating 99%; the tails, not the middles."}, {"t": "Therapeutic index", "correct": false, "why": "Therapeutic index (TI) would be: Lethal dose for 50% over effective dose for 50%; larger is safer."}, {"t": "Therapeutic window", "correct": false, "why": "Therapeutic window would be: The range of steady-state concentrations giving efficacy with minimal toxicity; not a ratio."}, {"t": "EC50 / ED50", "correct": false, "why": "EC50 / ED50 would be: Concentration (or dose) producing 50% of the maximal response; smaller means more potent."}], "teach": "Dose killing 1% divided by dose treating 99%; the tails, not the middles. Example: ED99 = 10, LD1 = 1 → SI = 1/10 = 0.1, not a safe drug even with TI = 100/0.1 = 1000."},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-safety-index", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 42; transcript 9/29", "quote": "For a drug to be safe the ED99 should be less than the LD1", "id": "T-safety-index-2", "stem": "Safety index means:", "options": [{"t": "Dose killing 1% divided by dose treating 99%; the tails, not the middles.", "correct": true, "why": "That is safety index (safety ratio)."}, {"t": "The range of steady-state concentrations giving efficacy with minimal toxicity; not a ratio.", "correct": false, "why": "That is therapeutic window, not safety index (safety ratio)."}, {"t": "Lethal dose for 50% over effective dose for 50%; larger is safer.", "correct": false, "why": "That is therapeutic index (ti), not safety index (safety ratio)."}, {"t": "Concentration (or dose) producing 50% of the maximal response; smaller means more potent.", "correct": false, "why": "That is ec50 / ed50, not safety index (safety ratio)."}], "teach": "Dose killing 1% divided by dose treating 99%; the tails, not the middles. Example: ED99 = 10, LD1 = 1 → SI = 1/10 = 0.1, not a safe drug even with TI = 100/0.1 = 1000.", "dupOf": "T-safety-index-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-safety-index", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 42; transcript 9/29", "quote": "For a drug to be safe the ED99 should be less than the LD1", "id": "T-safety-index-3", "stem": "Which term is defined as: Dose killing 1% divided by dose treating 99%; the tails, not the middles?", "options": [{"t": "Safety index", "correct": true, "why": "This is the definition of Safety index (safety ratio)."}, {"t": "Therapeutic index", "correct": false, "why": "Therapeutic index (TI): Lethal dose for 50% over effective dose for 50%; larger is safer."}, {"t": "Therapeutic window", "correct": false, "why": "Therapeutic window: The range of steady-state concentrations giving efficacy with minimal toxicity; not a ratio."}, {"t": "EC50 / ED50", "correct": false, "why": "EC50 / ED50: Concentration (or dose) producing 50% of the maximal response; smaller means more potent."}], "teach": "Example: ED99 = 10, LD1 = 1 → SI = 1/10 = 0.1, not a safe drug even with TI = 100/0.1 = 1000.", "dupOf": "T-safety-index-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-therapeutic-window", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 43; transcript 9/29", "quote": "Is the range of steady-state concentrations of drug that provides therapeutic efficacy with minimal toxicity", "id": "T-therapeutic-window-1", "stem": "Which term fits this situation? For a headache, the acceptable band of steady-state concentrations is narrow, since almost no toxicity is tolerated; for Hodgkin’s lymphoma a wider band is accepted because the disease is severe.", "options": [{"t": "Therapeutic window", "correct": true, "why": "This situation is therapeutic window: The range of steady-state concentrations giving efficacy with minimal toxicity; not a ratio."}, {"t": "Dose–response curve", "correct": false, "why": "Dose–response curve (DRC / CRC) would be: Log dose on the x-axis, percent of maximal effect on the y-axis; sigmoid."}, {"t": "Safety index", "correct": false, "why": "Safety index (safety ratio) would be: Dose killing 1% divided by dose treating 99%; the tails, not the middles."}, {"t": "Quantal response", "correct": false, "why": "Quantal response would be: All-or-none in a population: alive or dead; cumulative plot gives a sigmoid."}], "teach": "The range of steady-state concentrations giving efficacy with minimal toxicity; not a ratio. Knowing the TI and the SI gives the window in which it is safe to give the drug."},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-therapeutic-window", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 43; transcript 9/29", "quote": "Is the range of steady-state concentrations of drug that provides therapeutic efficacy with minimal toxicity", "id": "T-therapeutic-window-2", "stem": "Therapeutic window means:", "options": [{"t": "The range of steady-state concentrations giving efficacy with minimal toxicity; not a ratio.", "correct": true, "why": "That is therapeutic window."}, {"t": "In vivo potency: affinity and efficacy unchanged, but altered by absorption, elimination, age.", "correct": false, "why": "That is apparent potency, not therapeutic window."}, {"t": "Dose killing 1% divided by dose treating 99%; the tails, not the middles.", "correct": false, "why": "That is safety index (safety ratio), not therapeutic window."}, {"t": "All-or-none in a population: alive or dead; cumulative plot gives a sigmoid.", "correct": false, "why": "That is quantal response, not therapeutic window."}], "teach": "The range of steady-state concentrations giving efficacy with minimal toxicity; not a ratio. Knowing the TI and the SI gives the window in which it is safe to give the drug.", "dupOf": "T-therapeutic-window-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g4", "skill": "term", "concept": "term-therapeutic-window", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf page 43; transcript 9/29", "quote": "Is the range of steady-state concentrations of drug that provides therapeutic efficacy with minimal toxicity", "id": "T-therapeutic-window-3", "stem": "Which term is defined as: The range of steady-state concentrations giving efficacy with minimal toxicity; not a ratio?", "options": [{"t": "Therapeutic window", "correct": true, "why": "This is the definition of Therapeutic window."}, {"t": "Dose–response curve", "correct": false, "why": "Dose–response curve (DRC / CRC): Log dose on the x-axis, percent of maximal effect on the y-axis; sigmoid."}, {"t": "Safety index", "correct": false, "why": "Safety index (safety ratio): Dose killing 1% divided by dose treating 99%; the tails, not the middles."}, {"t": "Quantal response", "correct": false, "why": "Quantal response: All-or-none in a population: alive or dead; cumulative plot gives a sigmoid."}], "teach": "Knowing the TI and the SI gives the window in which it is safe to give the drug.", "dupOf": "T-therapeutic-window-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-side-effect", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 35, 44; transcript 9/29", "quote": "Undesired actions of drugs are commonly called side effects (or ADR)", "id": "T-side-effect-1", "stem": "Which term fits this situation? Sildenafil was studied to lower blood pressure, and the erection it also caused became the reason it is sold; minoxidil was a blood-pressure drug until the hair it grew became its use.", "options": [{"t": "Side effect", "correct": true, "why": "This situation is side effect (adr): An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known."}, {"t": "Therapeutic index", "correct": false, "why": "Therapeutic index (TI) would be: Lethal dose for 50% over effective dose for 50%; larger is safer."}, {"t": "Natural dietary supplement", "correct": false, "why": "Natural dietary supplement (NDS) would be: Regulated as food, not as a drug; the label cannot claim to cure."}, {"t": "Addition", "correct": false, "why": "Addition (drug–drug) would be: Two drugs with the same effect; the result equals the sum of each."}], "teach": "An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known. Sildenafil (studied for blood pressure, marketed for the erectile side effect) and minoxidil (blood pressure, then hair loss): which action is the effect depends on what you are treating."},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-side-effect", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 35, 44; transcript 9/29", "quote": "Undesired actions of drugs are commonly called side effects (or ADR)", "id": "T-side-effect-2", "stem": "Side effect means:", "options": [{"t": "An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known.", "correct": true, "why": "That is side effect (adr)."}, {"t": "Continued exposure to the same concentration gives a diminished effect; the clinical manifestation.", "correct": false, "why": "That is tolerance, not side effect (adr)."}, {"t": "Lethal dose for 50% over effective dose for 50%; larger is safer.", "correct": false, "why": "That is therapeutic index (ti), not side effect (adr)."}, {"t": "Regulated as food, not as a drug; the label cannot claim to cure.", "correct": false, "why": "That is natural dietary supplement (nds), not side effect (adr)."}], "teach": "An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known. Sildenafil (studied for blood pressure, marketed for the erectile side effect) and minoxidil (blood pressure, then hair loss): which action is the effect depends on what you are treating.", "dupOf": "T-side-effect-1"},
{"lecture": "L05", "prof": "Gottlieb", "tier": "new", "topic": "TERMS", "sub": "g1", "skill": "term", "concept": "term-side-effect", "tags": ["term"], "source": "both", "cite": "Pharmacodynamics-Day_4_-_5_2026s_pptx Part 2.pdf pages 35, 44; transcript 9/29", "quote": "Undesired actions of drugs are commonly called side effects (or ADR)", "id": "T-side-effect-3", "stem": "Which term is defined as: An undesired action of the drug; predictable once the ligand’s receptor pharmacology is known?", "options": [{"t": "Side effect", "correct": true, "why": "This is the definition of Side effect (ADR)."}, {"t": "Therapeutic index", "correct": false, "why": "Therapeutic index (TI): Lethal dose for 50% over effective dose for 50%; larger is safer."}, {"t": "Natural dietary supplement", "correct": false, "why": "Natural dietary supplement (NDS): Regulated as food, not as a drug; the label cannot claim to cure."}, {"t": "Addition", "correct": false, "why": "Addition (drug–drug): Two drugs with the same effect; the result equals the sum of each."}], "teach": "Sildenafil (studied for blood pressure, marketed for the erectile side effect) and minoxidil (blood pressure, then hair loss): which action is the effect depends on what you are treating.", "dupOf": "T-side-effect-1"});
